// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IPolicyWebAuthn {
    struct Assertion {
        bytes authenticatorData;
        bytes clientDataJSON;
        uint256 r;
        uint256 s;
    }

    function verify(bytes32 challenge, Assertion calldata a, uint256 x, uint256 y, bytes32 rpIdHash, bool requireUV)
        external view returns (bool);
}

/// @title CosignCommittee: runners that co-sign large agent transactions
/// @notice A k-of-n set of runner keys, chosen by governance (the chain's gov
///         module through a MsgEVMCall proposal, or a SimpleMultisig). A
///         member signs a co-sign digest only after running Neuro's checks
///         on the transaction (`zetaphy cosign`); isValid() counts distinct
///         member signatures (signers in ascending order, no repeats).
///         k-of-n separate ECDSA signatures, not a threshold-cryptography
///         signature: simple and checkable, at the cost of k signatures of gas.
contract CosignCommittee {
    uint256 public constant MAX_MEMBERS = 32;

    address public governance;
    mapping(address => bool) public isMember;
    address[] private memberList;
    uint256 public threshold;

    event MembersSet(address[] members, uint256 threshold);
    event GovernanceChanged(address governance);

    error NotGovernance();
    error BadMembers();

    constructor(address governance_, address[] memory initialMembers, uint256 threshold_) {
        governance = governance_;
        _set(initialMembers, threshold_);
    }

    function setMembers(address[] calldata newMembers, uint256 threshold_) external {
        if (msg.sender != governance) revert NotGovernance();
        _set(newMembers, threshold_);
    }

    function setGovernance(address g) external {
        if (msg.sender != governance) revert NotGovernance();
        governance = g;
        emit GovernanceChanged(g);
    }

    function members() external view returns (address[] memory) {
        return memberList;
    }

    /// True when at least `threshold` distinct members signed `digest` (65-byte ECDSA each, signers ascending).
    function isValid(bytes32 digest, bytes[] calldata sigs) external view returns (bool) {
        if (threshold == 0) return false;
        uint256 count;
        address last;
        for (uint256 i = 0; i < sigs.length; i++) {
            address s = _recover(digest, sigs[i]);
            if (s <= last) return false; // ascending: no signer counted twice
            last = s;
            if (isMember[s]) count++;
        }
        return count >= threshold;
    }

    function _set(address[] memory members_, uint256 threshold_) private {
        if (members_.length > MAX_MEMBERS || threshold_ == 0 || threshold_ > members_.length) revert BadMembers();
        for (uint256 i = 0; i < memberList.length; i++) isMember[memberList[i]] = false;
        delete memberList;
        for (uint256 i = 0; i < members_.length; i++) {
            if (members_[i] == address(0) || isMember[members_[i]]) revert BadMembers();
            isMember[members_[i]] = true;
            memberList.push(members_[i]);
        }
        threshold = threshold_;
        emit MembersSet(members_, threshold_);
    }

    function _recover(bytes32 d, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) return address(0);
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (v < 27) v += 27;
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) return address(0);
        return ecrecover(d, v, r, s);
    }
}

interface ICosignCommittee {
    function isValid(bytes32 digest, bytes[] calldata sigs) external view returns (bool);
}

/// @title AgentPolicyWallet: a wallet an AI agent runs inside guardrails (testnet)
/// @notice The owner (a person) holds the funds and sets the policy; the agent
///         key can only act inside it:
///           - spend caps per period, per token (address 0 = the native coin),
///             counting native value, ERC-20 transfer amounts and approvals;
///             a token without a cap cannot be moved by the agent at all;
///           - allow-listed recipients (native sends and ERC-20 transfers) and
///             contracts (any other call, and approval spenders);
///             transferFrom, increaseAllowance, setApprovalForAll and permit
///             are refused outright;
///           - above a per-token threshold ("cosignAbove"), an action either
///             waits in a timelock (queue, then executeQueued after `delay`;
///             the owner may cancel) or carries co-signatures of the runner
///             committee (CosignCommittee, set by governance) that ran Neuro
///             checks on it (executeCosigned). Caps still apply to both;
///           - emergency freeze: the owner's account, the owner's passkey
///             (WebAuthn, P-256 precompile via WebAuthnVerifier) or the
///             owner's ML-DSA-44 key (precompile 0x…0900) stops the agent at
///             once; passkey and PQ freezes are signed messages anyone can
///             relay. Only the owner's account unfreezes.
///         Every agent action logs (modelHash, promptHash) provenance.
///         The owner itself is not limited (ownerExecute), so it can always
///         take the funds back, frozen or not.
contract AgentPolicyWallet {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;

    bytes4 private constant TRANSFER = 0xa9059cbb;
    bytes4 private constant APPROVE = 0x095ea7b3;
    bytes4 private constant TRANSFER_FROM = 0x23b872dd;
    bytes4 private constant INCREASE_ALLOWANCE = 0x39509351;
    bytes4 private constant SET_APPROVAL_FOR_ALL = 0xa22cb465;
    bytes4 private constant PERMIT = 0xd505accf;
    uint256 public constant MAX_DELAY = 30 days;

    struct Limit {
        bool set;
        uint256 perPeriod;
        uint256 cosignAbove; // amounts above this need the timelock or the committee
        uint256 spent;
        uint64 windowStart;
    }

    address public owner;
    address public agent;
    ICosignCommittee public committee;
    IPolicyWebAuthn public webauthn;

    bytes32 public pqKeyHash;   // owner's ML-DSA-44 key (0 = none)
    uint256 public passkeyX;    // owner's passkey (0,0 = none)
    uint256 public passkeyY;
    bytes32 public rpIdHash;

    bool public frozen;
    uint256 public freezeNonce;
    uint256 public cosignNonce;
    uint256 public period;
    uint256 public delay;
    uint256 public queueCount;

    mapping(address => Limit) public limits;
    mapping(address => bool) public allowedTarget;
    mapping(address => bool) public allowedRecipient;
    mapping(bytes32 => uint64) public queuedAt; // id -> ready time (0 = none)

    event AgentAction(address indexed to, uint256 value, bytes4 selector, address token, uint256 amount, bytes32 modelHash, bytes32 promptHash, uint8 path);
    event Queued(bytes32 indexed id, uint256 seq, address to, uint256 value, bytes data, bytes32 modelHash, bytes32 promptHash, uint64 readyAt);
    event Cancelled(bytes32 indexed id);
    event Frozen(address by, uint8 how);
    event Unfrozen();
    event LimitSet(address indexed token, uint256 perPeriod, uint256 cosignAbove);
    event AllowSet(address indexed who, bool target, bool recipient);
    event ConfigSet(address agent, address committee, uint256 period, uint256 delay);
    event EmergencyKeysSet(bytes32 pqKeyHash, uint256 passkeyX, uint256 passkeyY, bytes32 rpIdHash);
    event OwnerChanged(address owner);

    error NotOwner();
    error NotAgent();
    error IsFrozen();
    error NotAllowed(address who);
    error Forbidden(bytes4 selector);
    error NoLimit(address token);
    error OverCap(address token, uint256 spent, uint256 cap);
    error NeedsDelayOrCosign(address token, uint256 amount);
    error NotQueued();
    error NotReady();
    error BadCosign();
    error Expired();
    error BadEmergencyKey();
    error BadConfig();
    error CallFailed(bytes reason);

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier onlyAgent() {
        if (msg.sender != agent) revert NotAgent();
        if (frozen) revert IsFrozen();
        _;
    }

    constructor(address owner_, address agent_, address committee_, address webauthn_, uint256 period_, uint256 delay_) payable {
        owner = owner_;
        webauthn = IPolicyWebAuthn(webauthn_);
        _config(agent_, committee_, period_, delay_);
    }

    receive() external payable {}

    // ------------------------------------------------------------- agent

    /// Within caps, allow-lists and below every cosignAbove: runs at once.
    function execute(address to, uint256 value, bytes calldata data, bytes32 modelHash, bytes32 promptHash)
        external onlyAgent returns (bytes memory)
    {
        (address token, uint256 amount) = _classify(to, value, data);
        if (amount != 0 && !limits[token].set) revert NoLimit(token);
        if (amount > limits[token].cosignAbove) revert NeedsDelayOrCosign(token, amount);
        return _run(to, value, data, token, amount, modelHash, promptHash, 0);
    }

    /// Above a threshold, path 1: wait `delay`, during which the owner sees it and may cancel or freeze.
    function queue(address to, uint256 value, bytes calldata data, bytes32 modelHash, bytes32 promptHash)
        external onlyAgent returns (bytes32 id)
    {
        _classify(to, value, data); // allow-lists checked now too, so a bad action fails early
        uint256 seq = ++queueCount;
        id = keccak256(abi.encode(seq, to, value, keccak256(data), modelHash, promptHash));
        uint64 readyAt = uint64(block.timestamp + delay);
        queuedAt[id] = readyAt;
        emit Queued(id, seq, to, value, data, modelHash, promptHash, readyAt);
    }

    function executeQueued(uint256 seq, address to, uint256 value, bytes calldata data, bytes32 modelHash, bytes32 promptHash)
        external onlyAgent returns (bytes memory)
    {
        bytes32 id = keccak256(abi.encode(seq, to, value, keccak256(data), modelHash, promptHash));
        uint64 readyAt = queuedAt[id];
        if (readyAt == 0) revert NotQueued();
        if (block.timestamp < readyAt) revert NotReady();
        delete queuedAt[id];
        (address token, uint256 amount) = _classify(to, value, data);
        return _run(to, value, data, token, amount, modelHash, promptHash, 1);
    }

    /// The digest committee members sign for one large action (raw 32 bytes, no EIP-191 prefix;
    /// bound to this chain, this wallet and cosignNonce). src/cosign.js computes the same.
    function cosignDigest(address to, uint256 value, bytes calldata data, bytes32 reportHash, uint256 deadline)
        public view returns (bytes32)
    {
        return keccak256(abi.encode("ZETAPHY AgentCosign", block.chainid, address(this), cosignNonce, to, value,
            keccak256(data), reportHash, deadline));
    }

    /// Above a threshold, path 2: no wait, with the committee's co-signatures
    /// (reportHash = the Neuro report the runners checked).
    function executeCosigned(
        address to,
        uint256 value,
        bytes calldata data,
        bytes32 modelHash,
        bytes32 promptHash,
        bytes32 reportHash,
        uint256 deadline,
        bytes[] calldata sigs
    ) external onlyAgent returns (bytes memory) {
        if (block.timestamp > deadline) revert Expired();
        if (address(committee) == address(0) || !committee.isValid(cosignDigest(to, value, data, reportHash, deadline), sigs)) revert BadCosign();
        cosignNonce++;
        (address token, uint256 amount) = _classify(to, value, data);
        return _run(to, value, data, token, amount, modelHash, promptHash, 2);
    }

    // ------------------------------------------------------------- emergency freeze

    /// The 32 bytes the owner's passkey or ML-DSA key signs to freeze the wallet.
    function freezeChallenge() public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY freeze", block.chainid, address(this), freezeNonce));
    }

    function freeze() external onlyOwner {
        _freeze(0);
    }

    function freezeWithPasskey(IPolicyWebAuthn.Assertion calldata assertion) external {
        if (passkeyX == 0 && passkeyY == 0) revert BadEmergencyKey();
        if (!webauthn.verify(freezeChallenge(), assertion, passkeyX, passkeyY, rpIdHash, true)) revert BadEmergencyKey();
        _freeze(1);
    }

    function freezeWithPq(bytes calldata pqPublicKey, bytes calldata pqSig) external {
        if (pqKeyHash == bytes32(0) || keccak256(pqPublicKey) != pqKeyHash) revert BadEmergencyKey();
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(uint8(44), freezeChallenge(), pqPublicKey, pqSig));
        if (!ok || ret.length != 32 || uint256(bytes32(ret)) != 1) revert BadEmergencyKey();
        _freeze(2);
    }

    function unfreeze() external onlyOwner {
        frozen = false;
        emit Unfrozen();
    }

    // ------------------------------------------------------------- owner

    function ownerExecute(address to, uint256 value, bytes calldata data) external onlyOwner returns (bytes memory ret) {
        bool ok;
        (ok, ret) = to.call{value: value}(data);
        if (!ok) revert CallFailed(ret);
    }

    function cancel(bytes32 id) external onlyOwner {
        if (queuedAt[id] == 0) revert NotQueued();
        delete queuedAt[id];
        emit Cancelled(id);
    }

    function setLimit(address token, uint256 perPeriod, uint256 cosignAbove) external onlyOwner {
        Limit storage l = limits[token];
        l.set = true;
        l.perPeriod = perPeriod;
        l.cosignAbove = cosignAbove;
        emit LimitSet(token, perPeriod, cosignAbove);
    }

    function setAllowed(address who, bool target, bool recipient) external onlyOwner {
        allowedTarget[who] = target;
        allowedRecipient[who] = recipient;
        emit AllowSet(who, target, recipient);
    }

    function setConfig(address agent_, address committee_, uint256 period_, uint256 delay_) external onlyOwner {
        _config(agent_, committee_, period_, delay_);
    }

    function setEmergencyKeys(bytes32 pqKeyHash_, uint256 x, uint256 y, bytes32 rpIdHash_) external onlyOwner {
        pqKeyHash = pqKeyHash_;
        passkeyX = x;
        passkeyY = y;
        rpIdHash = rpIdHash_;
        emit EmergencyKeysSet(pqKeyHash_, x, y, rpIdHash_);
    }

    function setOwner(address o) external onlyOwner {
        if (o == address(0)) revert BadConfig();
        owner = o;
        emit OwnerChanged(o);
    }

    /// What is left of a token's cap in the current period.
    function remaining(address token) external view returns (uint256) {
        Limit storage l = limits[token];
        if (!l.set) return 0;
        uint256 spent = block.timestamp >= l.windowStart + period ? 0 : l.spent;
        return spent >= l.perPeriod ? 0 : l.perPeriod - spent;
    }

    // ------------------------------------------------------------- internals

    function _config(address agent_, address committee_, uint256 period_, uint256 delay_) private {
        if (period_ == 0 || delay_ > MAX_DELAY) revert BadConfig();
        agent = agent_;
        committee = ICosignCommittee(committee_);
        period = period_;
        delay = delay_;
        emit ConfigSet(agent_, committee_, period_, delay_);
    }

    function _freeze(uint8 how) private {
        frozen = true;
        freezeNonce++;
        emit Frozen(msg.sender, how);
    }

    /// Which token an action moves and how much, after the allow-list checks.
    function _classify(address to, uint256 value, bytes calldata data) private view returns (address token, uint256 amount) {
        if (data.length == 0) {
            if (!allowedRecipient[to] && !allowedTarget[to]) revert NotAllowed(to);
            return (address(0), value);
        }
        bytes4 sel = data.length >= 4 ? bytes4(data[0:4]) : bytes4(0);
        if (sel == TRANSFER_FROM || sel == INCREASE_ALLOWANCE || sel == SET_APPROVAL_FOR_ALL || sel == PERMIT) revert Forbidden(sel);
        if (sel == TRANSFER || sel == APPROVE) {
            if (value != 0 || data.length < 68) revert Forbidden(sel);
            (address who, uint256 amt) = abi.decode(data[4:68], (address, uint256));
            if (sel == TRANSFER ? !allowedRecipient[who] : !allowedTarget[who]) revert NotAllowed(who);
            if (!limits[to].set) revert NoLimit(to);
            return (to, amt);
        }
        if (!allowedTarget[to]) revert NotAllowed(to);
        return (address(0), value);
    }

    function _run(address to, uint256 value, bytes calldata data, address token, uint256 amount, bytes32 modelHash, bytes32 promptHash, uint8 path)
        private returns (bytes memory ret)
    {
        if (amount != 0) {
            Limit storage l = limits[token];
            if (!l.set) revert NoLimit(token);
            if (block.timestamp >= l.windowStart + period) {
                l.windowStart = uint64(block.timestamp);
                l.spent = 0;
            }
            uint256 spent = l.spent + amount;
            if (spent > l.perPeriod) revert OverCap(token, spent, l.perPeriod);
            l.spent = spent;
        }
        bool ok;
        (ok, ret) = to.call{value: value}(data);
        if (!ok) revert CallFailed(ret);
        emit AgentAction(to, value, data.length >= 4 ? bytes4(data[0:4]) : bytes4(0), token, amount, modelHash, promptHash, path);
    }
}

contracts/AgentRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// A deterministic policy checker: given an action an agent recorded, the
/// agent's constitution (the document whose keccak256 the agent registered)
/// and optional evidence, says whether the action broke the policy, who was
/// harmed and how much. It must be a pure function of its inputs.
interface IPolicyChecker {
    struct ActionView {
        uint256 agentId;
        address target;
        uint256 value;
        bytes32 dataHash;
        bytes32 modelHash;
        bytes32 promptHash;
        uint64 time;
    }

    function check(ActionView calldata action, bytes calldata constitution, bytes calldata evidence)
        external view returns (bool violated, address victim, uint256 damage);
}

/// @title AgentRegistry: AI agents with an identity, a bond and liability (testnet)
/// @notice An agent is registered by its operator (who answers for it) with:
///           - the EVM account it transacts from (for human/agent labels),
///           - an ML-DSA-44 public key (only its keccak256 is stored; the key
///             rides in calldata, as in QuantumWallet) that signs every action
///             it records, checked by ZETAPHY's precompile at 0x…0900,
///           - a bond in testnet ZETAPHY (at least minBond),
///           - a constitution: the keccak256 of its policy document, and an
///             optional deterministic checker contract for that policy.
///         Each recorded action carries provenance: the hash of the model
///         (weights or model id + version) and of the prompt that produced it.
///
///         Claims, when an action broke the policy:
///           - checker path: anyone shows the constitution document; the
///             agent's checker decides deterministically, and the damage (at
///             most the bond) is paid to the victim the checker names, at once;
///           - committee path: a claimant posts claimDeposit and an evidence
///             hash; governance's claims committee votes; threshold "yes"
///             pays the claimed amount (at most the bond) to the claimant and
///             returns the deposit; threshold "no", or no decision within
///             VOTE_PERIOD, rejects it and the deposit goes to the operator.
///         The operator can take the bond back only UNBOND_DELAY after asking,
///         with no open claim; claims on an action are open for CLAIM_WINDOW.
contract AgentRegistry {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;
    uint8 public constant PQ_VARIANT = 44;
    uint256 public constant UNBOND_DELAY = 7 days;
    uint256 public constant CLAIM_WINDOW = 30 days;
    uint256 public constant VOTE_PERIOD = 7 days;
    uint256 public constant MAX_COMMITTEE = 32;

    struct Agent {
        address operator;
        address account;
        bytes32 pqKeyHash;
        bytes32 constitution;
        address checker;
        uint256 bond;
        uint64 unbondAt;   // 0 = not unbonding
        uint64 actions;    // per-agent sequence, in every action digest (no replay)
        uint32 openClaims;
    }

    struct Action {
        uint256 agentId;
        address target;
        uint256 value;
        bytes32 dataHash;
        bytes32 modelHash;
        bytes32 promptHash;
        bytes32 constitution; // the agent's constitution when it acted
        address checker;      // and its checker
        uint64 time;
        bool slashed;         // a checker claim was paid (one payout per action)
    }

    enum ClaimState { None, Open, Upheld, Rejected }

    struct Claim {
        uint256 actionId;
        address claimant;
        uint256 amount;
        uint256 deposit;
        bytes32 evidenceHash;
        uint64 opened;
        uint16 yes;
        uint16 no;
        ClaimState state;
    }

    address public governance;
    uint256 public minBond;
    uint256 public claimDeposit;

    uint256 public agentCount;
    mapping(uint256 => Agent) public agents;
    mapping(address => uint256) public agentOfAccount; // account -> agent id (0 = none)

    uint256 public actionCount;
    mapping(uint256 => Action) public actions;

    uint256 public claimCount;
    mapping(uint256 => Claim) public claims;
    mapping(uint256 => mapping(address => bool)) public voted;

    mapping(address => bool) public isCommittee;
    address[] private committee;
    uint256 public committeeThreshold;

    event AgentRegistered(uint256 indexed id, address indexed operator, address indexed account, bytes32 pqKeyHash, bytes32 constitution, address checker, uint256 bond);
    event AgentUpdated(uint256 indexed id, bytes32 pqKeyHash, bytes32 constitution, address checker);
    event BondAdded(uint256 indexed id, uint256 amount, uint256 bond);
    event UnbondRequested(uint256 indexed id, uint64 at);
    event BondWithdrawn(uint256 indexed id, uint256 amount);
    event ActionRecorded(uint256 indexed agentId, uint256 indexed actionId, ActionInput action);
    event Slashed(uint256 indexed agentId, uint256 indexed actionId, address indexed to, uint256 amount);
    event ClaimFiled(uint256 indexed claimId, uint256 indexed actionId, address indexed claimant, uint256 amount, bytes32 evidenceHash);
    event ClaimVoted(uint256 indexed claimId, address indexed member, bool uphold);
    event ClaimClosed(uint256 indexed claimId, ClaimState state, uint256 paid);
    event CommitteeSet(address[] members, uint256 threshold);
    event ParamsSet(uint256 minBond, uint256 claimDeposit);
    event GovernanceChanged(address governance);

    error NotGovernance();
    error NotOperator();
    error BondTooLow();
    error BadAccount();
    error AccountTaken();
    error NoAgent();
    error Inactive();
    error WrongKey();
    error BadPq();
    error Unbonding();
    error NotYet();
    error OpenClaims();
    error NoAction();
    error ClaimWindowOver();
    error BadConstitution();
    error NoChecker();
    error NotViolated();
    error AlreadySlashed();
    error BadDeposit();
    error NotCommittee();
    error AlreadyVoted();
    error ClaimNotOpen();
    error BadCommittee();
    error TransferFailed();

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    constructor(address governance_, uint256 minBond_, uint256 claimDeposit_) {
        governance = governance_;
        minBond = minBond_;
        claimDeposit = claimDeposit_;
        emit ParamsSet(minBond_, claimDeposit_);
    }

    // ------------------------------------------------------------- agents

    function register(address account, bytes32 pqKeyHash, bytes32 constitution, address checker) external payable returns (uint256 id) {
        if (msg.value < minBond) revert BondTooLow();
        if (account == address(0) || pqKeyHash == bytes32(0)) revert BadAccount();
        if (agentOfAccount[account] != 0) revert AccountTaken();
        id = ++agentCount;
        agents[id] = Agent({operator: msg.sender, account: account, pqKeyHash: pqKeyHash, constitution: constitution,
            checker: checker, bond: msg.value, unbondAt: 0, actions: 0, openClaims: 0});
        agentOfAccount[account] = id;
        emit AgentRegistered(id, msg.sender, account, pqKeyHash, constitution, checker, msg.value);
    }

    /// New key, constitution or checker. Past actions keep the constitution
    /// and checker they were recorded under.
    function update(uint256 id, bytes32 pqKeyHash, bytes32 constitution, address checker) external {
        Agent storage a = _operated(id);
        if (pqKeyHash == bytes32(0)) revert BadAccount();
        a.pqKeyHash = pqKeyHash;
        a.constitution = constitution;
        a.checker = checker;
        emit AgentUpdated(id, pqKeyHash, constitution, checker);
    }

    function addBond(uint256 id) external payable {
        Agent storage a = agents[id];
        if (a.operator == address(0)) revert NoAgent();
        a.bond += msg.value;
        emit BondAdded(id, msg.value, a.bond);
    }

    /// Stops new actions; the bond can be withdrawn UNBOND_DELAY later.
    function requestUnbond(uint256 id) external {
        Agent storage a = _operated(id);
        if (a.unbondAt != 0) revert Unbonding();
        a.unbondAt = uint64(block.timestamp + UNBOND_DELAY);
        emit UnbondRequested(id, a.unbondAt);
    }

    function withdrawBond(uint256 id) external {
        Agent storage a = _operated(id);
        if (a.unbondAt == 0 || block.timestamp < a.unbondAt) revert NotYet();
        if (a.openClaims != 0) revert OpenClaims();
        uint256 amount = a.bond;
        a.bond = 0;
        delete agentOfAccount[a.account];
        emit BondWithdrawn(id, amount);
        _pay(a.operator, amount);
    }

    /// Active = bonded at least minBond and not unbonding.
    function isActive(uint256 id) public view returns (bool) {
        Agent storage a = agents[id];
        return a.operator != address(0) && a.unbondAt == 0 && a.bond >= minBond;
    }

    /// For label readers: the active agent an account belongs to (0 = none).
    function activeAgentOf(address account) external view returns (uint256) {
        uint256 id = agentOfAccount[account];
        return id != 0 && isActive(id) ? id : 0;
    }

    // ------------------------------------------------------------- actions

    /// What an agent did (or is about to do), with its provenance.
    struct ActionInput {
        address target;
        uint256 value;
        bytes32 dataHash;   // keccak256 of the calldata (or of an off-chain action's description)
        bytes32 modelHash;  // keccak256 of the model weights, or of "provider/model-id@version"
        bytes32 promptHash; // keccak256 of the full prompt (system + user) that produced the action
    }

    /// The 32 bytes the agent's ML-DSA-44 key signs for its next action.
    function actionDigest(uint256 id, ActionInput calldata x) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY AgentAction", block.chainid, address(this), id, agents[id].actions,
            x.target, x.value, x.dataHash, x.modelHash, x.promptHash));
    }

    /// Records one action with its provenance. Anyone may submit it (a relay);
    /// only the agent's ML-DSA key can have signed it.
    function recordAction(uint256 id, ActionInput calldata x, bytes calldata pqPublicKey, bytes calldata pqSig)
        external returns (uint256 actionId)
    {
        Agent storage a = agents[id];
        if (a.operator == address(0)) revert NoAgent();
        if (!isActive(id)) revert Inactive();
        if (keccak256(pqPublicKey) != a.pqKeyHash) revert WrongKey();
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(PQ_VARIANT, actionDigest(id, x), pqPublicKey, pqSig));
        if (!ok || ret.length != 32 || uint256(bytes32(ret)) != 1) revert BadPq();
        a.actions++;
        actionId = ++actionCount;
        Action storage r = actions[actionId];
        r.agentId = id;
        r.target = x.target;
        r.value = x.value;
        r.dataHash = x.dataHash;
        r.modelHash = x.modelHash;
        r.promptHash = x.promptHash;
        r.constitution = a.constitution;
        r.checker = a.checker;
        r.time = uint64(block.timestamp);
        emit ActionRecorded(id, actionId, x);
    }

    // ------------------------------------------------------------- claims: deterministic checker

    /// Shows the constitution an action was recorded under; if the agent's
    /// checker finds a violation, the damage (at most the bond) goes to the
    /// victim the checker names. Anyone may call it; one payout per action.
    function claimByChecker(uint256 actionId, bytes calldata constitution, bytes calldata evidence) external returns (uint256 paid) {
        Action storage act = _claimable(actionId);
        if (act.checker == address(0)) revert NoChecker();
        if (act.slashed) revert AlreadySlashed();
        if (keccak256(constitution) != act.constitution) revert BadConstitution();
        IPolicyChecker.ActionView memory v = IPolicyChecker.ActionView({agentId: act.agentId, target: act.target,
            value: act.value, dataHash: act.dataHash, modelHash: act.modelHash, promptHash: act.promptHash, time: act.time});
        (bool violated, address victim, uint256 damage) = IPolicyChecker(act.checker).check(v, constitution, evidence);
        if (!violated || victim == address(0) || damage == 0) revert NotViolated();
        act.slashed = true;
        paid = _slash(act.agentId, actionId, victim, damage);
    }

    // ------------------------------------------------------------- claims: committee vote

    function fileClaim(uint256 actionId, uint256 amount, bytes32 evidenceHash) external payable returns (uint256 claimId) {
        Action storage act = _claimable(actionId);
        if (msg.value != claimDeposit) revert BadDeposit();
        claimId = ++claimCount;
        claims[claimId] = Claim({actionId: actionId, claimant: msg.sender, amount: amount, deposit: msg.value,
            evidenceHash: evidenceHash, opened: uint64(block.timestamp), yes: 0, no: 0, state: ClaimState.Open});
        agents[act.agentId].openClaims++;
        emit ClaimFiled(claimId, actionId, msg.sender, amount, evidenceHash);
    }

    function vote(uint256 claimId, bool uphold) external {
        if (!isCommittee[msg.sender]) revert NotCommittee();
        Claim storage c = claims[claimId];
        if (c.state != ClaimState.Open || block.timestamp > c.opened + VOTE_PERIOD) revert ClaimNotOpen();
        if (voted[claimId][msg.sender]) revert AlreadyVoted();
        voted[claimId][msg.sender] = true;
        if (uphold) c.yes++; else c.no++;
        emit ClaimVoted(claimId, msg.sender, uphold);
        if (c.yes >= committeeThreshold) _close(claimId, true);
        else if (c.no >= committeeThreshold) _close(claimId, false);
    }

    /// After VOTE_PERIOD without a decision, anyone may close the claim as rejected.
    function expireClaim(uint256 claimId) external {
        Claim storage c = claims[claimId];
        if (c.state != ClaimState.Open) revert ClaimNotOpen();
        if (block.timestamp <= c.opened + VOTE_PERIOD) revert NotYet();
        _close(claimId, false);
    }

    // ------------------------------------------------------------- governance

    function setCommittee(address[] calldata members, uint256 threshold) external onlyGovernance {
        if (members.length > MAX_COMMITTEE || threshold == 0 || threshold > members.length) revert BadCommittee();
        for (uint256 i = 0; i < committee.length; i++) isCommittee[committee[i]] = false;
        delete committee;
        for (uint256 i = 0; i < members.length; i++) {
            if (members[i] == address(0) || isCommittee[members[i]]) revert BadCommittee();
            isCommittee[members[i]] = true;
            committee.push(members[i]);
        }
        committeeThreshold = threshold;
        emit CommitteeSet(members, threshold);
    }

    function committeeMembers() external view returns (address[] memory) {
        return committee;
    }

    function setParams(uint256 minBond_, uint256 claimDeposit_) external onlyGovernance {
        minBond = minBond_;
        claimDeposit = claimDeposit_;
        emit ParamsSet(minBond_, claimDeposit_);
    }

    function setGovernance(address g) external onlyGovernance {
        governance = g;
        emit GovernanceChanged(g);
    }

    // ------------------------------------------------------------- internals

    function _operated(uint256 id) private view returns (Agent storage a) {
        a = agents[id];
        if (a.operator == address(0)) revert NoAgent();
        if (a.operator != msg.sender) revert NotOperator();
    }

    function _claimable(uint256 actionId) private view returns (Action storage act) {
        act = actions[actionId];
        if (act.agentId == 0) revert NoAction();
        if (block.timestamp > act.time + CLAIM_WINDOW) revert ClaimWindowOver();
        if (agents[act.agentId].bond == 0) revert Inactive(); // bond withdrawn or slashed away: nothing to claim
    }

    function _close(uint256 claimId, bool upheld) private {
        Claim storage c = claims[claimId];
        uint256 agentId = actions[c.actionId].agentId;
        Agent storage a = agents[agentId];
        a.openClaims--;
        uint256 paid;
        if (upheld) {
            c.state = ClaimState.Upheld;
            paid = _slash(agentId, c.actionId, c.claimant, c.amount);
            _pay(c.claimant, c.deposit);
        } else {
            c.state = ClaimState.Rejected;
            _pay(a.operator, c.deposit);
        }
        emit ClaimClosed(claimId, c.state, paid);
    }

    function _slash(uint256 agentId, uint256 actionId, address to, uint256 amount) private returns (uint256 paid) {
        Agent storage a = agents[agentId];
        paid = amount < a.bond ? amount : a.bond;
        a.bond -= paid;
        emit Slashed(agentId, actionId, to, paid);
        _pay(to, paid);
    }

    function _pay(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok,) = to.call{value: amount}("");
        if (!ok) revert TransferFailed();
    }
}

/// @title ConstitutionChecker: a deterministic checker for simple agent policies
/// @notice The constitution document is
///           abi.encode(address principal, uint256 maxValuePerAction,
///                      address[] allowedTargets, bytes32[] allowedModels)
///         and an action violates it when its value is above the cap, its
///         target is not allowed (an empty list allows none), or its model is
///         not allowed (an empty list allows any). The victim is the
///         principal; the damage is the action's value (the part above the
///         cap, for a cap violation).
contract ConstitutionChecker is IPolicyChecker {
    function check(ActionView calldata action, bytes calldata constitution, bytes calldata)
        external pure returns (bool violated, address victim, uint256 damage)
    {
        (address principal, uint256 maxValue, address[] memory targets, bytes32[] memory models) =
            abi.decode(constitution, (address, uint256, address[], bytes32[]));
        if (!_allowed(action.target, action.modelHash, targets, models)) return (true, principal, action.value);
        if (action.value > maxValue) return (true, principal, action.value - maxValue);
        return (false, address(0), 0);
    }

    function _allowed(address target, bytes32 model, address[] memory targets, bytes32[] memory models) private pure returns (bool) {
        bool targetOk;
        for (uint256 i = 0; i < targets.length; i++) if (targets[i] == target) targetOk = true;
        bool modelOk = models.length == 0;
        for (uint256 i = 0; i < models.length; i++) if (models[i] == model) modelOk = true;
        return targetOk && modelOk;
    }
}

contracts/BridgeAirlock.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRunnerRecords {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

interface IGuardInbound {
    function inbound(bytes32 route, address to, uint256 amount) external;
    function guardian(address who) external view returns (bool);
}

/// ThreatRegistry's views (Reason as its uint8 value). is*Held: once the flag is
/// the registry's holdDelay old (e.g. 10 minutes), or at once through its fast
/// lane or a guardian's holdNow. is*Enforced: once the flag is the registry's
/// enforceDelay old, or at once through its fast lane.
interface IThreatFlags {
    function isAddressEnforced(uint256 chainId, address who) external view returns (bool, uint8);
    function isContractEnforced(address who) external view returns (bool, uint8);
    function isAddressHeld(uint256 chainId, address who) external view returns (bool, uint8);
    function isContractHeld(address who) external view returns (bool, uint8);
}

/// NeuroControl (Neuro's stop switch); only `paused()` is used here.
interface INeuroControl {
    function paused() external view returns (bool);
}

/// A lane says who decides what it attests (NeuroLane: its runner records;
/// HyperlaneLane: its Mailbox). Lanes whose controllers are the same address
/// are one lane as far as independence goes.
interface ILaneInfo {
    function laneController() external view returns (address);
}

/// @title BridgeAirlock: nothing enters ZETAPHY on one bridge's word (stage 3)
/// @notice Defence in depth for incoming assets:
///   1. Several independent "lanes" (Hyperlane, IBC, the Neuro runner lane...)
///      must each attest the SAME transfer. One hacked bridge alone cannot
///      create money.
///   2. Even then the transfer waits in quarantine. During it, vetoers (the
///      Neuro lane by quorum, or a guardian) can stop it.
///   3. Markers: keys governance names (setMarker), typically the bridge
///      monitor's own low-privilege key, can mark an address (trip). A
///      transfer from or to a marked address is not released until governance
///      lifts the mark (untrip). Why an address is marked is decided off-chain
///      by the marker; the airlock keeps no list of what it watches.
///   4. Vaccine: with a ThreatRegistry set, a transfer whose source sender or
///      source contract (on its chain), or whose ZETAPHY recipient (address or
///      code), is flagged by the Neuro runners is not released:
///        - flagged, within the registry's holdDelay (e.g. 10 minutes): not
///          held yet, so a 2-runner quorum alone cannot freeze anyone's
///          transfers at once; governance or a guardian can holdNow(key)
///          meanwhile (the registry's fast lane holds at once too).
///        - held (past holdDelay, fast lane or holdNow), not enforced yet:
///          release reverts with ThreatHeld. It comes out once the flag is
///          cleared (same quorum, or an upheld appeal) or governance protects
///          the key; nothing else releases it.
///        - enforced (past the registry's enforceDelay, or at once through its
///          fast lane): refused, release reverts with ThreatFlagged, as long as
///          the flag stands. The transfer stays, so it still comes out if the
///          flag is cleared or the key protected.
///      For a hold that outlives any flag, the Neuro lane or a guardian vetoes.
///      The coins stay locked in the source chain's LockBox meanwhile: it has no
///      refund path, so a held (or vetoed) transfer is not paid back there.
///      deploy-bridge therefore protects the bridge's own keys and the source
///      LockBox in the registry, so runners cannot hold every transfer at once.
///   Released transfers still pass BridgeGuard's daily limits.
///   Independence: each lane names its controller (laneController(): NeuroLane
///   its runner records, HyperlaneLane its Mailbox; a plain key is its own).
///   independentLanes() counts distinct controllers, and BridgeGuard enables
///   this airlock's route only while it is 2 or more.
contract BridgeAirlock {
    struct Transfer {
        uint64 readyFrom;    // when the threshold was reached; quarantine counts from here
        uint8 attestations;
        bool released;
        bool vetoed;
    }

    IGuardInbound public immutable guard;
    bytes32 public immutable route;     // this airlock's route in BridgeGuard
    address public governance;
    uint8 public threshold;             // distinct lanes that must agree
    uint64 public quarantine;           // seconds a transfer waits after enough lanes agreed
    mapping(address => bool) public isLane;
    address[] private laneList;         // the lanes now on, in no particular order
    uint256 public constant MAX_LANES = 16;
    mapping(address => bool) public isVetoer;
    /// Keys that may mark addresses (trip). See trip(): a marker can only mark.
    mapping(address => bool) public isMarker;
    uint256 public markerCount;         // markers now on
    /// Who marked an address (zero: not marked). A mark counts while its
    /// marker is a marker, or was removed by a guardian (markerRevoked);
    /// governance removing a marker (setMarker) lifts all of its marks at once
    /// (see tripped()).
    mapping(address => address) public trippedBy;
    /// Markers a guardian removed (emergencyRemoveMarker): they mark no more,
    /// but the marks they made still count until governance decides
    /// (setMarker, untrip).
    mapping(address => bool) public markerRevoked;
    mapping(bytes32 => Transfer) public transfers;
    mapping(bytes32 => mapping(address => bool)) public attestedBy;
    /// By controller (laneControllerOf at attest time): two lanes with one
    /// controller count once, so the threshold means independent lanes.
    mapping(bytes32 => mapping(address => bool)) public attestedByController;
    IThreatFlags public threats;        // zero: no vaccine check

    event LaneSet(address lane, bool on);
    event GovernanceSet(address governance);
    event ThresholdSet(uint8 threshold);
    event QuarantineSet(uint64 quarantine);
    event Untripped(address indexed who);
    event VetoerSet(address who, bool on);
    event MarkerSet(address marker, bool on);
    /// The transfer's details too, so a monitor sees two lanes that disagree
    /// about one source deposit (same chain, contract and nonce; another id).
    event Attested(bytes32 indexed id, address indexed lane, uint8 count, uint256 srcChainId, address srcContract,
        uint256 indexed srcNonce, address sender, address to, uint256 amount);
    event Vetoed(bytes32 indexed id, address indexed by, string reason);
    event Released(bytes32 indexed id, address indexed to, uint256 amount);
    event Tripped(address indexed who, address indexed by);
    event ThreatsSet(address registry);

    error NotGovernance();
    error NotLane();
    error NotVetoer();
    error NotMarker();
    error NotGuardian();
    error Twice();
    error NotReady();
    error Blocked();
    /// what: 1 source sender, 2 source contract, 3 ZETAPHY recipient (enforced flag)
    error ThreatFlagged(uint8 what);
    /// the same, for a held flag that is not enforced yet: held until it is cleared
    error ThreatHeld(uint8 what);

    constructor(IGuardInbound guard_, bytes32 route_, address governance_, uint8 threshold_, uint64 quarantine_) {
        require(threshold_ >= 2, "need 2+ independent lanes");
        guard = guard_;
        route = route_;
        governance = governance_;
        threshold = threshold_;
        quarantine = quarantine_;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setLane(address lane, bool on) external onlyGov {
        if (on && !isLane[lane]) {
            require(lane != address(0) && laneList.length < MAX_LANES, "lane");
            laneList.push(lane);
        } else if (!on && isLane[lane]) {
            for (uint256 i = 0; i < laneList.length; i++) {
                if (laneList[i] == lane) { laneList[i] = laneList[laneList.length - 1]; laneList.pop(); break; }
            }
        }
        isLane[lane] = on;
        emit LaneSet(lane, on);
    }
    function setVetoer(address who, bool on) external onlyGov { isVetoer[who] = on; emit VetoerSet(who, on); }
    /// Names (or removes) a marker: typically the bridge monitor's own key, which
    /// holds no other role. Governance removes a lost or misused marker key here.
    /// Removing one lifts its marks, also after a guardian's emergencyRemoveMarker.
    function setMarker(address marker, bool on) external onlyGov {
        if (on != isMarker[marker]) {
            if (on) markerCount += 1;
            else markerCount -= 1;
        }
        isMarker[marker] = on;
        markerRevoked[marker] = false;
        emit MarkerSet(marker, on);
    }
    /// Raising the threshold later does not hold back transfers that already reached the old one.
    function setThreshold(uint8 t) external onlyGov { require(t >= 2, "need 2+"); threshold = t; emit ThresholdSet(t); }
    function setQuarantine(uint64 q) external onlyGov { quarantine = q; emit QuarantineSet(q); }
    function setGovernance(address g) external onlyGov { governance = g; emit GovernanceSet(g); }
    /// The ThreatRegistry whose flags hold transfers (zero turns the check off).
    function setThreats(IThreatFlags r) external onlyGov { threats = r; emit ThreatsSet(address(r)); }
    /// Governance can lift a mark set by mistake.
    function untrip(address who) external onlyGov { delete trippedBy[who]; emit Untripped(who); }

    // ---- emergency: BridgeGuard's guardians act at once, but only to reduce risk ----
    // Governance is meant to be the ZetaphyTimelock (48 h). Adding a lane or a
    // marker, lowering the threshold or the quarantine, lifting a mark, a new
    // registry or governance all wait that delay. These four only make release
    // harder, so a guardian of the guard (a multisig, BridgeGuard.setGuardian)
    // makes them at once. (A guardian removing a marker stops it from marking
    // but keeps the marks it made: only governance, through setMarker or
    // untrip, lifts marks.)
    uint64 public constant MAX_QUARANTINE = 30 days;

    function emergencyRemoveLane(address lane) external {
        _guardian();
        if (!isLane[lane]) revert NotLane();
        for (uint256 i = 0; i < laneList.length; i++) {
            if (laneList[i] == lane) { laneList[i] = laneList[laneList.length - 1]; laneList.pop(); break; }
        }
        isLane[lane] = false;
        emit LaneSet(lane, false);
    }

    function emergencyRemoveMarker(address marker) external {
        _guardian();
        if (!isMarker[marker]) revert NotMarker();
        isMarker[marker] = false;
        markerRevoked[marker] = true;
        markerCount -= 1;
        emit MarkerSet(marker, false);
    }

    /// More independent lanes must agree (at most MAX_LANES; above the lane count nothing is released).
    function emergencyRaiseThreshold(uint8 t) external {
        _guardian();
        require(t > threshold && t <= MAX_LANES, "raise only");
        threshold = t;
        emit ThresholdSet(t);
    }

    /// A longer quarantine (at most MAX_QUARANTINE), more time to veto.
    function emergencyRaiseQuarantine(uint64 q) external {
        _guardian();
        require(q > quarantine && q <= MAX_QUARANTINE, "raise only");
        quarantine = q;
        emit QuarantineSet(q);
    }

    /// Governance, or a guardian of the guard (a guard without guardian() has none).
    function _guardian() private view {
        if (msg.sender == governance) return;
        (bool ok, bytes memory ret) = address(guard).staticcall(abi.encodeCall(IGuardInbound.guardian, (msg.sender)));
        if (!ok || ret.length < 32 || !abi.decode(ret, (bool))) revert NotGuardian();
    }

    /// Marked by a marker that is still on, or that a guardian removed.
    /// setMarker(m, false) lifts every mark m made (setting m on again would
    /// bring them back).
    function tripped(address who) public view returns (bool) {
        address m = trippedBy[who];
        return m != address(0) && (isMarker[m] || markerRevoked[m]);
    }

    /// The lanes now on.
    function lanes() external view returns (address[] memory) { return laneList; }
    function laneCount() external view returns (uint256) { return laneList.length; }

    /// Who decides what a lane attests: its laneController(), or the lane itself
    /// (a key, or a contract that does not say).
    function laneControllerOf(address lane) public view returns (address) {
        if (lane.code.length == 0) return lane;
        try ILaneInfo(lane).laneController() returns (address c) { return c == address(0) ? lane : c; } catch { return lane; }
    }

    /// Lanes with distinct controllers. BridgeGuard will not enable this
    /// airlock's route while it is below 2: one controller behind two lane
    /// contracts is still one bridge's word.
    function independentLanes() external view returns (uint256 n) {
        uint256 len = laneList.length;
        address[] memory seen = new address[](len);
        for (uint256 i = 0; i < len; i++) {
            address c = laneControllerOf(laneList[i]);
            bool dup = false;
            for (uint256 j = 0; j < n; j++) if (seen[j] == c) { dup = true; break; }
            if (!dup) seen[n++] = c;
        }
    }

    /// The id every lane computes for one transfer seen on the source chain:
    /// the source contract's own running number, not a tx hash or log
    /// position, which can change if the source chain reorganises.
    function transferId(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount)
        public pure returns (bytes32)
    {
        return keccak256(abi.encode(srcChainId, srcContract, srcNonce, sender, to, amount));
    }

    function attest(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external {
        if (!isLane[msg.sender]) revert NotLane();
        bytes32 id = transferId(srcChainId, srcContract, srcNonce, sender, to, amount);
        if (attestedBy[id][msg.sender]) revert Twice();
        attestedBy[id][msg.sender] = true;
        Transfer storage t = transfers[id];
        address c = laneControllerOf(msg.sender);
        if (!attestedByController[id][c]) {
            attestedByController[id][c] = true;
            t.attestations += 1;
        }
        if (t.readyFrom == 0 && t.attestations >= threshold) t.readyFrom = uint64(block.timestamp);
        emit Attested(id, msg.sender, t.attestations, srcChainId, srcContract, srcNonce, sender, to, amount);
    }

    function veto(bytes32 id, string calldata reason) external {
        if (!isVetoer[msg.sender]) revert NotVetoer();
        Transfer storage t = transfers[id];
        if (t.released) revert Blocked();
        t.vetoed = true;
        emit Vetoed(id, msg.sender, reason);
    }

    /// A marker marks `who`: release() then refuses (Blocked) every transfer
    /// whose source sender or ZETAPHY recipient is `who`, until governance
    /// untrips it. That is all a marker can do: it cannot attest, veto,
    /// release, mint, pause or move any funds, and a mark loses nothing (the
    /// transfer stays and comes out once the mark is lifted). So a stolen or
    /// misused marker key can at worst delay some addresses' transfers until
    /// governance removes the marker (setMarker), which lifts all its marks.
    /// A mark that counts is kept by its first marker (another marker's
    /// mark does not replace it).
    function trip(address who) external {
        if (!isMarker[msg.sender]) revert NotMarker();
        if (tripped(who)) return;
        trippedBy[who] = msg.sender;
        emit Tripped(who, msg.sender);
    }

    /// Anyone may release a transfer that passed every check.
    function release(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external {
        bytes32 id = transferId(srcChainId, srcContract, srcNonce, sender, to, amount);
        Transfer storage t = transfers[id];
        if (t.released || t.vetoed || tripped(sender) || tripped(to)) revert Blocked();
        if (t.attestations < threshold || t.readyFrom == 0 || block.timestamp < t.readyFrom + quarantine) revert NotReady();
        uint8 what = flaggedParty(srcChainId, srcContract, sender, to);
        if (what != 0) revert ThreatFlagged(what);
        what = heldParty(srcChainId, srcContract, sender, to);
        if (what != 0) revert ThreatHeld(what);
        t.released = true;
        guard.inbound(route, to, amount);
        emit Released(id, to, amount);
    }

    /// 0 when no party of this transfer has an enforced flag, else which one
    /// has (see ThreatFlagged). NeuroLane watchers ask this before they attest.
    function flaggedParty(uint256 srcChainId, address srcContract, address sender, address to) public view returns (uint8) {
        return _party(srcChainId, srcContract, sender, to, true);
    }

    /// 0 when no party of this transfer is held, else which one is (the
    /// registry's is*Held views: past holdDelay, fast lane or holdNow). A
    /// transfer with a held party is not released; NeuroLane watchers ask this
    /// before they release.
    function heldParty(uint256 srcChainId, address srcContract, address sender, address to) public view returns (uint8) {
        return _party(srcChainId, srcContract, sender, to, false);
    }

    function _party(uint256 srcChainId, address srcContract, address sender, address to, bool enforced) private view returns (uint8) {
        IThreatFlags r = threats;
        if (address(r) == address(0)) return 0;
        bool f;
        (f, ) = enforced ? r.isAddressEnforced(srcChainId, sender) : r.isAddressHeld(srcChainId, sender);
        if (f) return 1;
        (f, ) = enforced ? r.isAddressEnforced(srcChainId, srcContract) : r.isAddressHeld(srcChainId, srcContract);
        if (f) return 2;
        (f, ) = enforced ? r.isContractEnforced(to) : r.isContractHeld(to);
        if (f) return 3;
        return 0;
    }

    function status(bytes32 id) external view returns (uint8 attestations, bool released, bool vetoed, uint64 readyAt) {
        Transfer storage t = transfers[id];
        return (t.attestations, t.released, t.vetoed, t.readyFrom == 0 ? 0 : t.readyFrom + quarantine);
    }
}

/// @title NeuroLane: Neuro runners as one of the airlock's bridges
/// @notice Runners watch the source chain's LockBox and each attest the
///         transfers they see. When `quorum` distinct proven runners attest
///         the same transfer, this lane attests it to the airlock. Runners
///         can also vote to veto a transfer still in quarantine.
///         While Neuro is paused (NeuroControl, if set) nothing is attested;
///         vetoes still work, since holding money back is always safe.
contract NeuroLane {
    IRunnerRecords public immutable runners;
    BridgeAirlock public immutable airlock;
    uint8 public immutable quorum;
    uint32 public immutable minAgreed;
    INeuroControl public immutable control; // zero: no pause check

    mapping(bytes32 => uint8) public votes;
    mapping(bytes32 => mapping(address => bool)) public votedBy;
    mapping(bytes32 => bool) public done;

    event RunnerAttested(bytes32 indexed id, address indexed runner, uint8 votes);

    /// The runner records decide what this lane attests (BridgeAirlock.independentLanes).
    function laneController() external view returns (address) { return address(runners); }
    event RunnerVetoVote(bytes32 indexed id, address indexed runner, uint8 votes);

    error NotRunner();
    error Twice();
    error NeuroPaused();

    constructor(IRunnerRecords runners_, BridgeAirlock airlock_, uint8 quorum_, uint32 minAgreed_, INeuroControl control_) {
        require(quorum_ >= 2, "quorum");
        runners = runners_;
        airlock = airlock_;
        quorum = quorum_;
        minAgreed = minAgreed_;
        control = control_;
    }

    function _runner() private view {
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed) revert NotRunner();
    }

    function attest(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external {
        _runner();
        if (address(control) != address(0) && control.paused()) revert NeuroPaused();
        bytes32 id = airlock.transferId(srcChainId, srcContract, srcNonce, sender, to, amount);
        bytes32 key = keccak256(abi.encode("attest", id));
        if (votedBy[key][msg.sender] || done[key]) revert Twice();
        votedBy[key][msg.sender] = true;
        uint8 v = ++votes[key];
        emit RunnerAttested(id, msg.sender, v);
        if (v >= quorum) {
            done[key] = true;
            airlock.attest(srcChainId, srcContract, srcNonce, sender, to, amount);
        }
    }

    function voteVeto(bytes32 id, string calldata reason) external {
        _runner();
        bytes32 key = keccak256(abi.encode("veto", id));
        if (votedBy[key][msg.sender] || done[key]) revert Twice();
        votedBy[key][msg.sender] = true;
        uint8 v = ++votes[key];
        emit RunnerVetoVote(id, msg.sender, v);
        if (v >= quorum) {
            done[key] = true;
            airlock.veto(id, reason);
        }
    }
}

/// @title LockBox: the source-chain side of the Neuro lane (test / testnet)
/// @notice Locks native coin and emits what the lanes need to attest. Lanes
///         attest (chainid, this contract, nonce, sender, to, amount).
contract LockBox {
    uint256 public nonce;
    event Locked(uint256 indexed nonce, address indexed sender, address indexed to, uint256 amount);

    function lock(address to) external payable {
        require(msg.value > 0 && to != address(0), "lock");
        emit Locked(nonce++, msg.sender, to, msg.value);
    }
}

contracts/BridgeGuard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// ThreatRegistry's hold view for code on ZETAPHY (Reason as its uint8 value):
/// true once a flag on its address or code is the registry's holdDelay old, or at
/// once through the registry's fast lane or a guardian's holdNow.
interface IContractThreats {
    function isContractHeld(address who) external view returns (bool, uint8);
}

/// BridgeAirlock's count of lanes with distinct controllers.
interface IIndependentLanes {
    function independentLanes() external view returns (uint256);
}

/// @title BridgedToken: a token that exists on ZETAPHY only through a bridge
/// @notice Only its BridgeGuard can mint (assets arriving) or burn (leaving).
contract BridgedToken {
    string public name;
    string public symbol;
    uint8 public immutable decimals;
    address public immutable guard;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(string memory n, string memory s, uint8 d, address guard_) {
        name = n; symbol = s; decimals = d; guard = guard_;
    }

    modifier onlyGuard() { require(msg.sender == guard, "only guard"); _; }

    function mint(address to, uint256 v) external onlyGuard { totalSupply += v; balanceOf[to] += v; emit Transfer(address(0), to, v); }
    function burn(address from, uint256 v) external onlyGuard {
        require(balanceOf[from] >= v, "balance");
        balanceOf[from] -= v; totalSupply -= v; emit Transfer(from, address(0), v);
    }
    function approve(address s, uint256 v) external returns (bool) { allowance[msg.sender][s] = v; emit Approval(msg.sender, s, v); return true; }
    function transfer(address to, uint256 v) external returns (bool) { _move(msg.sender, to, v); return true; }
    function transferFrom(address f, address to, uint256 v) external returns (bool) {
        uint256 a = allowance[f][msg.sender];
        if (a != type(uint256).max) { require(a >= v, "allowance"); allowance[f][msg.sender] = a - v; }
        _move(f, to, v); return true;
    }
    function _move(address f, address to, uint256 v) private {
        require(to != address(0) && balanceOf[f] >= v, "transfer");
        balanceOf[f] -= v; balanceOf[to] += v; emit Transfer(f, to, v);
    }
}

/// @title BridgeGuard: limits and a stop button for every bridge route (stage 3)
/// @notice A bridge adapter (Hyperlane warp route, IBC hook, ...) never mints
///         or burns directly: it asks this guard, which enforces
///           - a daily limit per route and direction, so a hacked bridge can
///             lose at most one day's limit, not everything;
///           - a pause that only guardians can pull and only governance can
///             release. Pausing stops the bridges, never the chain.
///           - vaccine (with a ThreatRegistry set): no coins to, or out of, an
///             address or contract the registry holds (is*Held: a flag that is
///             holdDelay old, e.g. 10 minutes, or held at once by the fast lane or
///             a guardian's holdNow; two runners alone cannot freeze anyone at
///             once). This is a hold, not a loss:
///               - inbound: the mint is QUEUED, not reverted (InboundHeld, an id
///                 in `held`). The adapter's message is delivered, so nothing
///                 depends on an adapter retrying. Anyone calls releaseHeld(id)
///                 once the hold ends (the flag cleared, or governance protects
///                 the key); it then passes the pause, the route (still enabled)
///                 and the route's daily limit like any inbound. Governance can
///                 dropHeld(id) a queued mint (e.g. from a hacked adapter).
///               - outbound: the call reverts (the burn simply did not happen;
///                 the holder keeps the coins).
///             The adapter itself is NOT checked: governance chose it and can
///             disable its route; a runner flag on its code hash or address must
///             not be able to freeze a whole route.
///         Opening gates (a route stays closed until they hold):
///           - an audit on record: setAudit(https url, sha256 of the report)
///             before any route can be enabled;
///           - the route's adapter is a BridgeAirlock with at least 2 lanes
///             whose controllers differ (independentLanes() >= 2);
///           - a hard cap, maxDailyLimit, over every route's daily limit and over all routes together per day. It
///             starts at 1,000 whole tokens (createToken), is lowered at once,
///             and is raised only by governance, at most x2 per step (or back up
///             to the cap before a lowerMaxDailyLimit cut), each step 7 days after
///             it was proposed: caps grow gradually and in public.
///         Outbound-only routes (setOutboundRoute): an adapter that only burns, e.g. a
///         HyperlaneOutbox sending the token back to its source chain. inbound() refuses
///         such a route, so it never mints and needs no airlock; enabling it still needs the
///         audit on record and a daily limit within the hard cap. An id is either kind, for good.
///         Governance should be the ZetaphyTimelock (proposers: the chain's gov
///         module or a multisig). Guardians act at once, but only to reduce risk:
///         pause, lowerMaxDailyLimit, cancelMaxDailyLimit, disableRoute.
contract BridgeGuard {
    struct Route {
        address adapter;      // the only caller allowed for this route
        uint128 dailyLimit;   // per direction, in token units
        uint128 inToday;
        uint128 outToday;
        uint64 day;
        bool enabled;
    }

    BridgedToken public token;
    address public governance;
    mapping(address => bool) public guardian;
    bool public paused;
    mapping(bytes32 => Route) public routes;
    IContractThreats public threats; // zero: no vaccine check
    address[] private guardianList;  // everyone ever made a guardian (guardians() filters the current ones)

    /// The audit the bridge opened on: where to read it and the sha256 of the report.
    string public auditUrl;
    bytes32 public auditSha256;
    /// Hard cap over every route's daily limit (token units).
    uint128 public maxDailyLimit;
    uint128 public pendingMaxDailyLimit;
    uint64 public pendingMaxAt;      // when the pending raise may be applied (0: none)
    uint64 public constant CAP_DELAY = 7 days;
    /// The highest cap before lowerMaxDailyLimit cut it (0: none). Governance may
    /// propose a raise back up to it in one step (still CAP_DELAY), so a guardian's
    /// emergency cut (even to 0) is never undone only by x2 steps of 7 days each.
    uint128 public restoreMaxDailyLimit;
    uint128 public constant STARTER_UNITS = 1000; // whole tokens: the cap at createToken
    /// Every route together, per direction and day: the hard cap binds the
    /// guard, so more routes cannot multiply it.
    uint128 public totalInToday;
    uint128 public totalOutToday;
    uint64 public totalDay;

    /// Inbound mints held by the vaccine, waiting for releaseHeld.
    struct HeldMint {
        bytes32 route;
        address to;
        uint256 amount;
        bool done;       // released or dropped
    }
    HeldMint[] public held;
    /// Routes that only burn (setOutboundRoute): inbound() refuses them.
    mapping(bytes32 => bool) public outboundOnly;

    event RouteSet(bytes32 indexed id, address adapter, uint128 dailyLimit, bool enabled);
    event GovernanceSet(address governance);
    event AuditSet(string url, bytes32 sha256);
    event MaxDailyLimitProposed(uint128 value, uint64 at);
    event MaxDailyLimitSet(uint128 value);
    event MaxDailyLimitCancelled();
    event GuardianSet(address indexed who, bool allowed);
    event Paused(address indexed by);
    event Unpaused();
    event Inbound(bytes32 indexed route, address indexed to, uint256 amount);
    event Outbound(bytes32 indexed route, address indexed from, uint256 amount);
    event ThreatsSet(address registry);
    event InboundHeld(uint256 indexed id, bytes32 indexed route, address indexed to, uint256 amount);
    event HeldReleased(uint256 indexed id, address indexed to, uint256 amount);
    event HeldDropped(uint256 indexed id);
    event OutboundOnly(bytes32 indexed id);

    error NotGovernance();
    error NotGuardian();
    error NotAdapter();
    error BridgePaused();
    error OverLimit(uint256 remaining);
    error FlaggedContract(address who);
    error NoHeld();
    error AuditMissing();
    error NeedLanes(uint256 independent);
    error OverCap(uint128 cap);
    error CapStep(uint128 most);
    error TooEarly(uint64 at);
    error NoPending();
    error RouteKind();

    constructor(address governance_) {
        governance = governance_;
    }

    /// One-time: the guard deploys and owns its token.
    function createToken(string calldata n, string calldata s, uint8 d) external returns (BridgedToken) {
        if (msg.sender != governance) revert NotGovernance();
        require(address(token) == address(0), "token exists");
        require(d <= 30, "decimals");
        token = new BridgedToken(n, s, d, address(this));
        maxDailyLimit = uint128(uint256(STARTER_UNITS) * (uint256(10) ** d));
        emit MaxDailyLimitSet(maxDailyLimit);
        return token;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setGovernance(address g) external onlyGov { governance = g; emit GovernanceSet(g); }
    function setGuardian(address who, bool allowed) external onlyGov {
        if (allowed && !guardian[who]) {
            bool known = false;
            for (uint256 i = 0; i < guardianList.length; i++) if (guardianList[i] == who) { known = true; break; }
            if (!known) { require(guardianList.length < 32, "guardians"); guardianList.push(who); }
        }
        guardian[who] = allowed;
        emit GuardianSet(who, allowed);
    }

    /// The current guardians.
    function guardians() external view returns (address[] memory out) {
        uint256 n = 0;
        for (uint256 i = 0; i < guardianList.length; i++) if (guardian[guardianList[i]]) n++;
        out = new address[](n);
        n = 0;
        for (uint256 i = 0; i < guardianList.length; i++) if (guardian[guardianList[i]]) out[n++] = guardianList[i];
    }

    /// The audit report the bridge opens on (an https url and the report's sha256).
    function setAudit(string calldata url, bytes32 sha) external onlyGov {
        bytes memory u = bytes(url);
        require(sha != bytes32(0) && u.length > 8 && u.length <= 200 && u[0] == "h" && u[1] == "t" && u[2] == "t" && u[3] == "p"
            && u[4] == "s" && u[5] == ":" && u[6] == "/" && u[7] == "/", "audit: https url and sha256");
        auditUrl = url;
        auditSha256 = sha;
        emit AuditSet(url, sha);
    }

    /// Lowering the cap applies at once (and cancels a pending raise); a raise
    /// (at most x2 of the cap, or up to restoreMaxDailyLimit) waits CAP_DELAY,
    /// then anyone applies it.
    function proposeMaxDailyLimit(uint128 v) external onlyGov {
        if (v <= maxDailyLimit) {
            maxDailyLimit = v;
            pendingMaxAt = 0;
            pendingMaxDailyLimit = 0;
            emit MaxDailyLimitSet(v);
            return;
        }
        uint256 most = uint256(maxDailyLimit) * 2;
        if (restoreMaxDailyLimit > most) most = restoreMaxDailyLimit;
        if (v > most) revert CapStep(uint128(most));
        pendingMaxDailyLimit = v;
        pendingMaxAt = uint64(block.timestamp) + CAP_DELAY;
        emit MaxDailyLimitProposed(v, pendingMaxAt);
    }

    function applyMaxDailyLimit() external {
        uint64 at = pendingMaxAt;
        if (at == 0) revert NoPending();
        if (block.timestamp < at) revert TooEarly(at);
        maxDailyLimit = pendingMaxDailyLimit;
        pendingMaxAt = 0;
        pendingMaxDailyLimit = 0;
        if (maxDailyLimit >= restoreMaxDailyLimit) restoreMaxDailyLimit = 0;
        emit MaxDailyLimitSet(maxDailyLimit);
    }

    /// Governance or a guardian: drop a pending raise (reducing risk never waits).
    function cancelMaxDailyLimit() external {
        _govOrGuardian();
        pendingMaxAt = 0;
        pendingMaxDailyLimit = 0;
        emit MaxDailyLimitCancelled();
    }

    // ---- emergency: guardians act at once, but only to reduce risk ----
    // With governance behind a timelock (ZetaphyTimelock, 48 h), everything that
    // raises risk or changes rules (enable a route, raise a cap, unpause, new
    // guardians, audit, registry, governance) waits the delay. These calls only
    // shrink what can cross, so a guardian (a multisig) makes them at once.

    /// Lower the hard cap (never raise it) and drop a pending raise.
    function lowerMaxDailyLimit(uint128 v) external {
        _govOrGuardian();
        if (v >= maxDailyLimit) revert CapStep(maxDailyLimit);
        if (maxDailyLimit > restoreMaxDailyLimit) restoreMaxDailyLimit = maxDailyLimit;
        maxDailyLimit = v;
        pendingMaxAt = 0;
        pendingMaxDailyLimit = 0;
        emit MaxDailyLimitSet(v);
    }

    /// Close a route (its adapter and limit are kept; enabling it again is governance's).
    function disableRoute(bytes32 id) external {
        _govOrGuardian();
        Route storage r = routes[id];
        r.enabled = false;
        emit RouteSet(id, r.adapter, r.dailyLimit, false);
    }

    function _govOrGuardian() private view {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
    }
    /// The ThreatRegistry whose flags refuse coins (zero turns the check off).
    function setThreats(IContractThreats r) external onlyGov { threats = r; emit ThreatsSet(address(r)); }

    /// Enabling needs the audit on record, a daily limit within the hard cap and
    /// an adapter that is a BridgeAirlock with 2+ independent lanes. Disabling (or
    /// setting a closed route up) needs none of them: closing always works.
    function setRoute(bytes32 id, address adapter, uint128 dailyLimit, bool enabled) external onlyGov {
        if (outboundOnly[id]) revert RouteKind();
        if (enabled) {
            if (dailyLimit > maxDailyLimit) revert OverCap(maxDailyLimit);
            if (auditSha256 == bytes32(0)) revert AuditMissing();
            uint256 n = _independentLanes(adapter);
            if (n < 2) revert NeedLanes(n);
        }
        Route storage r = routes[id];
        r.adapter = adapter;
        r.dailyLimit = dailyLimit;
        r.enabled = enabled;
        emit RouteSet(id, adapter, dailyLimit, enabled);
    }

    /// An outbound-only route: its adapter may only burn (outbound); inbound() refuses it.
    /// Enabling needs the audit on record and a daily limit within the hard cap, and an
    /// adapter that is a contract; an id used by an inbound route is refused (RouteKind).
    function setOutboundRoute(bytes32 id, address adapter, uint128 dailyLimit, bool enabled) external onlyGov {
        Route storage r = routes[id];
        if (!outboundOnly[id]) {
            if (r.adapter != address(0)) revert RouteKind();
            outboundOnly[id] = true;
            emit OutboundOnly(id);
        }
        if (enabled) {
            if (dailyLimit > maxDailyLimit) revert OverCap(maxDailyLimit);
            if (auditSha256 == bytes32(0)) revert AuditMissing();
            if (adapter.code.length == 0) revert NotAdapter();
        }
        r.adapter = adapter;
        r.dailyLimit = dailyLimit;
        r.enabled = enabled;
        emit RouteSet(id, adapter, dailyLimit, enabled);
    }

    /// Any guardian (or governance) can stop all bridges at once.
    function pause() external {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
        paused = true;
        emit Paused(msg.sender);
    }

    /// Restarting needs governance: a stolen guardian key can only stop things.
    function unpause() external onlyGov {
        paused = false;
        emit Unpaused();
    }

    /// A held recipient: the mint is queued (InboundHeld), not reverted, and
    /// counts against the daily limit only when it is released.
    function inbound(bytes32 id, address to, uint256 amount) external {
        Route storage r = _use(id, amount, true);
        if (_isHeld(to)) {
            held.push(HeldMint(id, to, amount, false));
            emit InboundHeld(held.length - 1, id, to, amount);
            return;
        }
        _total(amount, true);
        r.inToday += uint128(amount);
        token.mint(to, amount);
        emit Inbound(id, to, amount);
    }

    /// Anyone: mint a queued inbound once its recipient is no longer held.
    /// Passes the pause, the route being enabled and its daily limit, as inbound does.
    function releaseHeld(uint256 hid) external {
        if (hid >= held.length || held[hid].done) revert NoHeld();
        HeldMint storage h = held[hid];
        if (paused) revert BridgePaused();
        Route storage r = routes[h.route];
        if (!r.enabled || outboundOnly[h.route]) revert NotAdapter();
        _clean(h.to);
        uint64 today = uint64(block.timestamp / 1 days);
        if (r.day != today) { r.day = today; r.inToday = 0; r.outToday = 0; }
        uint128 lim = _limit(r);
        if (r.inToday + h.amount > lim) revert OverLimit(lim > r.inToday ? lim - r.inToday : 0);
        _total(h.amount, true);
        h.done = true;
        r.inToday += uint128(h.amount);
        token.mint(h.to, h.amount);
        emit HeldReleased(hid, h.to, h.amount);
        emit Inbound(h.route, h.to, h.amount);
    }

    /// Governance drops a queued mint (e.g. one a hacked adapter sent).
    function dropHeld(uint256 hid) external onlyGov {
        if (hid >= held.length || held[hid].done) revert NoHeld();
        held[hid].done = true;
        emit HeldDropped(hid);
    }

    function heldCount() external view returns (uint256) {
        return held.length;
    }

    function outbound(bytes32 id, address from, uint256 amount) external {
        Route storage r = _use(id, amount, false);
        _clean(from);
        _total(amount, false);
        r.outToday += uint128(amount);
        token.burn(from, amount);
        emit Outbound(id, from, amount);
    }

    function remaining(bytes32 id) external view returns (uint256 inLeft, uint256 outLeft) {
        Route storage r = routes[id];
        bool fresh = r.day != uint64(block.timestamp / 1 days);
        uint128 lim = _limit(r);
        uint128 i = fresh ? 0 : r.inToday;
        uint128 o = fresh ? 0 : r.outToday;
        inLeft = lim > i ? lim - i : 0;
        outLeft = lim > o ? lim - o : 0;
    }

    /// A route's daily limit, never above the hard cap.
    function _limit(Route storage r) private view returns (uint128) {
        return r.dailyLimit < maxDailyLimit ? r.dailyLimit : maxDailyLimit;
    }

    /// The hard cap over all routes together (per direction, per day).
    function _total(uint256 amount, bool isIn) private {
        uint64 today = uint64(block.timestamp / 1 days);
        if (totalDay != today) { totalDay = today; totalInToday = 0; totalOutToday = 0; }
        uint256 used = isIn ? totalInToday : totalOutToday;
        uint256 cap = maxDailyLimit;
        if (used + amount > cap) revert OverLimit(cap > used ? cap - used : 0);
        if (isIn) totalInToday = uint128(used + amount); else totalOutToday = uint128(used + amount);
    }

    function _independentLanes(address adapter) private view returns (uint256) {
        if (adapter.code.length == 0) return 0;
        (bool ok, bytes memory ret) = adapter.staticcall(abi.encodeCall(IIndependentLanes.independentLanes, ()));
        if (!ok || ret.length < 32) return 0;
        return abi.decode(ret, (uint256));
    }

    /// Vaccine: holds back a party (the coins' owner) that the registry holds.
    function _clean(address who) private view {
        if (_isHeld(who)) revert FlaggedContract(who);
    }

    function _isHeld(address who) private view returns (bool f) {
        IContractThreats t = threats;
        if (address(t) == address(0)) return false;
        (f, ) = t.isContractHeld(who);
    }

    function _use(bytes32 id, uint256 amount, bool isIn) private returns (Route storage r) {
        if (paused) revert BridgePaused();
        r = routes[id];
        if (!r.enabled || msg.sender != r.adapter || (isIn && outboundOnly[id])) revert NotAdapter();
        uint64 today = uint64(block.timestamp / 1 days);
        if (r.day != today) { r.day = today; r.inToday = 0; r.outToday = 0; }
        uint256 used = isIn ? r.inToday : r.outToday;
        uint256 lim = _limit(r);
        if (used + amount > lim) revert OverLimit(lim > used ? lim - used : 0);
    }
}

contracts/ComputeMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRunnersView {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

/// @title ComputeMarket: pay node runners in ZETAPHY for AI work (stage 4)
/// @notice Model output (tier 2+) is not deterministic, so it cannot be
///         settled by 2-of-3 agreement like Neuro tier 1. Instead: escrow.
///         The requester pays up front; a runner with a NeuroJobs track
///         record takes the task and delivers a result (hash + URI); the
///         requester accepts or rejects within REVIEW. Silence pays the
///         runner. Both sides' reject counts are public, so runners can avoid
///         requesters who reject everything, and requesters can avoid runners
///         who deliver junk.
contract ComputeMarket {
    uint64 public constant REVIEW = 1 days;

    enum Status { None, Open, Taken, Delivered, Paid, Refunded }

    struct Task {
        address requester;
        address runner;
        Status status;
        uint64 deadline;     // delivery due
        uint64 deliveredAt;
        bytes32 model;       // e.g. "llama-3.1-8b-instruct-q4"
        bytes32 inputHash;
        bytes32 resultHash;
        uint256 price;
        string inputURI;
        string resultURI;
    }

    IRunnersView public immutable runners;
    uint32 public immutable minAgreed;
    Task[] internal tasks;
    mapping(address => uint256) public credit;
    mapping(address => uint32) public runnerDone;
    mapping(address => uint32) public runnerRejected;
    mapping(address => uint32) public requesterRejections;

    event Requested(uint256 indexed id, bytes32 indexed model, uint256 price, uint64 deadline);
    event Taken(uint256 indexed id, address indexed runner);
    event Delivered(uint256 indexed id, bytes32 resultHash, string resultURI);
    event Settled(uint256 indexed id, Status status);

    error BadValue();
    error BadState();
    error NotAllowed();
    error TooEarly();
    error Nothing();

    constructor(IRunnersView runners_, uint32 minAgreed_) {
        runners = runners_;
        minAgreed = minAgreed_;
    }

    function request(bytes32 model, bytes32 inputHash, string calldata inputURI, uint64 seconds_) external payable returns (uint256 id) {
        if (msg.value == 0 || model == bytes32(0) || seconds_ == 0 || seconds_ > 7 days || bytes(inputURI).length > 256) revert BadValue();
        id = tasks.length;
        Task storage t = tasks.push();
        t.requester = msg.sender;
        t.status = Status.Open;
        t.deadline = uint64(block.timestamp) + seconds_;
        t.model = model;
        t.inputHash = inputHash;
        t.inputURI = inputURI;
        t.price = msg.value;
        emit Requested(id, model, msg.value, t.deadline);
    }

    function take(uint256 id) external {
        Task storage t = _task(id, Status.Open);
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed || msg.sender == t.requester) revert NotAllowed();
        if (block.timestamp >= t.deadline) revert BadState();
        t.runner = msg.sender;
        t.status = Status.Taken;
        emit Taken(id, msg.sender);
    }

    function deliver(uint256 id, bytes32 resultHash, string calldata resultURI) external {
        Task storage t = _task(id, Status.Taken);
        if (msg.sender != t.runner) revert NotAllowed();
        if (block.timestamp > t.deadline || resultHash == bytes32(0) || bytes(resultURI).length > 256) revert BadValue();
        t.resultHash = resultHash;
        t.resultURI = resultURI;
        t.deliveredAt = uint64(block.timestamp);
        t.status = Status.Delivered;
        emit Delivered(id, resultHash, resultURI);
    }

    function accept(uint256 id) external {
        Task storage t = _task(id, Status.Delivered);
        if (msg.sender != t.requester) revert NotAllowed();
        _pay(id, t);
    }

    function reject(uint256 id) external {
        Task storage t = _task(id, Status.Delivered);
        if (msg.sender != t.requester) revert NotAllowed();
        if (block.timestamp > t.deliveredAt + REVIEW) revert BadState();
        runnerRejected[t.runner] += 1;
        requesterRejections[t.requester] += 1;
        _refund(id, t);
    }

    /// The runner is paid once the review window passes without a rejection.
    function claim(uint256 id) external {
        Task storage t = _task(id, Status.Delivered);
        if (block.timestamp <= t.deliveredAt + REVIEW) revert TooEarly();
        _pay(id, t);
    }

    /// Requester gets the money back if nobody took the task, or nothing was delivered in time.
    function cancel(uint256 id) external {
        if (id >= tasks.length) revert BadState();
        Task storage t = tasks[id];
        if (msg.sender != t.requester) revert NotAllowed();
        bool open = t.status == Status.Open;
        bool late = t.status == Status.Taken && block.timestamp > t.deadline;
        if (!open && !late) revert BadState();
        _refund(id, t);
    }

    function withdraw() external {
        uint256 a = credit[msg.sender];
        if (a == 0) revert Nothing();
        credit[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: a}("");
        require(ok, "transfer failed");
    }

    function taskCount() external view returns (uint256) { return tasks.length; }

    function getTask(uint256 id) external view returns (Task memory) {
        if (id >= tasks.length) revert BadState();
        return tasks[id];
    }

    function _task(uint256 id, Status want) private view returns (Task storage t) {
        if (id >= tasks.length) revert BadState();
        t = tasks[id];
        if (t.status != want) revert BadState();
    }

    function _pay(uint256 id, Task storage t) private {
        t.status = Status.Paid;
        credit[t.runner] += t.price;
        runnerDone[t.runner] += 1;
        emit Settled(id, Status.Paid);
    }

    function _refund(uint256 id, Task storage t) private {
        t.status = Status.Refunded;
        credit[t.requester] += t.price;
        emit Settled(id, Status.Refunded);
    }
}

contracts/HumanAgentLabels.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface ILabelWebAuthn {
    struct Assertion {
        bytes authenticatorData;
        bytes clientDataJSON;
        uint256 r;
        uint256 s;
    }

    function verify(bytes32 challenge, Assertion calldata a, uint256 x, uint256 y, bytes32 rpIdHash, bool requireUV)
        external view returns (bool);
}

interface ILabelAgents {
    function activeAgentOf(address account) external view returns (uint256);
}

/// The read interface for hooks (faucets, DEX gates, ...).
interface ILabels {
    /// 0 = no label, 1 = human (passkey-verified), 2 = registered AI agent
    function labelOf(address account) external view returns (uint8);
}

/// @title LabelRegistry: "human" or "agent" labels for accounts (testnet)
/// @notice
///   AGENT: an account an active agent of AgentRegistry transacts from
///          (bonded, not unbonding). Read live from the registry, so it
///          follows registration, unbonding and slashing.
///   HUMAN: an account whose owner showed a passkey (WebAuthn) with user
///          verification (fingerprint, face or device PIN), in one of two ways:
///          - on chain: proveHumanP256 checks the assertion through
///            WebAuthnVerifier (the P-256 precompile 0x…0100); the passkey's
///            challenge commits to this account and its nonce;
///          - off chain: an attester governance approved (a volunteer runner)
///            verified the assertion and signs an EIP-712 HumanAttestation
///            that anyone submits with attestHuman.
///          One passkey (its public key hash) labels one account at a time;
///          moving it to another account drops the old one's label.
///   An agent account is labelled AGENT even if it once proved a passkey.
///
///   What a HUMAN label does NOT prove: that the person is unique. Anyone can
///   make many passkeys. It proves a person was present at a device when the
///   label was made (expires after humanTtl). Hooks must treat it as a
///   speed bump against simple bots, not as proof of personhood.
contract LabelRegistry is ILabels {
    uint8 public constant NONE = 0;
    uint8 public constant HUMAN = 1;
    uint8 public constant AGENT = 2;
    uint8 public constant BY_PASSKEY = 1;
    uint8 public constant BY_ATTESTER = 2;

    bytes32 public constant ATTESTATION_TYPEHASH = keccak256(
        "HumanAttestation(address account,bytes32 credentialHash,uint64 validUntil,uint256 nonce,uint256 deadline)"
    );
    bytes32 private constant DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");

    struct Human {
        uint64 validUntil;
        uint8 method;
        bytes32 credentialHash;
        address attester; // 0 for an on-chain passkey proof
    }

    address public governance;
    ILabelAgents public agents;
    ILabelWebAuthn public webauthn;
    bytes32 public rpIdHash;  // sha256 of the hub's host name (0 = any site)
    uint64 public humanTtl;

    mapping(address => bool) public isAttester;
    mapping(address => Human) public humans;
    mapping(bytes32 => address) public credentialAccount;
    mapping(address => uint256) public nonces;

    event HumanLabelled(address indexed account, bytes32 indexed credentialHash, uint8 method, address attester, uint64 validUntil);
    event HumanRevoked(address indexed account, address by);
    event AttesterSet(address indexed attester, bool allowed);
    event ConfigSet(address agents, address webauthn, bytes32 rpIdHash, uint64 humanTtl);
    event GovernanceChanged(address governance);

    error NotGovernance();
    error NotAttester();
    error BadPasskey();
    error BadSignature();
    error Expired();
    error BadTtl();

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    constructor(address governance_, address agents_, address webauthn_, bytes32 rpIdHash_, uint64 humanTtl_) {
        governance = governance_;
        _config(agents_, webauthn_, rpIdHash_, humanTtl_);
    }

    // ------------------------------------------------------------- reading

    function labelOf(address account) public view returns (uint8) {
        if (address(agents) != address(0) && agents.activeAgentOf(account) != 0) return AGENT;
        Human storage h = humans[account];
        if (h.validUntil >= block.timestamp && credentialAccount[h.credentialHash] == account) return HUMAN;
        return NONE;
    }

    function isHuman(address account) external view returns (bool) {
        return labelOf(account) == HUMAN;
    }

    function isAgent(address account) external view returns (bool) {
        return labelOf(account) == AGENT;
    }

    /// The 32-byte challenge the passkey must sign to label `account` now.
    function humanChallenge(address account) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY human label", block.chainid, address(this), account, nonces[account]));
    }

    function domainSeparator() public view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN_TYPEHASH, keccak256("ZETAPHY Labels"), keccak256("1"), block.chainid, address(this)));
    }

    function attestationDigest(address account, bytes32 credentialHash, uint64 validUntil, uint256 nonce, uint256 deadline)
        public view returns (bytes32)
    {
        return keccak256(abi.encodePacked("\x19\x01", domainSeparator(),
            keccak256(abi.encode(ATTESTATION_TYPEHASH, account, credentialHash, validUntil, nonce, deadline))));
    }

    // ------------------------------------------------------------- labelling

    /// On-chain path: msg.sender labels itself with a passkey assertion over humanChallenge(msg.sender).
    function proveHumanP256(uint256 x, uint256 y, ILabelWebAuthn.Assertion calldata assertion) external {
        if (!webauthn.verify(humanChallenge(msg.sender), assertion, x, y, rpIdHash, true)) revert BadPasskey();
        _label(msg.sender, keccak256(abi.encode(x, y)), BY_PASSKEY, address(0), uint64(block.timestamp) + humanTtl);
    }

    /// Off-chain path: an attester's EIP-712 HumanAttestation, submitted by anyone.
    function attestHuman(address account, bytes32 credentialHash, uint64 validUntil, uint256 deadline, bytes calldata sig) external {
        if (block.timestamp > deadline) revert Expired();
        if (validUntil > block.timestamp + humanTtl) revert BadTtl();
        address attester = _recover(attestationDigest(account, credentialHash, validUntil, nonces[account], deadline), sig);
        if (!isAttester[attester]) revert NotAttester();
        _label(account, credentialHash, BY_ATTESTER, attester, validUntil);
    }

    /// The account itself, governance or any attester can remove a human label.
    function revokeHuman(address account) external {
        if (msg.sender != account && msg.sender != governance && !isAttester[msg.sender]) revert NotAttester();
        Human storage h = humans[account];
        if (credentialAccount[h.credentialHash] == account) delete credentialAccount[h.credentialHash];
        delete humans[account];
        nonces[account]++;
        emit HumanRevoked(account, msg.sender);
    }

    // ------------------------------------------------------------- governance

    function setAttester(address a, bool allowed) external onlyGovernance {
        isAttester[a] = allowed;
        emit AttesterSet(a, allowed);
    }

    function setConfig(address agents_, address webauthn_, bytes32 rpIdHash_, uint64 humanTtl_) external onlyGovernance {
        _config(agents_, webauthn_, rpIdHash_, humanTtl_);
    }

    function setGovernance(address g) external onlyGovernance {
        governance = g;
        emit GovernanceChanged(g);
    }

    // ------------------------------------------------------------- internals

    function _config(address agents_, address webauthn_, bytes32 rpIdHash_, uint64 humanTtl_) private {
        if (humanTtl_ == 0 || humanTtl_ > 400 days) revert BadTtl();
        agents = ILabelAgents(agents_);
        webauthn = ILabelWebAuthn(webauthn_);
        rpIdHash = rpIdHash_;
        humanTtl = humanTtl_;
        emit ConfigSet(agents_, webauthn_, rpIdHash_, humanTtl_);
    }

    function _label(address account, bytes32 cred, uint8 method, address attester, uint64 until) private {
        if (cred == bytes32(0)) revert BadPasskey();
        address prev = credentialAccount[cred];
        if (prev != address(0) && prev != account) delete humans[prev]; // one passkey, one account
        Human storage old = humans[account];
        if (old.credentialHash != bytes32(0) && old.credentialHash != cred && credentialAccount[old.credentialHash] == account) {
            delete credentialAccount[old.credentialHash];
        }
        credentialAccount[cred] = account;
        humans[account] = Human({validUntil: until, method: method, credentialHash: cred, attester: attester});
        nonces[account]++;
        emit HumanLabelled(account, cred, method, attester, until);
    }

    function _recover(bytes32 d, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) revert BadSignature();
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (v < 27) v += 27;
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) revert BadSignature();
        address a = ecrecover(d, v, r, s);
        if (a == address(0)) revert BadSignature();
        return a;
    }
}

/// @title LabelFaucet: a testnet faucet hook that reads labels
/// @notice Pays each label its own amount (e.g. humans 10, agents 1,
///         unlabelled 0) at most once per cooldown per account, and, for
///         humans, once per cooldown per passkey too, so moving one passkey
///         across accounts does not multiply the drip. Funded by anyone.
contract LabelFaucet {
    LabelRegistry public immutable labels;
    address public governance;
    uint256 public cooldown;
    uint256[3] public amountFor; // by label: NONE, HUMAN, AGENT
    mapping(address => uint256) public lastDrip;
    mapping(bytes32 => uint256) public lastDripCredential;

    event Dripped(address indexed to, uint8 label, uint256 amount);
    event ConfigSet(uint256 cooldown, uint256[3] amountFor);

    error NotGovernance();
    error NothingForLabel(uint8 label);
    error TooSoon();
    error TransferFailed();

    constructor(LabelRegistry labels_, address governance_, uint256 cooldown_, uint256[3] memory amountFor_) {
        labels = labels_;
        governance = governance_;
        cooldown = cooldown_;
        amountFor = amountFor_;
        emit ConfigSet(cooldown_, amountFor_);
    }

    receive() external payable {}

    function setConfig(uint256 cooldown_, uint256[3] calldata amountFor_) external {
        if (msg.sender != governance) revert NotGovernance();
        cooldown = cooldown_;
        amountFor = amountFor_;
        emit ConfigSet(cooldown_, amountFor_);
    }

    function drip() external returns (uint256 amount) {
        uint8 label = labels.labelOf(msg.sender);
        amount = amountFor[label];
        if (amount == 0) revert NothingForLabel(label);
        if (lastDrip[msg.sender] != 0 && block.timestamp < lastDrip[msg.sender] + cooldown) revert TooSoon();
        lastDrip[msg.sender] = block.timestamp;
        if (label == 1) {
            (,, bytes32 cred,) = labels.humans(msg.sender);
            if (lastDripCredential[cred] != 0 && block.timestamp < lastDripCredential[cred] + cooldown) revert TooSoon();
            lastDripCredential[cred] = block.timestamp;
        }
        if (amount > address(this).balance) amount = address(this).balance;
        emit Dripped(msg.sender, label, amount);
        (bool ok,) = msg.sender.call{value: amount}("");
        if (!ok) revert TransferFailed();
    }
}

/// @title LabelSwapGate: a DEX-side hook that reads labels
/// @notice A router or pool calls check(trader, amountIn) before a swap.
///         Each label has its own cap per hour on the input amount (0 = no
///         swaps for that label, type(uint256).max = no cap). The default
///         testnet setting: humans uncapped, registered agents capped (they
///         can be held to account), unlabelled accounts capped lower.
contract LabelSwapGate {
    ILabels public immutable labels;
    address public governance;
    uint256[3] public hourlyCap;
    mapping(address => uint256) public windowStart;
    mapping(address => uint256) public usedInWindow;
    mapping(address => bool) public isCaller; // routers / pools allowed to count volume

    event CapsSet(uint256[3] hourlyCap);
    event CallerSet(address caller, bool allowed);

    error NotGovernance();
    error NotCaller();
    error OverCap(uint8 label, uint256 cap);

    constructor(ILabels labels_, address governance_, uint256[3] memory hourlyCap_) {
        labels = labels_;
        governance = governance_;
        hourlyCap = hourlyCap_;
        emit CapsSet(hourlyCap_);
    }

    function setCaps(uint256[3] calldata caps) external {
        if (msg.sender != governance) revert NotGovernance();
        hourlyCap = caps;
        emit CapsSet(caps);
    }

    function setCaller(address c, bool allowed) external {
        if (msg.sender != governance) revert NotGovernance();
        isCaller[c] = allowed;
        emit CallerSet(c, allowed);
    }

    /// Counts amountIn against the trader's hourly cap for its label; reverts when over.
    function check(address trader, uint256 amountIn) external returns (uint8 label) {
        if (!isCaller[msg.sender]) revert NotCaller();
        label = labels.labelOf(trader);
        uint256 cap = hourlyCap[label];
        if (cap == type(uint256).max) return label;
        if (block.timestamp >= windowStart[trader] + 1 hours) {
            windowStart[trader] = block.timestamp;
            usedInWindow[trader] = 0;
        }
        uint256 used = usedInWindow[trader] + amountIn;
        if (used > cap) revert OverCap(label, cap);
        usedInWindow[trader] = used;
    }
}

contracts/HyperlaneLane.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// Minimal local copies of Hyperlane v3 interfaces (no Hyperlane package offline).
// Checked against hyperlane-xyz/hyperlane-monorepo at commit
// bc8cfcec461930ec005590bc838871f903a297a1 (main, 2026-10-21):
//   solidity/contracts/interfaces/IMailbox.sol             dispatch / quoteDispatch / localDomain
//   solidity/contracts/interfaces/IMessageRecipient.sol    handle(uint32, bytes32, bytes) payable
//   solidity/contracts/interfaces/IInterchainSecurityModule.sol  moduleType / verify, and
//     ISpecifiesInterchainSecurityModule.interchainSecurityModule()
// The Mailbox calls recipient.handle{value: msg.value}(origin, sender, body) after
// its ISM (the recipient's interchainSecurityModule(), or the Mailbox default when
// that is zero) verified the message.

interface IHyperlaneMailbox {
    function localDomain() external view returns (uint32);
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256 fee);
    // With a custom post-dispatch hook (IPostDispatchHook, an address in the ABI) instead of the default hook.
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody, bytes calldata customHookMetadata, address customHook) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody, bytes calldata customHookMetadata, address customHook) external view returns (uint256 fee);
}

interface IInterchainSecurityModule {
    function moduleType() external view returns (uint8);
    function verify(bytes calldata metadata, bytes calldata message) external returns (bool);
}

interface IMessageRecipient {
    function handle(uint32 origin, bytes32 sender, bytes calldata message) external payable;
}

/// BridgeAirlock as a lane sees it.
interface IAirlockLane {
    function attest(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external;
    function transferId(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external pure returns (bytes32);
}

/// @title HyperlaneLane: Hyperlane as one of BridgeAirlock's lanes (ZETAPHY side)
/// @notice Independent of NeuroLane: what it attests is decided by Hyperlane's
///         Mailbox and the ISM (validator set) that secures it, not by Neuro
///         runners. It accepts a message only
///           - from the configured Mailbox (msg.sender),
///           - from the configured origin domain and origin sender (the source
///             chain's HyperlaneLockBox, or a router speaking for it),
///           - describing a deposit of the configured source chain and contract;
///         and each transfer once. It then attests to the airlock exactly the
///         fields NeuroLane attests for the same deposit, so both lanes produce
///         the same transfer id: (srcChainId, srcContract, srcNonce, sender, to, amount).
///         Body: abi.encode(uint256 srcChainId, address srcContract, uint256 srcNonce,
///         address sender, address to, uint256 amount), 192 bytes.
///         Governance (a multisig) sets the config and an optional custom ISM;
///         until the source is configured every message is refused.
contract HyperlaneLane is IMessageRecipient {
    IAirlockLane public immutable airlock;
    address public governance;
    address public mailbox;
    uint32 public originDomain;
    bytes32 public originSender;
    uint256 public srcChainId;
    address public srcContract;
    /// Hyperlane reads this (ISpecifiesInterchainSecurityModule); zero = the Mailbox's default ISM.
    IInterchainSecurityModule public interchainSecurityModule;
    mapping(bytes32 => bool) public delivered;   // by transfer id: replay protection

    event ConfigSet(address mailbox, uint32 originDomain, bytes32 originSender, uint256 srcChainId, address srcContract);
    event IsmSet(address ism);
    event GovernanceSet(address governance);
    event Delivered(bytes32 indexed id, uint256 indexed srcNonce, address sender, address to, uint256 amount);

    error NotGovernance();
    error NotMailbox();
    error WrongOrigin(uint32 origin);
    error WrongSender(bytes32 sender);
    error WrongSource();
    error BadBody();
    error Replay(bytes32 id);
    error NoValue();

    constructor(IAirlockLane airlock_, address governance_, address mailbox_, uint32 originDomain_, bytes32 originSender_,
        uint256 srcChainId_, address srcContract_, IInterchainSecurityModule ism_)
    {
        require(address(airlock_) != address(0) && governance_ != address(0) && mailbox_ != address(0), "config");
        airlock = airlock_;
        governance = governance_;
        _config(mailbox_, originDomain_, originSender_, srcChainId_, srcContract_);
        interchainSecurityModule = ism_;
        emit IsmSet(address(ism_));
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    /// The Mailbox decides what this lane attests (BridgeAirlock.independentLanes).
    function laneController() external view returns (address) { return mailbox; }

    function setConfig(address mailbox_, uint32 originDomain_, bytes32 originSender_, uint256 srcChainId_, address srcContract_) external onlyGov {
        require(mailbox_ != address(0), "mailbox");
        _config(mailbox_, originDomain_, originSender_, srcChainId_, srcContract_);
    }

    function setInterchainSecurityModule(IInterchainSecurityModule ism) external onlyGov {
        interchainSecurityModule = ism;
        emit IsmSet(address(ism));
    }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "governance");
        governance = g;
        emit GovernanceSet(g);
    }

    function handle(uint32 origin, bytes32 sender, bytes calldata body) external payable {
        if (msg.sender != mailbox) revert NotMailbox();
        if (msg.value != 0) revert NoValue();
        if (origin != originDomain) revert WrongOrigin(origin);
        if (sender != originSender || sender == bytes32(0)) revert WrongSender(sender);
        if (body.length != 192) revert BadBody();
        (uint256 chain, address src, uint256 nonce, address from, address to, uint256 amount) =
            abi.decode(body, (uint256, address, uint256, address, address, uint256));
        if (chain != srcChainId || src != srcContract || src == address(0)) revert WrongSource();
        bytes32 id = airlock.transferId(chain, src, nonce, from, to, amount);
        if (delivered[id]) revert Replay(id);
        delivered[id] = true;
        emit Delivered(id, nonce, from, to, amount);
        airlock.attest(chain, src, nonce, from, to, amount);
    }

    function _config(address mailbox_, uint32 originDomain_, bytes32 originSender_, uint256 srcChainId_, address srcContract_) private {
        mailbox = mailbox_;
        originDomain = originDomain_;
        originSender = originSender_;
        srcChainId = srcChainId_;
        srcContract = srcContract_;
        emit ConfigSet(mailbox_, originDomain_, originSender_, srcChainId_, srcContract_);
    }
}

/// @title HyperlaneLockBox: the source-chain side, for both lanes at once
/// @notice Locks native coin, emits LockBox's `Locked` event (the Neuro runners
///         watch it, unchanged: `zetaphy bridge watch --lockbox <this>`) and
///         dispatches the same transfer through the Hyperlane Mailbox to the
///         HyperlaneLane on ZETAPHY. msg.value = amount + the Mailbox fee
///         (quoteLock). Like LockBox it has no refund path: a vetoed or held
///         transfer stays locked here.
///         `hook`: zero = the Mailbox's default hook. Otherwise every dispatch uses
///         this hook instead (e.g. the source chain's MerkleTreeHook alone, when the
///         default hook's gas paymaster does not quote the destination; the
///         Mailbox's required hook still runs). Set once, at deploy.
contract HyperlaneLockBox {
    IHyperlaneMailbox public immutable mailbox;
    uint32 public immutable destinationDomain;
    bytes32 public immutable recipient;      // HyperlaneLane on ZETAPHY
    address public immutable hook;           // zero = the Mailbox default hook
    uint256 public nonce;

    event Locked(uint256 indexed nonce, address indexed sender, address indexed to, uint256 amount);
    event Dispatched(uint256 indexed nonce, bytes32 messageId);

    constructor(IHyperlaneMailbox mailbox_, uint32 destinationDomain_, bytes32 recipient_, address hook_) {
        require(address(mailbox_) != address(0) && recipient_ != bytes32(0), "config");
        mailbox = mailbox_;
        destinationDomain = destinationDomain_;
        recipient = recipient_;
        hook = hook_;
    }

    function body(uint256 n, address sender, address to, uint256 amount) public view returns (bytes memory) {
        return abi.encode(block.chainid, address(this), n, sender, to, amount);
    }

    /// The Mailbox fee for the next lock (pay amount + this).
    function quoteLock(address to, uint256 amount) external view returns (uint256) {
        bytes memory b = body(nonce, msg.sender, to, amount);
        if (hook == address(0)) return mailbox.quoteDispatch(destinationDomain, recipient, b);
        return mailbox.quoteDispatch(destinationDomain, recipient, b, "", hook);
    }

    function lock(address to, uint256 amount) external payable returns (bytes32 messageId) {
        require(amount > 0 && to != address(0) && msg.value >= amount, "lock");
        uint256 n = nonce++;
        emit Locked(n, msg.sender, to, amount);
        bytes memory b = body(n, msg.sender, to, amount);
        messageId = hook == address(0)
            ? mailbox.dispatch{value: msg.value - amount}(destinationDomain, recipient, b)
            : mailbox.dispatch{value: msg.value - amount}(destinationDomain, recipient, b, "", hook);
        emit Dispatched(n, messageId);
    }
}

contracts/HyperlaneLockBoxV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// ZETAPHY Saphan, EVM routes, version 2: both directions, one stack per source chain.
//
//   source chain (Sepolia, Base Sepolia, Arbitrum Sepolia, ...)       ZETAPHY
//   HyperlaneLockBoxV2 --lock: Hyperlane message------------------->  HyperlaneLane -> BridgeAirlock -> BridgeGuard mints
//                      <--release: Hyperlane message, verified by--   HyperlaneOutbox <- BridgeGuard burns (outbound route)
//                         OUR validator(s) for origin ZETAPHY
//
// Each source chain has its own BridgeGuard and so its own bridged token on ZETAPHY
// (docs/SAPHAN-MULTICHAIN.md): a hole in one source chain's route can only mint that
// route's token, which only that route's outbox can burn, and only that route's
// lockbox releases for it. Nobody can drain the ETH locked on chain B with a message
// or a token of chain A.
//
// Local copies of the Hyperlane v3 interfaces, checked against hyperlane-xyz/hyperlane-monorepo
// at commit 1aadbba0696ecf96ed4c06f78c978d08db22c0ad (main, 2026-10-28): IMailbox,
// IMessageRecipient, IInterchainSecurityModule and ISpecifiesInterchainSecurityModule. Named
// apart from HyperlaneLane.sol's copies (the build compiles every file in one unit).

interface ISaphanMailbox {
    function localDomain() external view returns (uint32);
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256 fee);
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody, bytes calldata customHookMetadata, address customHook) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody, bytes calldata customHookMetadata, address customHook) external view returns (uint256 fee);
}

interface ISaphanIsm {
    function moduleType() external view returns (uint8);
    function verify(bytes calldata metadata, bytes calldata message) external returns (bool);
}

/// BridgeGuard as an outbound adapter sees it: burns `amount` of the route's token from `from`.
interface IGuardOutbound {
    function outbound(bytes32 route, address from, uint256 amount) external;
}

/// @title HyperlaneLockBoxV2: the source-chain side, both directions
/// @notice Lock (source -> ZETAPHY): exactly HyperlaneLockBox's message and its `Locked`
///         event (the Neuro runners watch it, `zetaphy bridge watch --lockbox <this>`), so the
///         HyperlaneLane on ZETAPHY is unchanged. msg.value = amount + quoteLock(); the Mailbox
///         gets exactly the quote and anything above is sent back.
///
///         Release (ZETAPHY -> source): handle() takes a message only
///           - from the configured Mailbox (msg.sender), after the ISM this contract names
///             (interchainSecurityModule: a multisig ISM of OUR validators for origin ZETAPHY,
///             never the Mailbox default; set at deploy, changed only by governance),
///           - from origin domain ZETAPHY and the one HyperlaneOutbox of this route (sender),
///           - whose body names ZETAPHY's chain id and that outbox as the source, and this
///             chain and this contract as the destination,
///         and each message once. It never pays at once: the release is queued and can be
///         claimed (by anyone, paid to its receiver) after `releaseDelay`, while
///           - not vetoed (a guardian or governance vetoes during the delay or later),
///           - not paused (guardians pause; only governance unpauses),
///           - within the daily release limit (over it, the claim waits for the next day),
///           - within what this contract holds for locks (`locked`: locks minus releases), so
///             even a forged message can never take more than this route's own deposits.
///         A message is never refused for a limit or a pause: it is recorded, and the money
///         moves only when every check passes (nothing depends on the relayer retrying).
///
///         Roles: governance (the source chain's timelock: its multisig proposes, 48 h) changes
///         the ISM, raises limits, lifts vetoes, unpauses; guardians (a multisig) only reduce
///         risk, at once: pause, veto, lower the daily limit, lengthen the delay.
contract HyperlaneLockBoxV2 {
    struct Release {
        address to;
        uint64 readyAt;      // zero: no such release
        bool claimed;
        bool vetoed;
        uint256 amount;
    }

    ISaphanMailbox public immutable mailbox;
    uint32 public immutable zetaphyDomain;   // ZETAPHY's Hyperlane domain (77390)
    uint256 public immutable zetaphyChainId; // ZETAPHY's EVM chain id, as the outbox writes it (77390)
    bytes32 public immutable recipient;      // HyperlaneLane on ZETAPHY (locks go there)
    bytes32 public immutable remoteSender;   // HyperlaneOutbox on ZETAPHY (the only sender of releases)
    address public immutable hook;           // zero = the Mailbox default hook, for locks

    uint64 public constant MAX_RELEASE_DELAY = 30 days;

    address public governance;
    mapping(address => bool) public guardian;
    /// Hyperlane reads this (ISpecifiesInterchainSecurityModule). Never zero here: the Mailbox's
    /// default ISM is Hyperlane's, which does not know our validators for origin ZETAPHY.
    ISaphanIsm public interchainSecurityModule;
    bool public paused;
    uint256 public dailyLimit;               // wei released per day (UTC day)
    uint256 public releasedToday;
    uint64 public day;
    uint64 public releaseDelay;              // seconds between a message and its claim

    uint256 public nonce;                    // locks
    uint256 public received;                 // release messages recorded (the relayer workflow compares it with the outbox's nonce)
    uint256 public locked;                   // backing: everything locked minus everything released
    /// Each lock's transfer id (keccak256 of its body = BridgeAirlock.transferId): the relayer workflow asks the
    /// HyperlaneLane on ZETAPHY whether the latest one arrived (delivered(id)) instead of running for days.
    mapping(uint256 => bytes32) public transferIds;
    mapping(bytes32 => Release) public releases; // by keccak256(body)

    event Locked(uint256 indexed nonce, address indexed sender, address indexed to, uint256 amount);
    event Dispatched(uint256 indexed nonce, bytes32 messageId);
    event ReleaseQueued(bytes32 indexed id, uint256 indexed srcNonce, address sender, address indexed to, uint256 amount, uint64 readyAt);
    event Released(bytes32 indexed id, address indexed to, uint256 amount);
    event ReleaseVetoed(bytes32 indexed id, address indexed by);
    event VetoLifted(bytes32 indexed id);
    event Paused(address indexed by);
    event Unpaused();
    event IsmSet(address ism);
    event GovernanceSet(address governance);
    event GuardianSet(address indexed who, bool on);
    event DailyLimitSet(uint256 limit);
    event ReleaseDelaySet(uint64 delay);

    error NotGovernance();
    error NotGuardian();
    error NotMailbox();
    error WrongOrigin(uint32 origin);
    error WrongSender(bytes32 sender);
    error WrongSource();
    error WrongDestination();
    error BadBody();
    error Replay(bytes32 id);
    error NoValue();
    error IsPaused();
    error NoRelease();
    error AlreadyClaimed();
    error IsVetoed();
    error NotReady(uint64 readyAt);
    error OverLimit(uint256 remaining);
    error OverBacking(uint256 locked);
    error PayFailed();
    error Fee(uint256 needed);

    constructor(ISaphanMailbox mailbox_, uint32 zetaphyDomain_, uint256 zetaphyChainId_, bytes32 recipient_, bytes32 remoteSender_,
        address hook_, ISaphanIsm ism_, address governance_, address guardian_, uint256 dailyLimit_, uint64 releaseDelay_)
    {
        require(address(mailbox_) != address(0) && recipient_ != bytes32(0) && remoteSender_ != bytes32(0) && zetaphyChainId_ != 0
            && address(ism_) != address(0) && governance_ != address(0) && releaseDelay_ <= MAX_RELEASE_DELAY, "config");
        mailbox = mailbox_;
        zetaphyDomain = zetaphyDomain_;
        zetaphyChainId = zetaphyChainId_;
        recipient = recipient_;
        remoteSender = remoteSender_;
        hook = hook_;
        interchainSecurityModule = ism_;
        governance = governance_;
        dailyLimit = dailyLimit_;
        releaseDelay = releaseDelay_;
        emit IsmSet(address(ism_));
        emit GovernanceSet(governance_);
        emit DailyLimitSet(dailyLimit_);
        emit ReleaseDelaySet(releaseDelay_);
        if (guardian_ != address(0)) { guardian[guardian_] = true; emit GuardianSet(guardian_, true); }
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }
    modifier onlyGuardian() { if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian(); _; }

    // ---------------------------------------------------------------- lock (source -> ZETAPHY)

    /// The same body as HyperlaneLockBox (192 bytes), so the HyperlaneLane on ZETAPHY is unchanged.
    function body(uint256 n, address sender, address to, uint256 amount) public view returns (bytes memory) {
        return abi.encode(block.chainid, address(this), n, sender, to, amount);
    }

    /// The Mailbox fee for the next lock (pay amount + this).
    function quoteLock(address to, uint256 amount) public view returns (uint256) {
        return _quote(body(nonce, msg.sender, to, amount));
    }

    function lock(address to, uint256 amount) external payable returns (bytes32 messageId) {
        if (paused) revert IsPaused();
        require(amount > 0 && to != address(0) && msg.value >= amount, "lock");
        uint256 n = nonce++;
        bytes memory b = body(n, msg.sender, to, amount);
        uint256 fee = _quote(b);
        if (msg.value < amount + fee) revert Fee(amount + fee);
        locked += amount;
        transferIds[n] = keccak256(b);
        emit Locked(n, msg.sender, to, amount);
        messageId = hook == address(0)
            ? mailbox.dispatch{value: fee}(zetaphyDomain, recipient, b)
            : mailbox.dispatch{value: fee}(zetaphyDomain, recipient, b, "", hook);
        emit Dispatched(n, messageId);
        uint256 extra = msg.value - amount - fee;
        if (extra > 0) {
            (bool ok, ) = msg.sender.call{value: extra}("");
            if (!ok) revert PayFailed();
        }
    }

    function _quote(bytes memory b) private view returns (uint256) {
        return hook == address(0) ? mailbox.quoteDispatch(zetaphyDomain, recipient, b) : mailbox.quoteDispatch(zetaphyDomain, recipient, b, "", hook);
    }

    // ---------------------------------------------------------------- release (ZETAPHY -> source)

    /// Called by the Mailbox after interchainSecurityModule verified the message.
    /// Body (256 bytes): abi.encode(uint256 srcChainId, address srcContract, uint256 srcNonce,
    /// address sender, address to, uint256 amount, uint256 dstChainId, address dstContract).
    function handle(uint32 origin, bytes32 sender, bytes calldata b) external payable {
        if (msg.sender != address(mailbox)) revert NotMailbox();
        if (msg.value != 0) revert NoValue();
        if (origin != zetaphyDomain) revert WrongOrigin(origin);
        if (sender != remoteSender) revert WrongSender(sender);
        if (b.length != 256) revert BadBody();
        (uint256 srcChain, address src, uint256 n, address from, address to, uint256 amount, uint256 dstChain, address dst) =
            abi.decode(b, (uint256, address, uint256, address, address, uint256, uint256, address));
        if (srcChain != zetaphyChainId || bytes32(uint256(uint160(src))) != remoteSender) revert WrongSource();
        if (dstChain != block.chainid || dst != address(this)) revert WrongDestination();
        if (to == address(0) || amount == 0) revert BadBody();
        bytes32 id = keccak256(b);
        if (releases[id].readyAt != 0) revert Replay(id);
        uint64 readyAt = uint64(block.timestamp) + releaseDelay;
        releases[id] = Release(to, readyAt, false, false, amount);
        received += 1;
        emit ReleaseQueued(id, n, from, to, amount, readyAt);
    }

    /// Anyone: pays a queued release to its receiver once every check passes.
    function claim(bytes32 id) external {
        Release storage r = releases[id];
        if (r.readyAt == 0) revert NoRelease();
        if (r.claimed) revert AlreadyClaimed();
        if (r.vetoed) revert IsVetoed();
        if (paused) revert IsPaused();
        if (block.timestamp < r.readyAt) revert NotReady(r.readyAt);
        uint64 today = uint64(block.timestamp / 1 days);
        if (day != today) { day = today; releasedToday = 0; }
        uint256 amount = r.amount;
        if (releasedToday + amount > dailyLimit) revert OverLimit(dailyLimit > releasedToday ? dailyLimit - releasedToday : 0);
        if (amount > locked) revert OverBacking(locked);
        r.claimed = true;
        releasedToday += amount;
        locked -= amount;
        emit Released(id, r.to, amount);
        (bool ok, ) = r.to.call{value: amount}("");
        if (!ok) revert PayFailed();
    }

    /// What can still be released today.
    function remainingToday() external view returns (uint256) {
        uint256 used = day == uint64(block.timestamp / 1 days) ? releasedToday : 0;
        return dailyLimit > used ? dailyLimit - used : 0;
    }

    // ---------------------------------------------------------------- guardians: only reduce risk, at once

    function pause() external onlyGuardian { paused = true; emit Paused(msg.sender); }

    /// Stops a release that is not paid yet (during its delay, or while it waits for a limit).
    function veto(bytes32 id) external onlyGuardian {
        Release storage r = releases[id];
        if (r.readyAt == 0) revert NoRelease();
        if (r.claimed) revert AlreadyClaimed();
        r.vetoed = true;
        emit ReleaseVetoed(id, msg.sender);
    }

    function lowerDailyLimit(uint256 v) external onlyGuardian {
        require(v < dailyLimit, "lower only");
        dailyLimit = v;
        emit DailyLimitSet(v);
    }

    function raiseReleaseDelay(uint64 d) external onlyGuardian {
        require(d > releaseDelay && d <= MAX_RELEASE_DELAY, "raise only");
        releaseDelay = d;
        emit ReleaseDelaySet(d);
    }

    // ---------------------------------------------------------------- governance (the source chain's timelock)

    function unpause() external onlyGov { paused = false; emit Unpaused(); }

    function liftVeto(bytes32 id) external onlyGov {
        Release storage r = releases[id];
        if (r.readyAt == 0) revert NoRelease();
        r.vetoed = false;
        emit VetoLifted(id);
    }

    function setDailyLimit(uint256 v) external onlyGov { dailyLimit = v; emit DailyLimitSet(v); }

    function setReleaseDelay(uint64 d) external onlyGov {
        require(d <= MAX_RELEASE_DELAY, "delay");
        releaseDelay = d;
        emit ReleaseDelaySet(d);
    }

    /// A new ISM (e.g. more of our validators, a higher threshold). Never zero.
    function setInterchainSecurityModule(ISaphanIsm ism) external onlyGov {
        require(address(ism) != address(0), "ism");
        interchainSecurityModule = ism;
        emit IsmSet(address(ism));
    }

    function setGuardian(address who, bool on) external onlyGov { guardian[who] = on; emit GuardianSet(who, on); }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "governance");
        governance = g;
        emit GovernanceSet(g);
    }
}

/// @title HyperlaneOutbox: the ZETAPHY side of the way back (ZETAPHY -> one source chain)
/// @notice send(to, amount) burns `amount` of the route's bridged token from the caller through
///         BridgeGuard (its outbound route for this outbox: daily limit, hard cap, pause,
///         vaccine) and dispatches a release to the source chain's HyperlaneLockBoxV2 through
///         ZETAPHY's Mailbox. Everything it may do is fixed at deploy (no admin): which guard
///         route burns, which domain, chain and lockbox it sends to. Closing it is the guard's:
///         a guardian pauses, governance disables the outbound route.
///         Body (256 bytes): abi.encode(block.chainid, this, nonce, sender, to, amount,
///         destinationChainId, the lockbox): the lockbox checks every field.
contract HyperlaneOutbox {
    IGuardOutbound public immutable guard;
    bytes32 public immutable route;              // this outbox's outbound route in the guard
    ISaphanMailbox public immutable mailbox;     // ZETAPHY's Mailbox
    uint32 public immutable destinationDomain;   // the source chain's Hyperlane domain
    uint256 public immutable destinationChainId; // the source chain's EVM chain id
    bytes32 public immutable recipient;          // the source chain's HyperlaneLockBoxV2
    address public immutable hook;               // zero = the Mailbox default hook
    uint256 public nonce;

    event Sent(uint256 indexed nonce, address indexed sender, address indexed to, uint256 amount, bytes32 messageId);

    error Fee(uint256 needed);
    error PayFailed();

    constructor(IGuardOutbound guard_, bytes32 route_, ISaphanMailbox mailbox_, uint32 destinationDomain_, uint256 destinationChainId_,
        bytes32 recipient_, address hook_)
    {
        require(address(guard_) != address(0) && address(mailbox_) != address(0) && recipient_ != bytes32(0) && destinationChainId_ != 0, "config");
        guard = guard_;
        route = route_;
        mailbox = mailbox_;
        destinationDomain = destinationDomain_;
        destinationChainId = destinationChainId_;
        recipient = recipient_;
        hook = hook_;
    }

    function body(uint256 n, address sender, address to, uint256 amount) public view returns (bytes memory) {
        return abi.encode(block.chainid, address(this), n, sender, to, amount, destinationChainId, address(uint160(uint256(recipient))));
    }

    /// The Mailbox fee for the next send (msg.value of send).
    function quoteSend(address to, uint256 amount) public view returns (uint256) {
        return _quote(body(nonce, msg.sender, to, amount));
    }

    function send(address to, uint256 amount) external payable returns (bytes32 messageId) {
        require(amount > 0 && to != address(0), "send");
        uint256 n = nonce++;
        bytes memory b = body(n, msg.sender, to, amount);
        uint256 fee = _quote(b);
        if (msg.value < fee) revert Fee(fee);
        guard.outbound(route, msg.sender, amount); // burns; reverts when closed, paused, over a limit or held
        messageId = hook == address(0)
            ? mailbox.dispatch{value: fee}(destinationDomain, recipient, b)
            : mailbox.dispatch{value: fee}(destinationDomain, recipient, b, "", hook);
        emit Sent(n, msg.sender, to, amount, messageId);
        if (msg.value > fee) {
            (bool ok, ) = msg.sender.call{value: msg.value - fee}("");
            if (!ok) revert PayFailed();
        }
    }

    function _quote(bytes memory b) private view returns (uint256) {
        return hook == address(0) ? mailbox.quoteDispatch(destinationDomain, recipient, b) : mailbox.quoteDispatch(destinationDomain, recipient, b, "", hook);
    }
}

contracts/IntentExecutor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IIntentERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
}

/// @title IntentExecutor: Proof of Intent (testnet)
/// @notice A user signs WHAT they want (an intent: send / swap / stake with
///         limits), not HOW. Anyone (an off-chain AI or compiler, "the
///         solver") turns the intent into calls and submits them here. This
///         contract runs the calls and then checks the effects on chain:
///           - the user's tokenIn balance went down by at most maxIn,
///           - the recipient's tokenOut balance went up by at least minOut,
///           - this contract keeps nothing (leftover tokenIn back to the user,
///             any tokenOut it holds on to the recipient),
///           - the deadline has not passed, the nonce is unused,
///           - every call went to a contract the user listed (targetsHash),
///             never to tokenIn, tokenOut, the user or this contract, with no
///             value, and never with an ERC-20 transferFrom selector,
///         and reverts everything otherwise. The solver cannot take more than
///         the user signed for, whatever calls it sends.
///
///         Signatures: EIP-712 by the user's ECDSA key (sigType 0), or the
///         same EIP-712 digest signed with an ML-DSA-44 key whose keccak256
///         the user registered with setPqKey (sigType 1), checked by
///         ZETAPHY's precompile at 0x…0900.
///
///         Tokens are ERC-20 (the native coin is an ERC-20 at
///         0xEeee…EEeE on ZETAPHY). Approve this contract for at most what
///         you sign for; approve a fresh amount per intent.
contract IntentExecutor {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;

    uint8 public constant SEND = 1;
    uint8 public constant SWAP = 2;
    uint8 public constant STAKE = 3;
    uint256 public constant MAX_CALLS = 8;

    // Selectors a solver call may never use: the executor does its own (temporary) approval of `spender`.
    bytes4 private constant TRANSFER_FROM = 0x23b872dd;
    bytes4 private constant APPROVE = 0x095ea7b3;
    bytes4 private constant INCREASE_ALLOWANCE = 0x39509351;
    bytes4 private constant SET_APPROVAL_FOR_ALL = 0xa22cb465;
    bytes4 private constant PERMIT = 0xd505accf;

    struct Intent {
        address user;
        uint8 kind;
        address tokenIn;
        uint256 maxIn;
        address tokenOut;
        uint256 minOut;
        address recipient;
        bytes32 targetsHash; // keccak256(abi.encode(address[] targets)); 0 for SEND
        uint256 nonce;
        uint256 deadline;
    }

    struct Call {
        address target;
        bytes data;
    }

    bytes32 public constant INTENT_TYPEHASH = keccak256(
        "Intent(address user,uint8 kind,address tokenIn,uint256 maxIn,address tokenOut,uint256 minOut,address recipient,bytes32 targetsHash,uint256 nonce,uint256 deadline)"
    );
    bytes32 private constant DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");

    mapping(address => mapping(uint256 => bool)) public nonceUsed;
    mapping(address => bytes32) public pqKeyOf;
    uint256 private locked = 1;

    event IntentExecuted(address indexed user, uint256 indexed nonce, bytes32 indexed intentHash, address solver, uint256 spent, uint256 received);
    event NonceCancelled(address indexed user, uint256 nonce);
    event PqKeySet(address indexed user, bytes32 keyHash);

    error Expired();
    error NonceUsed();
    error BadSignature();
    error BadIntent();
    error TargetNotAllowed(address target);
    error ForbiddenCall(address target);
    error CallFailed(uint256 index, bytes reason);
    error SpentTooMuch(uint256 spent, uint256 maxIn);
    error ReceivedTooLittle(uint256 received, uint256 minOut);
    error Leftover();
    error TokenFailed();
    error Reentrancy();

    modifier nonReentrant() {
        if (locked != 1) revert Reentrancy();
        locked = 2;
        _;
        locked = 1;
    }

    function domainSeparator() public view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN_TYPEHASH, keccak256("ZETAPHY IntentExecutor"), keccak256("1"), block.chainid, address(this)));
    }

    function intentHash(Intent calldata i) public pure returns (bytes32) {
        return keccak256(abi.encode(INTENT_TYPEHASH, i.user, i.kind, i.tokenIn, i.maxIn, i.tokenOut, i.minOut,
            i.recipient, i.targetsHash, i.nonce, i.deadline));
    }

    /// The EIP-712 digest the user signs (eth_signTypedData_v4 gives the same).
    function digest(Intent calldata i) public view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", domainSeparator(), intentHash(i)));
    }

    /// Registers (or with 0 removes) the ML-DSA-44 key that may sign this account's intents.
    function setPqKey(bytes32 keyHash) external {
        pqKeyOf[msg.sender] = keyHash;
        emit PqKeySet(msg.sender, keyHash);
    }

    function cancel(uint256 nonce) external {
        nonceUsed[msg.sender][nonce] = true;
        emit NonceCancelled(msg.sender, nonce);
    }

    /// How the user signed: sigType 0 = ECDSA (65 bytes r‖s‖v), 1 = ML-DSA-44 (pqPublicKey + sig).
    struct Auth {
        uint8 sigType;
        bytes sig;
        bytes pqPublicKey;
    }

    /// What the solver does: calls to `targets` only (must hash to intent.targetsHash);
    /// `spender` (one of the targets, or 0) is approved for the pulled tokenIn during the calls.
    struct Plan {
        address[] targets;
        address spender;
        Call[] calls;
    }

    function execute(Intent calldata intent, Auth calldata auth, Plan calldata plan)
        external nonReentrant returns (uint256 spent, uint256 received)
    {
        if (block.timestamp > intent.deadline) revert Expired();
        if (nonceUsed[intent.user][intent.nonce]) revert NonceUsed();
        if (intent.user == address(0) || intent.recipient == address(0) || intent.maxIn == 0) revert BadIntent();
        _checkSig(intent, auth);
        nonceUsed[intent.user][intent.nonce] = true;

        uint256 userBefore = IIntentERC20(intent.tokenIn).balanceOf(intent.user);
        uint256 recvBefore = IIntentERC20(intent.tokenOut).balanceOf(intent.recipient);

        if (intent.kind == SEND) {
            // to oneself nothing would move: refuse rather than pretend
            if (intent.tokenIn != intent.tokenOut || plan.calls.length != 0 || intent.minOut > intent.maxIn
                || intent.recipient == intent.user) revert BadIntent();
            _safe(intent.tokenIn, abi.encodeCall(IIntentERC20.transferFrom, (intent.user, intent.recipient, intent.minOut)));
        } else if (intent.kind == SWAP || intent.kind == STAKE) {
            _runPlan(intent, plan);
        } else {
            revert BadIntent();
        }

        spent = _moved(IIntentERC20(intent.tokenIn).balanceOf(intent.user), userBefore);
        if (spent > intent.maxIn) revert SpentTooMuch(spent, intent.maxIn);
        received = _moved(recvBefore, IIntentERC20(intent.tokenOut).balanceOf(intent.recipient));
        if (received < intent.minOut) revert ReceivedTooLittle(received, intent.minOut);
        emit IntentExecuted(intent.user, intent.nonce, intentHash(intent), msg.sender, spent, received);
    }

    /// hi - lo when hi > lo, else 0 (how far a balance moved).
    function _moved(uint256 lo, uint256 hi) private pure returns (uint256) {
        return hi > lo ? hi - lo : 0;
    }

    function _runPlan(Intent calldata intent, Plan calldata plan) private {
        if (intent.tokenIn == intent.tokenOut || plan.calls.length == 0 || plan.calls.length > MAX_CALLS) revert BadIntent();
        if (keccak256(abi.encode(plan.targets)) != intent.targetsHash) revert BadIntent();
        IIntentERC20 tin = IIntentERC20(intent.tokenIn);
        IIntentERC20 tout = IIntentERC20(intent.tokenOut);
        uint256 inBefore = tin.balanceOf(address(this));
        uint256 outBefore = tout.balanceOf(address(this));
        _safe(address(tin), abi.encodeCall(IIntentERC20.transferFrom, (intent.user, address(this), intent.maxIn)));
        if (plan.spender != address(0)) {
            _allowed(plan.spender, plan.targets, intent);
            _safe(address(tin), abi.encodeCall(IIntentERC20.approve, (plan.spender, intent.maxIn)));
        }
        for (uint256 k = 0; k < plan.calls.length; k++) _call(k, plan.calls[k], plan.targets, intent);
        if (plan.spender != address(0)) _safe(address(tin), abi.encodeCall(IIntentERC20.approve, (plan.spender, 0)));
        // leftovers: tokenIn back to the user, tokenOut on to the recipient
        uint256 inNow = tin.balanceOf(address(this));
        if (inNow > inBefore) _safe(address(tin), abi.encodeCall(IIntentERC20.transfer, (intent.user, inNow - inBefore)));
        uint256 outNow = tout.balanceOf(address(this));
        if (outNow > outBefore) _safe(address(tout), abi.encodeCall(IIntentERC20.transfer, (intent.recipient, outNow - outBefore)));
        if (tin.balanceOf(address(this)) != inBefore || tout.balanceOf(address(this)) != outBefore) revert Leftover();
    }

    function _call(uint256 k, Call calldata c, address[] calldata targets, Intent calldata intent) private {
        _allowed(c.target, targets, intent);
        if (c.data.length >= 4) {
            bytes4 sel = bytes4(c.data[0:4]);
            if (sel == TRANSFER_FROM || sel == APPROVE || sel == INCREASE_ALLOWANCE || sel == SET_APPROVAL_FOR_ALL || sel == PERMIT) {
                revert ForbiddenCall(c.target);
            }
        }
        (bool ok, bytes memory ret) = c.target.call(c.data);
        if (!ok) revert CallFailed(k, ret);
    }

    /// A call target must be listed, and never tokenIn, the user, this contract or 0. tokenOut is
    /// refused too, except for STAKE, where the vault is both the target and the receipt token
    /// (ERC-4626 style); the balance checks still hold there.
    function _allowed(address t, address[] calldata targets, Intent calldata intent) private view {
        if (t == intent.tokenIn || t == intent.user || t == address(this) || t == address(0)) revert ForbiddenCall(t);
        if (t == intent.tokenOut && intent.kind != STAKE) revert ForbiddenCall(t);
        for (uint256 i = 0; i < targets.length; i++) if (targets[i] == t) return;
        revert TargetNotAllowed(t);
    }

    function _checkSig(Intent calldata intent, Auth calldata auth) private view {
        bytes32 d = digest(intent);
        if (auth.sigType == 0) {
            bytes calldata sig = auth.sig;
            if (sig.length != 65) revert BadSignature();
            uint8 v = uint8(sig[64]);
            if (v < 27) v += 27;
            if (uint256(bytes32(sig[32:64])) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) revert BadSignature();
            address got = ecrecover(d, v, bytes32(sig[0:32]), bytes32(sig[32:64]));
            if (got == address(0) || got != intent.user) revert BadSignature();
        } else if (auth.sigType == 1) {
            bytes32 kh = pqKeyOf[intent.user];
            if (kh == bytes32(0) || keccak256(auth.pqPublicKey) != kh) revert BadSignature();
            (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(uint8(44), d, auth.pqPublicKey, auth.sig));
            if (!ok || ret.length != 32 || uint256(bytes32(ret)) != 1) revert BadSignature();
        } else {
            revert BadSignature();
        }
    }

    /// ERC-20 call that accepts tokens returning nothing (USDT style) but not false or a revert.
    function _safe(address token, bytes memory data) private {
        (bool ok, bytes memory ret) = token.call(data);
        if (!ok || (ret.length != 0 && !abi.decode(ret, (bool))) || (ret.length == 0 && token.code.length == 0)) revert TokenFailed();
    }
}

contracts/MockMailbox.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IMockRecipient {
    function handle(uint32 origin, bytes32 sender, bytes calldata message) external payable;
}

/// @title MockMailbox: TEST ONLY stand-in for a Hyperlane v3 Mailbox
/// @notice dispatch() records the message (and charges `fee`); deliver() plays
///         the relayer + ISM on the destination: it calls handle() as the real
///         Mailbox does after its ISM verified the message. Anyone may deliver
///         anything here: it stands for a Mailbox, never use it on a real chain.
contract MockMailbox {
    uint32 public immutable localDomain;
    uint256 public fee;
    uint32 public nonce;

    address public lastHook;   // the custom hook of the last dispatch (zero = default)

    event Dispatch(address indexed sender, uint32 indexed destination, bytes32 indexed recipient, bytes message);

    constructor(uint32 localDomain_) { localDomain = localDomain_; }

    function setFee(uint256 f) external { fee = f; }

    function quoteDispatch(uint32, bytes32, bytes calldata) external view returns (uint256) { return fee; }

    function quoteDispatch(uint32, bytes32, bytes calldata, bytes calldata, address) external view returns (uint256) { return fee; }

    function dispatch(uint32 destination, bytes32 recipient, bytes calldata body, bytes calldata, address hook) external payable returns (bytes32 id) {
        lastHook = hook;
        return _dispatch(destination, recipient, body);
    }

    function dispatch(uint32 destination, bytes32 recipient, bytes calldata body) external payable returns (bytes32 id) {
        lastHook = address(0);
        return _dispatch(destination, recipient, body);
    }

    function _dispatch(uint32 destination, bytes32 recipient, bytes calldata body) private returns (bytes32 id) {
        require(msg.value >= fee, "fee");
        id = keccak256(abi.encode(localDomain, nonce++, msg.sender, destination, recipient, body));
        emit Dispatch(msg.sender, destination, recipient, body);
    }

    function deliver(uint32 origin, bytes32 sender, address recipient, bytes calldata body) external {
        IMockRecipient(recipient).handle(origin, sender, body);
    }
}

contracts/NeuroControl.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title NeuroControl: the governance knobs of Neuro (testnet)
/// @notice One place where the vote steers Neuro, separate from the coin:
///           - paused(): the Neuro stop button. NeuroJobs takes no new
///             requests or commits and runners stop taking jobs. It never
///             touches coin transfers, staking, bridges or withdrawals.
///             A guardian may pull it at once; only governance releases it.
///           - skills: a skill id (sha256 of Neuro's code, `zetaphy neuro
///             skill-id`) must be approved by a vote before jobs use it;
///             new jobs record activeSkill().
///           - the defender roster: runners governance allows to sit in the
///             4 defender seats of NeuroJobs (filled by its regrow()).
///           - release(runner): lets a quarantined runner work again.
///           - maxBodies: the cap on elastic bodies; maxRegrowPerHour: the
///             cap on refilling defender seats after an attack.
///           - communityFund: receives 5% of every job fee. The burned 5%
///             goes to BURN, an address nobody has a key for: it is locked
///             forever (still counted in the bank supply, never spendable).
///           - chains: the chain keys ("bsc", "eth", ...) NeuroJobs takes
///             requests for. A request for any other chain reverts, so fake
///             requests for chains no runner reads cannot inflate the bodies.
///             `zetaphy deploy` seeds it with the chains the runner supports.
///           - challenges: challengeBond (the least bond to challenge a
///             verdict; NeuroJobs asks max(2 x fee, this)), challengeWindow
///             (seconds after a quorum in which anyone may challenge; 0 =
///             NeuroJobs' jobTimeout) and defenderTimeout (a defender silent
///             longer than this loses its seat at the next regrow).
///         Governance is the chain's gov module (its EVM address, called
///         through a MsgEVMCall proposal: zetaphy-chain/gov.sh neuro ...) or
///         a SimpleMultisig.
///
///         Small read interface used by other contracts:
///           paused() returns (bool)
///           activeSkill() returns (bytes32)
///           defenderApproved(address) returns (bool)
///           releasedAt(address) returns (uint64)
///           maxBodies() / maxRegrowPerHour() returns (uint256)
///           communityFund() returns (address)
///           chainAllowed(bytes32) returns (bool)
///           challengeBond() / challengeWindow() / defenderTimeout() returns (uint256)
contract NeuroControl {
    /// Locked forever: no key exists for it.
    address public constant BURN = 0x000000000000000000000000000000000000dEaD;
    /// Bodies never go below the four defender seats.
    uint256 public constant MIN_BODIES = 4;
    uint256 public constant MAX_BODIES = 1000;
    uint256 public constant MAX_ROSTER = 32;
    uint256 public constant MAX_CHAINS_PER_CALL = 64;
    /// Bounds of the challenge window and the defender timeout (seconds).
    uint256 public constant MIN_WINDOW = 60;
    uint256 public constant MAX_WINDOW = 7 days;

    address public governance;
    mapping(address => bool) public guardian;
    bool public paused;

    mapping(bytes32 => bool) public skillApproved;
    bytes32 public activeSkill;

    mapping(address => bool) public defenderApproved;
    address[] private _roster;

    /// When governance last released a runner from quarantine; a quarantine
    /// that started after this still holds.
    mapping(address => uint64) public releasedAt;

    uint256 public maxBodies;
    uint256 public maxRegrowPerHour;
    address public communityFund;

    /// Chain keys (bytes32 of e.g. "bsc") NeuroJobs accepts requests for.
    mapping(bytes32 => bool) public chainAllowed;

    /// Least challenge bond (NeuroJobs asks max(2 x job fee, this)).
    uint256 public challengeBond = 1 ether;
    /// Seconds after a quorum in which a verdict may be challenged; 0 = NeuroJobs' jobTimeout.
    uint256 public challengeWindow;
    /// A defender whose last heartbeat (or commit/reveal) is older than this loses its seat.
    uint256 public defenderTimeout = 6 hours;

    event GovernanceChanged(address governance);
    event GuardianSet(address indexed who, bool allowed);
    event Paused(address indexed by);
    event Unpaused();
    event SkillApproved(bytes32 indexed id);
    event SkillRevoked(bytes32 indexed id);
    event ActiveSkill(bytes32 indexed id);
    event DefenderApproved(address indexed runner);
    event DefenderRemoved(address indexed runner);
    event Released(address indexed runner);
    event MaxBodies(uint256 value);
    event MaxRegrowPerHour(uint256 value);
    event CommunityFund(address fund);
    event ChainApproved(bytes32 indexed chain);
    event ChainRemoved(bytes32 indexed chain);
    event ChallengeBond(uint256 value);
    event ChallengeWindow(uint256 value);
    event DefenderTimeout(uint256 value);

    error NotGovernance();
    error NotGuardian();
    error BadValue();
    error NotApproved();
    error SkillInUse();

    constructor(address governance_, address communityFund_, uint256 maxBodies_, uint256 maxRegrowPerHour_) {
        if (governance_ == address(0) || communityFund_ == address(0)) revert BadValue();
        if (maxBodies_ < MIN_BODIES || maxBodies_ > MAX_BODIES || maxRegrowPerHour_ == 0) revert BadValue();
        governance = governance_;
        communityFund = communityFund_;
        maxBodies = maxBodies_;
        maxRegrowPerHour = maxRegrowPerHour_;
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    // ---- stop button ----

    /// A guardian (or governance) stops Neuro at once.
    function pause() external {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
        paused = true;
        emit Paused(msg.sender);
    }

    /// Only a vote starts it again.
    function unpause() external onlyGovernance {
        paused = false;
        emit Unpaused();
    }

    function setGuardian(address who, bool allowed) external onlyGovernance {
        guardian[who] = allowed;
        emit GuardianSet(who, allowed);
    }

    function setGovernance(address next) external onlyGovernance {
        if (next == address(0)) revert BadValue();
        governance = next;
        emit GovernanceChanged(next);
    }

    // ---- skills ----

    function approveSkill(bytes32 id) external onlyGovernance {
        if (id == bytes32(0)) revert BadValue();
        skillApproved[id] = true;
        emit SkillApproved(id);
    }

    /// The active skill cannot be revoked: switch first (or pause).
    function revokeSkill(bytes32 id) external onlyGovernance {
        if (id == activeSkill) revert SkillInUse();
        skillApproved[id] = false;
        emit SkillRevoked(id);
    }

    function setActiveSkill(bytes32 id) external onlyGovernance {
        if (!skillApproved[id]) revert NotApproved();
        activeSkill = id;
        emit ActiveSkill(id);
    }

    // ---- defenders and quarantine ----

    function approveDefender(address runner) external onlyGovernance {
        if (runner == address(0) || defenderApproved[runner] || _roster.length == MAX_ROSTER) revert BadValue();
        defenderApproved[runner] = true;
        _roster.push(runner);
        emit DefenderApproved(runner);
    }

    /// Its seat (if any) is vacated by the next NeuroJobs.regrow().
    function removeDefender(address runner) external onlyGovernance {
        if (!defenderApproved[runner]) revert NotApproved();
        defenderApproved[runner] = false;
        for (uint256 i = 0; i < _roster.length; i++) {
            if (_roster[i] == runner) {
                _roster[i] = _roster[_roster.length - 1];
                _roster.pop();
                break;
            }
        }
        emit DefenderRemoved(runner);
    }

    function roster() external view returns (address[] memory) {
        return _roster;
    }

    function release(address runner) external onlyGovernance {
        releasedAt[runner] = uint64(block.timestamp);
        emit Released(runner);
    }

    // ---- sizes and money ----

    function setMaxBodies(uint256 n) external onlyGovernance {
        if (n < MIN_BODIES || n > MAX_BODIES) revert BadValue();
        maxBodies = n;
        emit MaxBodies(n);
    }

    function setMaxRegrowPerHour(uint256 n) external onlyGovernance {
        if (n == 0 || n > MAX_ROSTER) revert BadValue();
        maxRegrowPerHour = n;
        emit MaxRegrowPerHour(n);
    }

    function setCommunityFund(address fund) external onlyGovernance {
        if (fund == address(0)) revert BadValue();
        communityFund = fund;
        emit CommunityFund(fund);
    }

    // ---- challenges and defender liveness ----

    function setChallengeBond(uint256 amount) external onlyGovernance {
        if (amount == 0) revert BadValue();
        challengeBond = amount;
        emit ChallengeBond(amount);
    }

    /// 0 goes back to NeuroJobs' jobTimeout.
    function setChallengeWindow(uint256 secs) external onlyGovernance {
        if (secs != 0 && (secs < MIN_WINDOW || secs > MAX_WINDOW)) revert BadValue();
        challengeWindow = secs;
        emit ChallengeWindow(secs);
    }

    function setDefenderTimeout(uint256 secs) external onlyGovernance {
        if (secs < MIN_WINDOW || secs > MAX_WINDOW) revert BadValue();
        defenderTimeout = secs;
        emit DefenderTimeout(secs);
    }

    // ---- chains NeuroJobs takes requests for ----

    function approveChain(bytes32 chain) public onlyGovernance {
        if (chain == bytes32(0)) revert BadValue();
        chainAllowed[chain] = true;
        emit ChainApproved(chain);
    }

    /// Several at once (used at deploy to seed the runner's chain list).
    function approveChains(bytes32[] calldata chains) external onlyGovernance {
        if (chains.length == 0 || chains.length > MAX_CHAINS_PER_CALL) revert BadValue();
        for (uint256 i = 0; i < chains.length; i++) approveChain(chains[i]);
    }

    /// Jobs already requested for it keep running; new requests are refused.
    function removeChain(bytes32 chain) external onlyGovernance {
        if (!chainAllowed[chain]) revert NotApproved();
        chainAllowed[chain] = false;
        emit ChainRemoved(chain);
    }
}

contracts/NeuroIdentity.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IERC721Receiver {
    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data) external returns (bytes4);
}

/// NeuroJobs' runner record (the only part of NeuroJobs this registry reads).
interface IClaimRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

/// @title NeuroIdentity: one contract = one on-chain identity (ERC-8004 Identity Registry)
/// @notice An ERC-8004 ("Trustless Agents") Identity Registry: an ERC-721 whose
///         tokenId is the agentId and whose tokenURI (agentURI) resolves to the
///         agent registration file. On top of the plain ERC-8004 `register()`
///         calls, it gives every analysed contract, on any chain Neuro reads,
///         exactly one agent: "the Neuro of that contract".
///
///         Rules for a contract's identity (registerTarget / claim):
///         - Anyone may register a target. The identity is keyed by the target
///           (CAIP-10 style `namespace:reference:account`), so each target has
///           at most one, and the registry records who registered it.
///         - A new identity is held by this registry itself, so nobody (not the
///           registrant, not the admin) can edit, move or speak for it. Its
///           agentURI is built on-chain and points only at Neuro's report for
///           that target. A squatter therefore gains nothing: registering just
///           makes the Neuro report discoverable.
///         - The target's real owner can take control with proof. For a
///           contract on this chain: a call from the contract itself, or from
///           the address its `owner()` returns. Control follows the contract:
///           whoever can prove it now can claim again, even after a transfer.
///         - A target on another chain is claimed with `claimRemote`: its owner
///           (owner()/getOwner()/EIP-1967 admin on EVM, mint or upgrade
///           authority on Solana, ...) signs a consent off-chain, and at least
///           `claimQuorum` bonded Neuro runners (NeuroJobs: active,
///           agreed >= claimMinAgreed, rejected <= agreed, the bar ThreatRegistry
///           uses) attest with EIP-712 signatures that this key is the target's
///           owner on its chain right now. For an EVM owner the consent itself
///           is also checked here (ecrecover). Trust: the runners' quorum is
///           trusted to have read the owner correctly; for a non-EVM owner
///           (ed25519, ...) it is also trusted to have checked the consent
///           signature. Each claim uses the agent's `claimNonce`, so
///           attestations cannot be replayed.
///         - A remote claim only PROPOSES the takeover. It runs after
///           `claimDelay` (`finalizeClaim`, anyone may call it). Until then the
///           current holder (if the identity is claimed) or any ONE runner that
///           meets the bar can `contestClaim`, which cancels it; the claimant
///           must then gather fresh signatures. One honest runner (or the real
///           holder) is therefore enough to stop a colluding quorum. The price:
///           one rogue runner can also delay an honest claim, which fails safe
///           (the identity stays where it is).
///         - One spelling per target on chain: EVM/Move hex is lowercase, TON
///           friendly addresses (base64url, bounceable or not, testnet flag)
///           are converted to raw `0:hex` / `-1:hex` after their CRC16 check,
///           and a Bitcoin rune loses its spacers (• or .) and must be A-Z.
///         - A claimed identity behaves as a normal ERC-8004 agent (custom
///           agentURI, metadata, agentWallet, transfer). `neuroURI()` and
///           `getTarget()` still show what the identity is about, whatever its
///           owner writes in the agentURI.
///         - Nothing can be transferred to this registry. "Held by the
///           registry" therefore always means "never claimed, agentURI is
///           Neuro's own file": a claimed owner cannot set a custom URI and then
///           hand the token back to pass it off as an unclaimed identity.
contract NeuroIdentity {
    // ---------------------------------------------------------------- types

    struct MetadataEntry {
        string metadataKey;
        bytes metadataValue;
    }

    struct Target {
        string chain;        // Neuro chain key, e.g. "bsc"
        string account;      // canonical address / token id on that chain
        address registeredBy;
        uint64 registeredAt;
    }

    struct Chain {
        string caip2;        // e.g. "eip155:56"
        uint8 rule;          // RULE_*: how strictly the account is checked
        bool exists;
    }

    uint8 public constant RULE_TEXT = 0;      // [A-Za-z0-9._:-] and %XX (uppercase hex)
    uint8 public constant RULE_LOWER = 1;     // [a-z0-9._:-] only (bech32, NEAR, Starknet hex)
    uint8 public constant RULE_EVM = 2;       // 0x + 40 lowercase hex
    uint8 public constant RULE_MOVE = 3;      // 0x + 64 lowercase hex [::module::Name] (Sui, Aptos)
    uint8 public constant RULE_BASE58 = 4;    // 32-44 base58 characters (Solana)
    uint8 public constant RULE_TON = 5;       // stored raw: "0:" / "-1:" + 64 lowercase hex (friendly form converted)
    uint8 public constant RULE_RUNE = 6;      // stored A-Z only, 1-28 letters (spacers removed)

    string public constant name = "Neuro Agent Identity";
    string public constant symbol = "NEURO";
    string public constant REGISTRATION_TYPE = "https://eips.ethereum.org/EIPS/eip-8004#registration-v1";

    // ------------------------------------------------------------- storage

    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;
    mapping(uint256 => address) private _tokenApprovals;
    mapping(address => mapping(address => bool)) private _operatorApprovals;

    /// Last agentId handed out. Ids start at 1, so 0 means "none" (and "broadcast" in Neuro messages).
    uint256 public lastId;
    mapping(uint256 => string) private _uris;
    mapping(uint256 => mapping(string => bytes)) private _metadata;
    mapping(uint256 => Target) private _targets;
    /// keccak256(bytes(caip10)) => agentId
    mapping(bytes32 => uint256) public agentOfTarget;

    mapping(string => Chain) private _chains;
    string[] public chainKeys;
    bytes32 public immutable localCaip2Hash; // keccak256("eip155:<this chain id>")

    address public admin;
    string public webBase;   // Neuro web, e.g. "https://neuro.example/web/"
    string public imageURI;

    /// NeuroJobs (runner records) for claimRemote; zero = remote claims off. Fixed at deploy:
    /// whoever could change it could pick the runners and take any identity.
    IClaimRunners public immutable claimRunners;
    /// Runner attestations a remote claim needs.
    uint256 public immutable claimQuorum;
    /// Accepted verdicts (NeuroJobs `agreed`) a runner needs before it may attest or contest a remote claim.
    uint32 public immutable claimMinAgreed;
    /// Seconds a remote claim waits (contest window) before `finalizeClaim` can run it.
    uint64 public immutable claimDelay;
    struct PendingClaim { address newOwner; uint64 readyAt; }
    /// The remote claim waiting for its contest window to end (readyAt 0 = none).
    mapping(uint256 => PendingClaim) public pendingClaim;
    /// Bumped by every claim (local or remote): attestations and consents name it, so each is used once.
    mapping(uint256 => uint256) public claimNonce;
    /// Spelling rules (NeuroTargets), created by the constructor.
    NeuroTargets public immutable targetFormat;

    // -------------------------------------------------------------- events

    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);
    // ERC-4906
    event MetadataUpdate(uint256 _tokenId);
    event BatchMetadataUpdate(uint256 _fromTokenId, uint256 _toTokenId);
    // ERC-8004
    event Registered(uint256 indexed agentId, string agentURI, address indexed owner);
    event MetadataSet(uint256 indexed agentId, string indexed indexedMetadataKey, string metadataKey, bytes metadataValue);
    event URIUpdated(uint256 indexed agentId, string newURI, address indexed updatedBy);
    // Neuro
    event TargetRegistered(uint256 indexed agentId, bytes32 indexed targetHash, string target, address indexed registeredBy);
    event Claimed(uint256 indexed agentId, address indexed by, address indexed previousOwner);
    event RemoteClaimProposed(uint256 indexed agentId, address indexed newOwner, bytes ownerKey, address[] runners, uint64 readyAt);
    event RemoteClaimContested(uint256 indexed agentId, address indexed by, address indexed newOwner);
    event RemoteClaimFinalized(uint256 indexed agentId, address indexed newOwner);
    event ChainAdded(string key, string caip2, uint8 rule);
    event WebBaseSet(string webBase, string imageURI);
    event AdminSet(address admin);

    error NotAuthorized();
    error Nonexistent();
    error ReservedKey();
    error BadWallet();
    error Expired();
    error DeadlineTooFar();
    error InvalidSignature();
    error UnknownChain();
    error BadAccount();
    error BadValue();
    error ChainExists();
    error AlreadyRegistered(uint256 agentId);
    error NotTarget();
    error NotLocal();
    error NotTargetOwner();
    error AlreadyHolder();
    error UnsafeRecipient();
    error RegistryCustody();
    error RemoteClaimsOff();
    error NotRemote();
    error BadNonce();
    error NotRunner(address signer);
    error Quorum(uint256 have, uint256 need);
    error ClaimPending();
    error NoPendingClaim();
    error ClaimNotReady(uint64 readyAt);
    error ContestClosed();

    bytes32 private constant AGENT_WALLET_SET_TYPEHASH =
        keccak256("AgentWalletSet(uint256 agentId,address newWallet,address owner,uint256 deadline)");
    bytes32 private constant DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
    bytes32 private constant NAME_HASH = keccak256("ERC8004IdentityRegistry");
    bytes32 private constant VERSION_HASH = keccak256("1");
    uint256 private constant MAX_DEADLINE_DELAY = 5 minutes;
    /// A remote claim gathers several runners' signatures: allow up to a day.
    uint256 private constant MAX_CLAIM_DELAY = 1 days;
    bytes32 private constant CONSENT_TYPEHASH = keccak256(
        "RemoteClaimConsent(uint256 agentId,address newOwner,string target,bytes ownerKey,uint256 nonce,uint256 deadline)");
    bytes32 private constant ATTEST_TYPEHASH = keccak256(
        "RemoteClaimAttestation(uint256 agentId,address newOwner,string target,bytes ownerKey,uint256 nonce,uint256 deadline)");
    bytes32 private constant KEY_WALLET = keccak256("agentWallet");
    bytes32 private constant KEY_TARGET = keccak256("neuro.target");
    bytes32 private constant KEY_REGISTERED_BY = keccak256("neuro.registeredBy");

    constructor(string memory webBase_, string memory image_, string[] memory keys, string[] memory caip2s, uint8[] memory rules,
        address runners_, uint256 quorum_, uint32 minAgreed_, uint64 claimDelay_) {
        if (keys.length != caip2s.length || keys.length != rules.length) revert BadValue();
        // remote claims on: a quorum, a runner bar and a contest window of 1 hour to 30 days
        if (runners_ != address(0) && (quorum_ == 0 || minAgreed_ == 0 || claimDelay_ < 1 hours || claimDelay_ > 30 days)) revert BadValue();
        claimRunners = IClaimRunners(runners_);
        targetFormat = new NeuroTargets();
        claimQuorum = quorum_;
        claimMinAgreed = minAgreed_;
        claimDelay = claimDelay_;
        admin = msg.sender;
        localCaip2Hash = keccak256(bytes(string.concat("eip155:", _toString(block.chainid))));
        _setWeb(webBase_, image_);
        for (uint256 i; i < keys.length; i++) _addChain(keys[i], caip2s[i], rules[i]);
    }

    // ============================================================ ERC-165

    function supportsInterface(bytes4 id) external pure returns (bool) {
        return id == 0x01ffc9a7    // ERC-165
            || id == 0x80ac58cd    // ERC-721
            || id == 0x5b5e139f    // ERC-721 Metadata
            || id == 0x49064906;   // ERC-4906 (metadata update events)
    }

    // ============================================================ ERC-721

    function balanceOf(address owner) external view returns (uint256) {
        if (owner == address(0)) revert BadValue();
        return _balances[owner];
    }

    function ownerOf(uint256 tokenId) public view returns (address o) {
        o = _owners[tokenId];
        if (o == address(0)) revert Nonexistent();
    }

    function approve(address to, uint256 tokenId) external {
        address o = ownerOf(tokenId);
        if (msg.sender != o && !_operatorApprovals[o][msg.sender]) revert NotAuthorized();
        _tokenApprovals[tokenId] = to;
        emit Approval(o, to, tokenId);
    }

    function getApproved(uint256 tokenId) public view returns (address) {
        ownerOf(tokenId);
        return _tokenApprovals[tokenId];
    }

    function setApprovalForAll(address operator, bool approved) external {
        if (operator == address(0)) revert BadValue();
        _operatorApprovals[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function isApprovedForAll(address owner, address operator) public view returns (bool) {
        return _operatorApprovals[owner][operator];
    }

    function transferFrom(address from, address to, uint256 tokenId) public {
        address o = ownerOf(tokenId);
        if (o != from) revert NotAuthorized();
        if (!_isAuthorized(o, msg.sender, tokenId)) revert NotAuthorized();
        if (to == address(0)) revert BadValue();
        // Custody is only for never-claimed identities (see the contract notes).
        if (to == address(this)) revert RegistryCustody();
        _transfer(from, to, tokenId);
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) external {
        safeTransferFrom(from, to, tokenId, "");
    }

    function safeTransferFrom(address from, address to, uint256 tokenId, bytes memory data) public {
        transferFrom(from, to, tokenId);
        if (to.code.length > 0) {
            try IERC721Receiver(to).onERC721Received(msg.sender, from, tokenId, data) returns (bytes4 r) {
                if (r != IERC721Receiver.onERC721Received.selector) revert UnsafeRecipient();
            } catch {
                revert UnsafeRecipient();
            }
        }
    }

    /// agentURI. A custom URI set by a claimed owner wins; otherwise a Neuro
    /// identity resolves to its on-chain registration file (`neuroURI`).
    function tokenURI(uint256 agentId) external view returns (string memory) {
        ownerOf(agentId);
        if (bytes(_uris[agentId]).length > 0) return _uris[agentId];
        if (bytes(_targets[agentId].chain).length > 0) return neuroURI(agentId);
        return "";
    }

    function _isAuthorized(address owner, address spender, uint256 tokenId) internal view returns (bool) {
        return spender != address(0)
            && (spender == owner || _operatorApprovals[owner][spender] || _tokenApprovals[tokenId] == spender);
    }

    function _transfer(address from, address to, uint256 tokenId) internal {
        delete _tokenApprovals[tokenId];
        // ERC-8004: the verified agentWallet does not follow the token to a new owner.
        if (_metadata[tokenId]["agentWallet"].length > 0) {
            delete _metadata[tokenId]["agentWallet"];
            emit MetadataSet(tokenId, "agentWallet", "agentWallet", "");
        }
        unchecked {
            _balances[from] -= 1;
            _balances[to] += 1;
        }
        _owners[tokenId] = to;
        emit Transfer(from, to, tokenId);
    }

    function _mint(address to, uint256 tokenId) internal {
        unchecked { _balances[to] += 1; }
        _owners[tokenId] = to;
        emit Transfer(address(0), to, tokenId);
    }

    // ===================================================== ERC-8004 identity

    function register() external returns (uint256 agentId) {
        agentId = _registerPlain("");
    }

    function register(string calldata agentURI) external returns (uint256 agentId) {
        agentId = _registerPlain(agentURI);
    }

    function register(string calldata agentURI, MetadataEntry[] calldata metadata) external returns (uint256 agentId) {
        agentId = _registerPlain(agentURI);
        for (uint256 i; i < metadata.length; i++) {
            _requireFreeKey(metadata[i].metadataKey);
            _metadata[agentId][metadata[i].metadataKey] = metadata[i].metadataValue;
            emit MetadataSet(agentId, metadata[i].metadataKey, metadata[i].metadataKey, metadata[i].metadataValue);
        }
    }

    function _registerPlain(string memory agentURI) internal returns (uint256 agentId) {
        agentId = ++lastId;
        _metadata[agentId]["agentWallet"] = abi.encodePacked(msg.sender);
        _mint(msg.sender, agentId);
        if (bytes(agentURI).length > 0) _uris[agentId] = agentURI;
        emit Registered(agentId, agentURI, msg.sender);
        emit MetadataSet(agentId, "agentWallet", "agentWallet", abi.encodePacked(msg.sender));
        if (msg.sender.code.length > 0) {
            // _safeMint semantics: a contract registrant must accept ERC-721 tokens.
            try IERC721Receiver(msg.sender).onERC721Received(msg.sender, address(0), agentId, "") returns (bytes4 r) {
                if (r != IERC721Receiver.onERC721Received.selector) revert UnsafeRecipient();
            } catch {
                revert UnsafeRecipient();
            }
        }
    }

    function setAgentURI(uint256 agentId, string calldata newURI) external {
        _onlyAuthorized(agentId);
        _uris[agentId] = newURI;
        emit URIUpdated(agentId, newURI, msg.sender);
        emit MetadataUpdate(agentId);
    }

    function getMetadata(uint256 agentId, string memory metadataKey) external view returns (bytes memory) {
        bytes32 k = keccak256(bytes(metadataKey));
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length > 0) {
            if (k == KEY_TARGET) return bytes(_caip10(t));
            if (k == KEY_REGISTERED_BY) return abi.encodePacked(t.registeredBy);
        }
        return _metadata[agentId][metadataKey];
    }

    function setMetadata(uint256 agentId, string memory metadataKey, bytes memory metadataValue) external {
        _onlyAuthorized(agentId);
        _requireFreeKey(metadataKey);
        _metadata[agentId][metadataKey] = metadataValue;
        emit MetadataSet(agentId, metadataKey, metadataKey, metadataValue);
    }

    function getAgentWallet(uint256 agentId) external view returns (address) {
        bytes memory w = _metadata[agentId]["agentWallet"];
        if (w.length < 20) return address(0);
        return address(bytes20(w));
    }

    function setAgentWallet(uint256 agentId, address newWallet, uint256 deadline, bytes calldata signature) external {
        address owner = _onlyAuthorized(agentId);
        if (newWallet == address(0)) revert BadWallet();
        if (block.timestamp > deadline) revert Expired();
        if (deadline > block.timestamp + MAX_DEADLINE_DELAY) revert DeadlineTooFar();
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", domainSeparator(),
            keccak256(abi.encode(AGENT_WALLET_SET_TYPEHASH, agentId, newWallet, owner, deadline))));
        if (_recover(digest, signature) != newWallet) {
            (bool ok, bytes memory res) = newWallet.staticcall(abi.encodeWithSelector(0x1626ba7e, digest, signature));
            if (!(ok && res.length >= 32 && bytes4(abi.decode(res, (bytes32))) == 0x1626ba7e)) revert InvalidSignature();
        }
        _metadata[agentId]["agentWallet"] = abi.encodePacked(newWallet);
        emit MetadataSet(agentId, "agentWallet", "agentWallet", abi.encodePacked(newWallet));
    }

    function unsetAgentWallet(uint256 agentId) external {
        _onlyAuthorized(agentId);
        delete _metadata[agentId]["agentWallet"];
        emit MetadataSet(agentId, "agentWallet", "agentWallet", "");
    }

    /// As in the ERC-8004 reference implementation.
    function isAuthorizedOrOwner(address spender, uint256 agentId) external view returns (bool) {
        return _isAuthorized(ownerOf(agentId), spender, agentId);
    }

    function domainSeparator() public view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN_TYPEHASH, NAME_HASH, VERSION_HASH, block.chainid, address(this)));
    }

    function getVersion() external pure returns (string memory) {
        return "neuro-1 (ERC-8004 identity v2.0.0 interface)";
    }

    function _onlyAuthorized(uint256 agentId) internal view returns (address owner) {
        owner = ownerOf(agentId);
        if (!_isAuthorized(owner, msg.sender, agentId)) revert NotAuthorized();
    }

    function _requireFreeKey(string memory key) internal pure {
        bytes32 k = keccak256(bytes(key));
        if (k == KEY_WALLET || k == KEY_TARGET || k == KEY_REGISTERED_BY) revert ReservedKey();
    }

    function _recover(bytes32 digest, bytes calldata sig) internal pure returns (address) {
        if (sig.length != 65) return address(0);
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) return address(0);
        if (v != 27 && v != 28) return address(0);
        return ecrecover(digest, v, r, s);
    }

    // ===================================================== Neuro: 1 contract = 1 identity

    /// Registers the Neuro of `account` on Neuro chain `chain` (e.g. "bsc").
    /// Anyone may call it; the identity stays held by this registry until the
    /// target's owner claims it. Reverts AlreadyRegistered(id) if it exists.
    function registerTarget(string calldata chain, string calldata typed) external returns (uint256 agentId) {
        Chain storage c = _chains[chain];
        if (!c.exists) revert UnknownChain();
        string memory account = _canonical(bytes(typed), c.rule);
        string memory caip10 = string.concat(c.caip2, ":", account);
        bytes32 h = keccak256(bytes(caip10));
        if (agentOfTarget[h] != 0) revert AlreadyRegistered(agentOfTarget[h]);
        agentId = ++lastId;
        agentOfTarget[h] = agentId;
        _targets[agentId] = Target(chain, account, msg.sender, uint64(block.timestamp));
        _mint(address(this), agentId);
        emit Registered(agentId, neuroURI(agentId), address(this));
        emit MetadataSet(agentId, "agentWallet", "agentWallet", "");
        emit TargetRegistered(agentId, h, caip10, msg.sender);
    }

    /// Takes control of a ZETAPHY contract's identity: callable by the target
    /// contract itself or by the address its `owner()` returns right now.
    function claim(uint256 agentId) external {
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length == 0) revert NotTarget();
        if (keccak256(bytes(_chains[t.chain].caip2)) != localCaip2Hash) revert NotLocal();
        address target = _parseAddress(bytes(t.account));
        bool ok = msg.sender == target;
        if (!ok && target.code.length > 0) {
            (bool s, bytes memory r) = target.staticcall(abi.encodeWithSignature("owner()"));
            ok = s && r.length >= 32 && abi.decode(r, (uint256)) == uint256(uint160(msg.sender));
        }
        if (!ok) revert NotTargetOwner();
        _takeOver(agentId, msg.sender);
    }

    /// PROPOSES that `newOwner` takes control of the identity of a target on
    /// ANOTHER chain. Anyone may submit it; the signatures decide. The takeover
    /// runs with `finalizeClaim` after `claimDelay`, unless contested first.
    /// @param ownerKey   the target's owner/authority on its chain, as bytes
    ///                   (20-byte address on EVM, 32-byte ed25519 key on Solana, ...)
    /// @param ownerSig   for an EVM target: the owner's EIP-712 RemoteClaimConsent
    ///                   signature, checked here. Otherwise ignored (the runners checked it).
    /// @param attestations 65-byte EIP-712 RemoteClaimAttestation signatures by
    ///                   distinct runners, sorted by signer address (ascending).
    function claimRemote(uint256 agentId, address newOwner, bytes calldata ownerKey, uint256 deadline,
        bytes calldata ownerSig, bytes[] calldata attestations) external {
        if (address(claimRunners) == address(0)) revert RemoteClaimsOff();
        if (pendingClaim[agentId].readyAt != 0) revert ClaimPending();
        (bytes memory fields, bool evmOwner) = _claimFields(agentId, newOwner, ownerKey, deadline);
        // An EVM owner proves its consent here, so the runners cannot move the
        // identity for a real owner who never asked.
        if (evmOwner && (ownerKey.length != 20 || _recover(_typed(CONSENT_TYPEHASH, fields), ownerSig) != address(bytes20(ownerKey)))) {
            revert InvalidSignature();
        }
        address[] memory runners = _runnerQuorum(_typed(ATTEST_TYPEHASH, fields), attestations);
        if (_owners[agentId] == newOwner) revert AlreadyHolder();
        claimNonce[agentId]++; // these signatures are spent, whether the claim runs or is contested
        uint64 readyAt = uint64(block.timestamp) + claimDelay;
        pendingClaim[agentId] = PendingClaim(newOwner, readyAt);
        emit RemoteClaimProposed(agentId, newOwner, ownerKey, runners, readyAt);
    }

    /// Runs a remote claim whose contest window has passed. Anyone may call it.
    function finalizeClaim(uint256 agentId) external {
        PendingClaim memory p = pendingClaim[agentId];
        if (p.readyAt == 0) revert NoPendingClaim();
        if (block.timestamp < p.readyAt) revert ClaimNotReady(p.readyAt);
        delete pendingClaim[agentId];
        emit RemoteClaimFinalized(agentId, p.newOwner);
        if (_owners[agentId] != p.newOwner) _takeOver(agentId, p.newOwner);
    }

    /// Cancels a pending remote claim during its window. Callable by the
    /// current holder (owner/operator of a claimed identity) or by any one
    /// runner that meets the attestation bar.
    function contestClaim(uint256 agentId) external {
        PendingClaim memory p = pendingClaim[agentId];
        if (p.readyAt == 0) revert NoPendingClaim();
        if (block.timestamp >= p.readyAt) revert ContestClosed();
        address holder = _owners[agentId];
        if (!(holder != address(this) && _isAuthorized(holder, msg.sender, agentId)) && !_goodRunner(msg.sender)) revert NotAuthorized();
        delete pendingClaim[agentId];
        emit RemoteClaimContested(agentId, msg.sender, p.newOwner);
    }

    /// A runner in good standing: active, agreed >= claimMinAgreed, rejected <= agreed.
    function _goodRunner(address r) internal view returns (bool) {
        if (address(claimRunners) == address(0)) return false;
        (, , bool active, uint32 agreed, uint32 rejected) = claimRunners.workers(r);
        return active && agreed >= claimMinAgreed && rejected <= agreed;
    }

    /// The signed fields of a remote claim (EIP-712: string and bytes members
    /// hashed, static words after the typehash), and whether the target is EVM.
    function _claimFields(uint256 agentId, address newOwner, bytes calldata ownerKey, uint256 deadline)
        internal view returns (bytes memory, bool)
    {
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length == 0) revert NotTarget();
        Chain storage c = _chains[t.chain];
        if (keccak256(bytes(c.caip2)) == localCaip2Hash) revert NotRemote();
        if (newOwner == address(0) || newOwner == address(this) || ownerKey.length == 0 || ownerKey.length > 64) revert BadValue();
        if (block.timestamp > deadline) revert Expired();
        if (deadline > block.timestamp + MAX_CLAIM_DELAY) revert DeadlineTooFar();
        return (abi.encode(agentId, newOwner, keccak256(bytes(_caip10(t))), keccak256(ownerKey), claimNonce[agentId], deadline), c.rule == RULE_EVM);
    }

    /// Signers of `digest`: distinct, ascending, each a runner in good standing, at least claimQuorum of them.
    function _runnerQuorum(bytes32 digest, bytes[] calldata sigs) internal view returns (address[] memory signers) {
        if (sigs.length < claimQuorum) revert Quorum(sigs.length, claimQuorum);
        signers = new address[](sigs.length);
        address last;
        for (uint256 i; i < sigs.length; i++) {
            address r = _recover(digest, sigs[i]);
            if (r <= last) revert InvalidSignature(); // zero, unsorted or repeated
            if (!_goodRunner(r)) revert NotRunner(r);
            signers[i] = last = r;
        }
    }

    function _typed(bytes32 typehash, bytes memory fields) internal view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", domainSeparator(), keccak256(abi.encodePacked(typehash, fields))));
    }

    function _takeOver(uint256 agentId, address to) internal {
        address prev = _owners[agentId];
        if (prev == to) revert AlreadyHolder();
        claimNonce[agentId]++;
        _transfer(prev, to, agentId);
        _metadata[agentId]["agentWallet"] = abi.encodePacked(to);
        emit MetadataSet(agentId, "agentWallet", "agentWallet", abi.encodePacked(to));
        emit Claimed(agentId, to, prev);
        emit MetadataUpdate(agentId);
    }

    /// agentId of a target, 0 if none (or if the chain is unknown). Any accepted
    /// spelling works (e.g. a TON friendly address, a rune with spacers).
    function agentIdOf(string calldata chain, string calldata account) external view returns (uint256) {
        Chain storage c = _chains[chain];
        if (!c.exists) return 0;
        (bool ok, string memory a) = targetFormat.canonical(bytes(account), c.rule);
        if (!ok) return 0;
        return agentOfTarget[keccak256(bytes(string.concat(c.caip2, ":", a)))];
    }

    /// The one spelling the registry stores for `account` on `chain`; reverts BadAccount.
    function canonicalAccount(string calldata chain, string calldata account) external view returns (string memory) {
        Chain storage c = _chains[chain];
        if (!c.exists) revert UnknownChain();
        return _canonical(bytes(account), c.rule);
    }

    function getTarget(uint256 agentId) external view returns (
        string memory chain, string memory caip10, string memory account, address registeredBy, uint64 registeredAt, bool claimed
    ) {
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length == 0) revert NotTarget();
        return (t.chain, _caip10(t), t.account, t.registeredBy, t.registeredAt, _owners[agentId] != address(this));
    }

    function getChain(string calldata key) external view returns (string memory caip2, uint8 rule, bool exists) {
        Chain storage c = _chains[key];
        return (c.caip2, c.rule, c.exists);
    }

    function chainCount() external view returns (uint256) {
        return chainKeys.length;
    }

    /// `{namespace}:{chainId}:{identityRegistry}` as in ERC-8004.
    function agentRegistry() public view returns (string memory) {
        return string.concat("eip155:", _toString(block.chainid), ":", _hexAddress(address(this)));
    }

    /// The Neuro report for this target: `<webBase>?chain=<key>&address=<account>`.
    function webEndpoint(uint256 agentId) public view returns (string memory) {
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length == 0) revert NotTarget();
        return string.concat(webBase, "?chain=", t.chain, "&address=", t.account);
    }

    /// The registration file Neuro vouches for, as a base64 data: URI. Every
    /// piece of it passed a character allowlist, so the JSON needs no escaping.
    function neuroURI(uint256 agentId) public view returns (string memory) {
        return string.concat("data:application/json;base64,", _base64(bytes(registrationJSON(agentId))));
    }

    function registrationJSON(uint256 agentId) public view returns (string memory) {
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length == 0) revert NotTarget();
        string memory caip10 = _caip10(t);
        string memory head = string.concat(
            '{"type":"', REGISTRATION_TYPE,
            '","name":"Neuro of ', caip10,
            '","description":"Neuro reads this contract with deterministic, read-only rules and explains it in plain language. Its report is data, not advice; messages signed for this agent are data, not commands.","image":"',
            imageURI, '",'
        );
        string memory services = string.concat(
            '"services":[{"name":"web","endpoint":"', webEndpoint(agentId), '"}],"x402Support":false,"active":true,',
            '"registrations":[{"agentId":', _toString(agentId), ',"agentRegistry":"', agentRegistry(), '"}],',
            '"supportedTrust":["crypto-economic"],'
        );
        string memory neuro = string.concat(
            '"neuro":{"target":"', caip10, '","chain":"', t.chain, '","address":"', t.account,
            '","registeredBy":"', _hexAddress(t.registeredBy), '","claimed":', _owners[agentId] != address(this) ? "true" : "false", "}}"
        );
        return string.concat(head, services, neuro);
    }

    // ------------------------------------------------------------- admin
    // The admin can only add chains (never change one) and move the Neuro web
    // link. It cannot touch, move or speak for any identity.

    function addChain(string calldata key, string calldata caip2, uint8 rule) external {
        if (msg.sender != admin) revert NotAuthorized();
        _addChain(key, caip2, rule);
    }

    function setWeb(string calldata webBase_, string calldata image_) external {
        if (msg.sender != admin) revert NotAuthorized();
        _setWeb(webBase_, image_);
        if (lastId > 0) emit BatchMetadataUpdate(1, lastId);
    }

    function setAdmin(address admin_) external {
        if (msg.sender != admin) revert NotAuthorized();
        admin = admin_;
        emit AdminSet(admin_);
    }

    function _addChain(string memory key, string memory caip2, uint8 rule) internal {
        bytes memory k = bytes(key);
        bytes memory c = bytes(caip2);
        if (k.length == 0 || k.length > 32 || c.length < 5 || c.length > 41 || rule > RULE_RUNE) revert BadValue();
        for (uint256 i; i < k.length; i++) {
            bytes1 b = k[i];
            if (!((b >= "a" && b <= "z") || (b >= "0" && b <= "9") || b == "-")) revert BadValue();
        }
        uint256 colons;
        for (uint256 i; i < c.length; i++) {
            bytes1 b = c[i];
            if (b == ":") { colons++; continue; }
            if (!_alnum(b) && b != "-" && b != "_") revert BadValue();
        }
        if (colons != 1) revert BadValue();
        if (_chains[key].exists) revert ChainExists();
        _chains[key] = Chain(caip2, rule, true);
        chainKeys.push(key);
        emit ChainAdded(key, caip2, rule);
    }

    function _setWeb(string memory webBase_, string memory image_) internal {
        if (bytes(webBase_).length == 0) revert BadValue();
        _checkUrl(bytes(webBase_));
        _checkUrl(bytes(image_));
        webBase = webBase_;
        imageURI = image_;
        emit WebBaseSet(webBase_, image_);
    }

    // ------------------------------------------------------------- helpers

    /// Printable ASCII without quotes, backslash, angle brackets or spaces, at most 200 bytes.
    function _checkUrl(bytes memory u) internal pure {
        if (u.length > 200) revert BadValue();
        for (uint256 i; i < u.length; i++) {
            bytes1 b = u[i];
            if (b <= 0x20 || b >= 0x7f || b == '"' || b == "\\" || b == "<" || b == ">" || b == "`") revert BadValue();
        }
    }

    function _canonical(bytes memory a, uint8 rule) internal view returns (string memory) {
        (bool ok, string memory out) = targetFormat.canonical(a, rule);
        if (!ok) revert BadAccount();
        return out;
    }

    function _safeLower(bytes1 b) internal pure returns (bool) {
        return (b >= "a" && b <= "z") || (b >= "0" && b <= "9") || b == "." || b == "_" || b == ":" || b == "-";
    }

    /// Hex digit value, or 255. `upper` picks which letter case is accepted.
    function _hexVal(bytes1 b, bool upper) internal pure returns (uint8) {
        if (b >= "0" && b <= "9") return uint8(b) - 48;
        if (!upper && b >= "a" && b <= "f") return uint8(b) - 87;
        if (upper && b >= "A" && b <= "F") return uint8(b) - 55;
        return 255;
    }

    function _alnum(bytes1 b) internal pure returns (bool) {
        return (b >= "a" && b <= "z") || (b >= "A" && b <= "Z") || (b >= "0" && b <= "9");
    }

    function _parseAddress(bytes memory a) internal pure returns (address) {
        uint160 v;
        for (uint256 i = 2; i < 42; i++) v = v * 16 + _hexVal(a[i], false);
        return address(v);
    }

    function _caip10(Target storage t) internal view returns (string memory) {
        return string.concat(_chains[t.chain].caip2, ":", t.account);
    }

    function _toString(uint256 v) internal pure returns (string memory) {
        if (v == 0) return "0";
        uint256 len;
        for (uint256 x = v; x != 0; x /= 10) len++;
        bytes memory out = new bytes(len);
        while (v != 0) { out[--len] = bytes1(uint8(48 + v % 10)); v /= 10; }
        return string(out);
    }

    function _hexAddress(address a) internal pure returns (string memory) {
        bytes memory out = new bytes(42);
        out[0] = "0";
        out[1] = "x";
        bytes16 digits = "0123456789abcdef";
        uint160 v = uint160(a);
        for (uint256 i = 41; i > 1; i--) { out[i] = digits[v & 15]; v >>= 4; }
        return string(out);
    }

    function _base64(bytes memory data) internal pure returns (string memory) {
        bytes memory table = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        uint256 n = data.length;
        if (n == 0) return "";
        bytes memory out = new bytes(4 * ((n + 2) / 3));
        uint256 j;
        for (uint256 i; i < n; i += 3) {
            uint256 a = uint8(data[i]);
            uint256 b = i + 1 < n ? uint8(data[i + 1]) : 0;
            uint256 c = i + 2 < n ? uint8(data[i + 2]) : 0;
            uint256 triple = (a << 16) | (b << 8) | c;
            out[j++] = table[(triple >> 18) & 63];
            out[j++] = table[(triple >> 12) & 63];
            out[j++] = i + 1 < n ? table[(triple >> 6) & 63] : bytes1("=");
            out[j++] = i + 2 < n ? table[triple & 63] : bytes1("=");
        }
        return string(out);
    }
}

/// @title NeuroTargets: the one spelling of a target account (NeuroIdentity's helper)
/// @notice Pure functions, split out so NeuroIdentity stays under the 24,576-byte
///         code limit. NeuroIdentity creates its own copy in its constructor.
contract NeuroTargets {
    uint8 internal constant RULE_TEXT = 0;
    uint8 internal constant RULE_LOWER = 1;
    uint8 internal constant RULE_EVM = 2;
    uint8 internal constant RULE_MOVE = 3;
    uint8 internal constant RULE_BASE58 = 4;
    uint8 internal constant RULE_TON = 5;
    uint8 internal constant RULE_RUNE = 6;

    /// (true, the one spelling) or (false, "") if `a` is not an account of that rule.
    function canonical(bytes memory a, uint8 rule) external pure returns (bool, string memory) {
        if (rule == RULE_TON) return _tonRaw(a);
        if (rule == RULE_RUNE) return _runeName(a);
        if (a.length > 128 || !_accountOk(a, rule)) return (false, "");
        return (true, string(a));
    }

    /// TON: raw `0:` / `-1:` + 64 hex (either case, stored lowercase), or the
    /// 48-character friendly form (base64 or base64url; bounceable 0x11 or
    /// non-bounceable 0x51, optionally | 0x80 testnet) with a valid CRC16.
    function _tonRaw(bytes memory a) internal pure returns (bool, string memory) {
        bytes memory out = new bytes(67);
        uint256 n;
        bytes memory hash;
        if (a.length == 48) {
            bytes memory d = new bytes(36);
            for (uint256 i; i < 48; i += 4) {
                uint256 w;
                for (uint256 j; j < 4; j++) {
                    uint8 v = _b64(a[i + j]);
                    if (v > 63) return (false, "");
                    w = (w << 6) | v;
                }
                uint256 k = (i / 4) * 3;
                d[k] = bytes1(uint8(w >> 16));
                d[k + 1] = bytes1(uint8(w >> 8));
                d[k + 2] = bytes1(uint8(w));
            }
            uint8 tag = uint8(d[0]) & 0x7f; // 0x80 = testnet only
            if (tag != 0x11 && tag != 0x51) return (false, "");
            uint256 crc;
            for (uint256 i; i < 34; i++) {
                crc ^= uint256(uint8(d[i])) << 8;
                for (uint256 b; b < 8; b++) crc = crc & 0x8000 != 0 ? ((crc << 1) ^ 0x1021) & 0xffff : (crc << 1) & 0xffff;
            }
            if (crc != (uint256(uint8(d[34])) << 8 | uint8(d[35]))) return (false, "");
            if (d[1] == 0x00) { out[0] = "0"; n = 1; }
            else if (d[1] == 0xff) { out[0] = "-"; out[1] = "1"; n = 2; }
            else return (false, "");
            hash = new bytes(32);
            for (uint256 i; i < 32; i++) hash[i] = d[i + 2];
        } else {
            if (a.length == 66 && a[0] == "0" && a[1] == ":") { out[0] = "0"; n = 1; }
            else if (a.length == 67 && a[0] == "-" && a[1] == "1" && a[2] == ":") { out[0] = "-"; out[1] = "1"; n = 2; }
            else return (false, "");
            hash = new bytes(32);
            for (uint256 i; i < 32; i++) {
                uint8 hi = _hexAny(a[n + 1 + 2 * i]);
                uint8 lo = _hexAny(a[n + 2 + 2 * i]);
                if (hi > 15 || lo > 15) return (false, "");
                hash[i] = bytes1(hi * 16 + lo);
            }
        }
        out[n] = ":";
        bytes16 digits = "0123456789abcdef";
        for (uint256 i; i < 32; i++) {
            out[n + 1 + 2 * i] = digits[uint8(hash[i]) >> 4];
            out[n + 2 + 2 * i] = digits[uint8(hash[i]) & 15];
        }
        assembly { mstore(out, add(n, 65)) }
        return (true, string(out));
    }

    /// Rune name: spacers (U+2022 "•" as UTF-8 or %E2%80%A2, and ".") are
    /// dropped; what is left must be 1-28 letters A-Z.
    function _runeName(bytes memory a) internal pure returns (bool, string memory) {
        bytes memory out = new bytes(a.length);
        uint256 n;
        for (uint256 i; i < a.length; i++) {
            bytes1 b = a[i];
            if (b >= "A" && b <= "Z") { out[n++] = b; continue; }
            if (b == ".") continue;
            if (b == 0xe2 && i + 2 < a.length && a[i + 1] == 0x80 && a[i + 2] == 0xa2) { i += 2; continue; }
            if (b == "%" && i + 8 < a.length && keccak256(abi.encodePacked(a[i + 1], a[i + 2], a[i + 3], a[i + 4], a[i + 5], a[i + 6], a[i + 7], a[i + 8]))
                == keccak256("E2%80%A2")) { i += 8; continue; }
            return (false, "");
        }
        if (n == 0 || n > 28) return (false, "");
        assembly { mstore(out, n) }
        return (true, string(out));
    }

    function _b64(bytes1 c) internal pure returns (uint8) {
        if (c >= "A" && c <= "Z") return uint8(c) - 65;
        if (c >= "a" && c <= "z") return uint8(c) - 71;
        if (c >= "0" && c <= "9") return uint8(c) + 4;
        if (c == "-" || c == "+") return 62;
        if (c == "_" || c == "/") return 63;
        return 255;
    }

    function _hexAny(bytes1 b) internal pure returns (uint8) {
        uint8 v = _hexVal(b, false);
        return v < 16 ? v : _hexVal(b, true);
    }

    /// The account checks of the other rules: the input must already be the one spelling.
    function _accountOk(bytes memory a, uint8 rule) internal pure returns (bool) {
        if (a.length == 0 || a.length > 128) return false;
        if (rule == RULE_EVM) {
            if (a.length != 42 || a[0] != "0" || a[1] != "x") return false;
            for (uint256 i = 2; i < 42; i++) if (_hexVal(a[i], false) > 15) return false;
            return true;
        }
        if (rule == RULE_MOVE) return _moveOk(a);
        if (rule == RULE_BASE58) {
            if (a.length < 32 || a.length > 44) return false;
            for (uint256 i; i < a.length; i++) {
                bytes1 b = a[i];
                if (!_alnum(b) || b == "0" || b == "O" || b == "I" || b == "l") return false;
            }
            return true;
        }
        for (uint256 i; i < a.length; i++) {
            bytes1 b = a[i];
            if (_safeLower(b)) continue;
            if (rule == RULE_TEXT) {
                if (b >= "A" && b <= "Z") continue;
                // %XX with uppercase hex, the one canonical spelling of an escaped byte;
                // a byte that needs no escape (e.g. %41 for "A") is a second spelling, so refused
                if (b == "%" && i + 2 < a.length && _hexVal(a[i + 1], true) < 16 && _hexVal(a[i + 2], true) < 16) {
                    bytes1 d = bytes1(_hexVal(a[i + 1], true) * 16 + _hexVal(a[i + 2], true));
                    if (_safeLower(d) || (d >= "A" && d <= "Z")) return false;
                    i += 2;
                    continue;
                }
            }
            return false;
        }
        return true;
    }

    /// Move: "0x" + 64 lowercase hex (the padded address), optionally followed
    /// by "::module::Name" with identifiers [A-Za-z_][A-Za-z0-9_]*.
    function _moveOk(bytes memory a) internal pure returns (bool) {
        if (a.length < 66 || a[0] != "0" || a[1] != "x") return false;
        for (uint256 j = 2; j < 66; j++) if (_hexVal(a[j], false) > 15) return false;
        if (a.length == 66) return true;
        uint256 i = 66;
        for (uint256 part; part < 2; part++) {
            if (i + 2 >= a.length || a[i] != ":" || a[i + 1] != ":") return false;
            i += 2;
            bytes1 f = a[i];
            if (!((f >= "a" && f <= "z") || (f >= "A" && f <= "Z") || f == "_")) return false;
            while (i < a.length && a[i] != ":") {
                if (!_alnum(a[i]) && a[i] != "_") return false;
                i++;
            }
        }
        return i == a.length;
    }

    function _safeLower(bytes1 b) internal pure returns (bool) {
        return (b >= "a" && b <= "z") || (b >= "0" && b <= "9") || b == "." || b == "_" || b == ":" || b == "-";
    }

    function _hexVal(bytes1 b, bool upper) internal pure returns (uint8) {
        if (b >= "0" && b <= "9") return uint8(b) - 48;
        if (!upper && b >= "a" && b <= "f") return uint8(b) - 87;
        if (upper && b >= "A" && b <= "F") return uint8(b) - 55;
        return 255;
    }

    function _alnum(bytes1 b) internal pure returns (bool) {
        return (b >= "a" && b <= "z") || (b >= "A" && b <= "Z") || (b >= "0" && b <= "9");
    }
}

contracts/NeuroJobs.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// What NeuroJobs reads from NeuroControl (contracts/NeuroControl.sol).
interface INeuroKnobs {
    function paused() external view returns (bool);
    function activeSkill() external view returns (bytes32);
    function defenderApproved(address) external view returns (bool);
    function roster() external view returns (address[] memory);
    function releasedAt(address) external view returns (uint64);
    function maxBodies() external view returns (uint256);
    function maxRegrowPerHour() external view returns (uint256);
    function communityFund() external view returns (address);
    function chainAllowed(bytes32) external view returns (bool);
    function challengeBond() external view returns (uint256);
    function challengeWindow() external view returns (uint256);
    function defenderTimeout() external view returns (uint256);
}

/// @title NeuroJobsBase: storage, rules and helpers shared by NeuroJobs and
///        its challenge logic (NeuroJobsChallenges, reached by delegatecall,
///        so both see the same storage). See NeuroJobs for the rules.
abstract contract NeuroJobsBase {
    uint8 public constant SEATS = 3;
    uint8 public constant QUORUM = 2;
    /// Share of the bond a runner loses for a verdict the quorum rejected,
    /// or for committing and then never revealing (basis points).
    uint16 public constant PENALTY_BPS = 1000;
    /// Fee split (basis points of the fee); the runners get the rest (90%).
    uint16 public constant BURN_BPS = 500;
    uint16 public constant COMMUNITY_BPS = 500;
    address public constant BURN = 0x000000000000000000000000000000000000dEaD;
    /// Defender seats; also the fewest bodies there ever are.
    uint8 public constant DEFENDERS = 4;
    /// Requests per minute one body is expected to handle.
    uint256 public constant CAPACITY_PER_BODY = 6;
    /// Minutes for the extra bodies to fade out after the last busy minute.
    uint256 public constant DECAY_MINUTES = 30;
    /// Strikes within the last STRIKE_WINDOW judged seats that put a runner in quarantine (K).
    uint8 public constant QUARANTINE_AFTER = 2;
    uint8 public constant STRIKE_WINDOW = 5;
    /// Share of a failed or expired job's fee that is burned instead of refunded.
    uint16 public constant FAIL_BURN_BPS = 500;
    /// Longest target: a Move coin type (66-char address + two 128-char names + separators).
    uint256 public constant MAX_TARGET = 330;
    /// Share of its bond a round-1 runner loses when a challenge overturns its verdict.
    uint16 public constant CHALLENGE_SLASH_BPS = 5000;
    /// The challenge bond is at least this many times the job fee.
    uint256 public constant CHALLENGE_FEE_MULTIPLE = 2;
    /// Challenge rounds per job (after a Disputed one a new one may open): 3 rounds in all.
    uint8 public constant MAX_CHALLENGES = 2;
    /// Share of the challenger's bond kept when a challenge round finds no quorum.
    uint16 public constant DISPUTE_KEEP_BPS = 2000;

    uint256 public immutable workerBond;
    uint256 public immutable jobReward;
    uint256 public immutable minFee;
    uint64 public immutable commitWindow;
    uint64 public immutable jobTimeout;
    uint64 public immutable unbondDelay;
    uint256 public immutable dailyRewardCap;
    /// May call setControl() once.
    address public immutable deployer;

    enum Status { None, Open, Done, Failed }
    enum ChallengeState { None, Open, Confirmed, Overturned, Disputed }

    struct Worker {
        uint128 bond;
        uint64 unbondAt; // 0 while active
        bool active;
        uint32 agreed;
        uint32 rejected;
        uint64 since;    // when it last became active; only later jobs count
        uint8 recent;    // last STRIKE_WINDOW judged seats, newest in bit 0; 1 = strike
        uint64 quarantinedAt; // 0 = never; see quarantined()
        uint64 lastSeen;  // last register, heartbeat, commit or reveal
        uint64 heldUntil; // bond stays until nothing it sat on can still slash it
    }

    /// One round of 3 seats (round 1 = the job, rounds 2.. = challenges).
    struct Round {
        uint8 commits;
        uint8 reveals;
        uint8 defenders;   // seats taken as a defender
        uint64 start;      // the commit window starts here
        uint64 startBlock; // the lottery uses blockhash(startBlock + 1)
        bytes32 rand;      // the stored lottery; 0 until stored (see _rand)
        uint256 total;     // totalActiveBond when the round opened (the lottery's denominator)
        address[3] seat;
        bytes32[3] commitOf;
        bytes32[3] verdictOf;
        bool[3] revealed;
    }

    struct Job {
        address requester;
        Status status;
        uint8 agreedBy;  // distinct runners that revealed the final verdict
        uint8 chN;       // challenges opened on it (at most MAX_CHALLENGES)
        uint16 bodies;   // bodies when requested
        uint16 drawn;    // of which drawn by lottery (bodies minus seated defenders)
        uint64 settleAt; // quorum reached with seats unrevealed: grace ends here (0 = nothing pending)
        uint64 challengeUntil; // set when the quorum forms (moved after a Disputed challenge)
        bytes32 chain;
        uint256 fee;
        bytes32 result;
        bytes32 seed;
        bytes32 skill;   // NeuroControl.activeSkill() at request time
        string target;
        Round r;
    }

    struct Challenge {
        address challenger;
        ChallengeState state;
        uint64 settleAt;
        uint256 bond;
        bytes32 claim;   // the verdict the challenger says is right
        bytes32 result;
        Round r;
    }

    uint256 public rewardPool;
    uint256 public activeWorkers;
    uint256 public totalActiveBond;
    uint64 public rewardDay;
    uint256 public rewardedToday;
    mapping(address => uint256) public requestCount;
    mapping(address => Worker) public workers;
    mapping(address => uint256) public credit;
    Job[] internal jobs;
    /// challenges[id][k]: the k-th challenge (0-based) of job id.
    mapping(uint256 => mapping(uint256 => Challenge)) internal challenges;
    /// Ids of challenged jobs, once per challenge, in order (runners scan it for seats).
    uint256[] public challenged;

    INeuroKnobs public control;
    address[4] public defender;
    uint64 public regrowHour;
    uint256 public regrownThisHour;
    uint256 public totalBurned;
    // Load meter: requests in the latest minute that had any, and the
    // busiest earlier minute still fading (see bodies()).
    uint64 public loadMinute;
    uint64 public loadCount;
    uint64 public peakMinute;
    uint64 public peakCount;

    event Funded(address indexed from, uint256 amount);
    event Registered(address indexed worker, uint256 bond);
    event UnbondRequested(address indexed worker, uint64 at);
    event JobRequested(uint256 indexed id, bytes32 indexed chain, string target, uint256 fee);
    event Committed(uint256 indexed id, address indexed worker);
    event Revealed(uint256 indexed id, address indexed worker, bytes32 verdict);
    event Finalized(uint256 indexed id, bytes32 verdict);
    event JobFailed(uint256 indexed id);
    event Penalized(address indexed worker, uint256 amount);
    event ControlSet(address control);
    event JobSized(uint256 indexed id, bytes32 indexed skill, uint256 bodies, uint256 drawn);
    event FeeSplit(uint256 indexed id, uint256 runners, uint256 burned, uint256 community);
    event Quarantined(address indexed worker);
    event DefenderSeated(address indexed worker, uint256 seat);
    event DefenderVacated(address indexed worker, uint256 seat);
    event Missed(uint256 indexed id, address indexed worker);
    event Settled(uint256 indexed id);
    event Drawn(uint256 indexed id, uint8 round, bytes32 rand);
    /// The lottery block's hash fell out of the 256-block window before anyone used it: the round takes a new block.
    event Redrawn(uint256 indexed id, uint8 round, uint64 startBlock);
    event Challenged(uint256 indexed id, address indexed challenger, uint256 bond);
    event ChallengeClaim(uint256 indexed id, uint8 round, bytes32 claim);
    event ChallengeCommitted(uint256 indexed id, address indexed worker);
    event ChallengeRevealed(uint256 indexed id, address indexed worker, bytes32 verdict);
    event ChallengeResolved(uint256 indexed id, ChallengeState state, bytes32 verdict);

    error BadValue();
    error BadJob();
    error NotWorker();
    error Closed();
    error AlreadyIn();
    error NoSeat();
    error TooEarly();
    error BadReveal();
    error Nothing();
    error NotChosen();
    error Paused();
    error NoSkill();
    error NoControl();
    error NotDeployer();
    error UnknownChain();
    error InQuarantine();

    constructor(uint256 bond_, uint256 reward_, uint256 minFee_, uint64 commitWindow_, uint64 timeout_, uint64 unbondDelay_, uint256 dailyRewardCap_) {
        if (bond_ == 0 || commitWindow_ == 0 || timeout_ <= commitWindow_ || unbondDelay_ < timeout_) revert BadValue();
        workerBond = bond_;
        jobReward = reward_;
        minFee = minFee_;
        commitWindow = commitWindow_;
        jobTimeout = timeout_;
        unbondDelay = unbondDelay_;
        dailyRewardCap = dailyRewardCap_;
        deployer = msg.sender;
    }

    // ---- shared internals ----

    function _job(uint256 id) internal view returns (Job storage) {
        if (id >= jobs.length) revert BadJob();
        return jobs[id];
    }

    /// The latest challenge of job `id` and its round number (2, 3, ...);
    /// (an empty one, 1) when there is none.
    function _latest(uint256 id) internal view returns (Challenge storage ch, uint8 round) {
        uint8 n = jobs[id].chN;
        return (challenges[id][n == 0 ? 0 : n - 1], n + 1);
    }

    function _paused() internal view returns (bool) {
        return address(control) != address(0) && control.paused();
    }

    /// The lottery of a round: keccak256(seed, blockhash(startBlock + 1), round).
    /// Fixed by a block the caller cannot pick, so failing (a revert) and
    /// trying again in a later block, or calling only when it suits, changes
    /// nothing. 0 = not available: before block startBlock + 2, or (blockhash
    /// 0) more than 256 blocks later, when draw() moves the round to a new
    /// block. A chain whose BLOCKHASH gives 0 inside the window gets a fixed
    /// fallback, keccak256(seed, 1, round): as predictable as the request.
    function _rand(bytes32 seed, Round storage r, uint8 round) internal view returns (bytes32) {
        if (r.rand != 0) return r.rand;
        uint256 n = uint256(r.startBlock) + 1;
        if (block.number <= n) return 0;
        bytes32 h = blockhash(n);
        if (h == 0) {
            if (block.number - n > 256) return 0;
            h = bytes32(uint256(1));
        }
        return keccak256(abi.encode(seed, h, round));
    }

    function _open(Round storage r) internal {
        r.start = uint64(block.timestamp);
        r.startBlock = uint64(block.number);
        r.total = totalActiveBond;
    }

    /// Takes a seat in round `round` for msg.sender.
    function _take(uint256 id, Round storage r, uint8 round, bytes32 commitment) internal {
        Worker storage wk = workers[msg.sender];
        if (!wk.active) revert NotWorker();
        if (_paused()) revert Paused();
        if (block.timestamp >= r.start + commitWindow || r.commits == SEATS) revert NoSeat();
        if (r.rand == 0) {
            bytes32 x = _rand(jobs[id].seed, r, round);
            if (x == 0) revert TooEarly();
            r.rand = x;
            emit Drawn(id, round, x);
        }
        (bool ok, bool asDefender) = _eligible(id, r, msg.sender, round);
        if (!ok) revert NotChosen();
        for (uint8 i = 0; i < r.commits; i++) if (r.seat[i] == msg.sender) revert AlreadyIn();
        r.seat[r.commits] = msg.sender;
        r.commitOf[r.commits] = commitment;
        r.commits += 1;
        if (asDefender) r.defenders += 1;
        wk.lastSeen = uint64(block.timestamp);
        // Penalties of this seat come by start + jobTimeout (+ the grace): the bond stays.
        _hold(msg.sender, uint256(r.start) + 2 * uint256(jobTimeout));
    }

    /// Checks msg.sender's commitment; returns how many revealed seats now
    /// hold this verdict (itself included).
    function _reveal(Round storage r, bytes32 verdict, bytes32 salt) internal returns (uint8 same) {
        uint8 s = _seatOf(r, msg.sender);
        if (r.revealed[s]) revert AlreadyIn();
        if (keccak256(abi.encode(verdict, msg.sender, salt)) != r.commitOf[s]) revert BadReveal();
        r.revealed[s] = true;
        r.verdictOf[s] = verdict;
        r.reveals += 1;
        workers[msg.sender].lastSeen = uint64(block.timestamp);
        for (uint8 i = 0; i < r.commits; i++) if (r.revealed[i] && r.verdictOf[i] == verdict) same++;
    }

    /// May a round's reveal still come? Open rounds: once seats are full or
    /// the commit window is over, and never after start + jobTimeout (a hard
    /// deadline: expire()/challengeExpire() close the round).
    function _revealOpen(Round storage r) internal view {
        if (block.timestamp >= r.start + jobTimeout) revert Closed();
        if (r.commits < SEATS && block.timestamp < r.start + commitWindow) revert TooEarly();
    }

    /// (eligible, as a defender) for round `round` of job `id`. Rounds 2..
    /// exclude every challenger so far and every seat of the earlier rounds.
    function _eligible(uint256 id, Round storage r, address w, uint8 round) internal view returns (bool, bool) {
        Job storage j = jobs[id];
        Worker storage wk = workers[w];
        uint256 total = r.total;
        if (_rand(j.seed, r, round) == 0 || !wk.active || wk.since >= r.start || total == 0 || quarantined(w)) return (false, false);
        if (round >= 2) {
            for (uint8 i = 0; i < j.r.commits; i++) if (j.r.seat[i] == w) return (false, false);
            for (uint256 c = 0; c + 2 <= round; c++) {
                Challenge storage x = challenges[id][c];
                if (x.challenger == w) return (false, false);
                if (c + 2 < round) for (uint8 i = 0; i < x.r.commits; i++) if (x.r.seat[i] == w) return (false, false);
            }
        }
        // A defender never goes by the lottery, and at most one sits on a
        // round, in every phase, unless no runner but defenders is active.
        if (isDefender(w)) return (r.defenders == 0 || activeWorkers <= _seatedDefenders(), true);
        uint256 stage = ((block.timestamp - r.start) * 3) / commitWindow; // 0, 1, 2 inside the window
        // Last third: every active runner (a real random draw must not leave seats empty).
        if (stage >= 2) return (true, false);
        uint256 base = j.drawn;
        if (stage > 0 && base < SEATS) base = SEATS;
        uint256 k = base << stage;
        uint256 x2 = uint256(keccak256(abi.encode(_rand(j.seed, r, round), w))) % 1e18;
        return (x2 * total < k * uint256(wk.bond) * 1e18, false);
    }

    function _seatOf(Round storage r, address w) internal view returns (uint8) {
        for (uint8 i = 0; i < r.commits; i++) if (r.seat[i] == w) return i;
        revert NoSeat();
    }

    function _challengeWindow() internal view returns (uint256 w) {
        if (address(control) != address(0)) w = control.challengeWindow();
        if (w == 0) w = jobTimeout;
    }

    /// Bonds of round-1 seats stay until a challenge opened by challengeUntil
    /// is over (its reveals end jobTimeout after it opens, its grace and
    /// settle() inside another jobTimeout).
    function _holdRound1(Job storage j) internal {
        uint256 hold = uint256(j.challengeUntil) + 2 * uint256(jobTimeout);
        for (uint8 i = 0; i < j.r.commits; i++) _hold(j.r.seat[i], hold);
    }

    function _hold(address w, uint256 until) internal {
        if (workers[w].heldUntil < until) workers[w].heldUntil = uint64(until);
    }

    function _toCommunity(uint256 amount) internal {
        if (amount == 0) return;
        if (address(control) != address(0)) credit[control.communityFund()] += amount;
        else rewardPool += amount;
    }

    function _settleRound(uint256 id, Round storage r, uint64 at) internal returns (bool) {
        if (at == 0 || block.timestamp < at) return false;
        for (uint8 i = 0; i < r.commits; i++) if (!r.revealed[i]) _miss(id, r.seat[i]);
        return true;
    }

    /// A judged seat: `ok` = its verdict stood. A rejected verdict costs the
    /// penalty and a strike.
    function _judge(address w, bool ok) internal {
        Worker storage wk = workers[w];
        if (ok) {
            wk.agreed += 1;
            _record(w, false);
        } else {
            wk.rejected += 1;
            _penalize(w, PENALTY_BPS, true);
            _record(w, true);
        }
    }

    /// Committed, never revealed: penalty and a strike.
    function _miss(uint256 id, address w) internal {
        emit Missed(id, w);
        _penalize(w, PENALTY_BPS, true);
        _record(w, true);
    }

    function _record(address w, bool strike) internal {
        Worker storage wk = workers[w];
        wk.recent = uint8(((uint256(wk.recent) << 1) | (strike ? 1 : 0)) & ((1 << STRIKE_WINDOW) - 1));
        if (strike && strikes(w) >= QUARANTINE_AFTER && !quarantined(w)) _quarantine(w);
    }

    /// Out at once: not active, its bond leaves totalActiveBond and starts
    /// unbonding (withdrawable after unbondDelay, minus penalties).
    function _quarantine(address w) internal {
        Worker storage wk = workers[w];
        wk.recent = 0;
        wk.quarantinedAt = uint64(block.timestamp);
        _deactivate(w);
        emit Quarantined(w);
        for (uint256 i = 0; i < DEFENDERS; i++) {
            if (defender[i] == w) {
                defender[i] = address(0);
                emit DefenderVacated(w, i);
            }
        }
    }

    /// Not active any more, and the unbond timer runs (withdrawBond after
    /// unbondDelay and heldUntil), so the bond never gets stuck.
    function _deactivate(address w) internal {
        Worker storage wk = workers[w];
        if (wk.active) {
            wk.active = false;
            activeWorkers -= 1;
            totalActiveBond -= wk.bond;
        }
        if (wk.unbondAt == 0 && wk.bond > 0) {
            wk.unbondAt = uint64(block.timestamp) + unbondDelay;
            emit UnbondRequested(w, wk.unbondAt);
        }
    }

    /// Takes `bps` of the bond: into the reward pool (`toPool`), or returned
    /// for the caller to hand out (a challenge's slash).
    function _penalize(address w, uint16 bps, bool toPool) internal returns (uint256 cut) {
        Worker storage wk = workers[w];
        cut = (uint256(wk.bond) * bps) / 10_000;
        if (cut == 0) return 0;
        wk.bond -= uint128(cut);
        if (toPool) rewardPool += cut;
        if (wk.active) totalActiveBond -= cut;
        emit Penalized(w, cut);
        // Below the bond: out until topped up (register() again), unbonding meanwhile.
        if (wk.active && wk.bond < workerBond) _deactivate(w);
    }

    /// Strikes within the runner's last STRIKE_WINDOW judged seats.
    function strikes(address w) public view returns (uint256 n) {
        for (uint8 r = workers[w].recent; r != 0; r >>= 1) n += r & 1;
    }

    function quarantined(address w) public view returns (bool) {
        uint64 q = workers[w].quarantinedAt;
        if (q == 0) return false;
        return address(control) == address(0) || q >= control.releasedAt(w);
    }

    /// Seated in a defender seat and still fit for it (incl. a recent heartbeat).
    function isDefender(address w) public view returns (bool) {
        if (w == address(0)) return false;
        for (uint256 i = 0; i < DEFENDERS; i++) if (defender[i] == w) return _fit(w);
        return false;
    }

    function _fit(address w) internal view returns (bool) {
        if (address(control) == address(0) || !control.defenderApproved(w) || !workers[w].active || quarantined(w)) return false;
        return block.timestamp < uint256(workers[w].lastSeen) + control.defenderTimeout();
    }

    function _seatedDefenders() internal view returns (uint256 n) {
        for (uint256 i = 0; i < DEFENDERS; i++) if (defender[i] != address(0) && _fit(defender[i])) n++;
    }

    /// The least bond challenge(id) takes: max(2 x fee, NeuroControl.challengeBond()).
    function challengeBondOf(uint256 id) public view returns (uint256 b) {
        b = _job(id).fee * CHALLENGE_FEE_MULTIPLE;
        if (address(control) != address(0)) {
            uint256 floor_ = control.challengeBond();
            if (floor_ > b) b = floor_;
        }
    }
}

/// @title NeuroJobsChallenges: the challenge rounds of NeuroJobs
/// @notice Runs only through NeuroJobs' delegatecall (on NeuroJobs' storage
///         and balance); NeuroJobs deploys it in its constructor. Called
///         directly it refuses. The rules are documented on NeuroJobs.
contract NeuroJobsChallenges is NeuroJobsBase {
    address private immutable self_;

    constructor(uint256 bond_, uint256 reward_, uint256 minFee_, uint64 commitWindow_, uint64 timeout_, uint64 unbondDelay_, uint256 dailyRewardCap_)
        NeuroJobsBase(bond_, reward_, minFee_, commitWindow_, timeout_, unbondDelay_, dailyRewardCap_)
    {
        self_ = address(this);
    }

    modifier delegated() {
        if (address(this) == self_) revert NotDeployer();
        _;
    }

    function challenge(uint256 id, bytes32 claim) external payable delegated {
        Job storage j = _job(id);
        if (j.status != Status.Done || block.timestamp >= j.challengeUntil) revert Closed();
        (Challenge storage prev,) = _latest(id);
        if (prev.state != ChallengeState.None && prev.state != ChallengeState.Disputed) revert AlreadyIn();
        if (j.chN >= MAX_CHALLENGES) revert Closed();
        if (_paused()) revert Paused();
        if (claim == bytes32(0) || claim == j.result || msg.value < challengeBondOf(id)) revert BadValue();
        Challenge storage ch = challenges[id][j.chN];
        j.chN += 1;
        ch.challenger = msg.sender;
        ch.state = ChallengeState.Open;
        ch.bond = msg.value;
        ch.claim = claim;
        _open(ch.r);
        // Round-1 bonds stay until this round is over (whatever challengeUntil said).
        uint256 hold = uint256(block.timestamp) + 2 * uint256(jobTimeout);
        for (uint8 i = 0; i < j.r.commits; i++) _hold(j.r.seat[i], hold);
        challenged.push(id);
        emit Challenged(id, msg.sender, msg.value);
        emit ChallengeClaim(id, j.chN + 1, claim);
    }

    function challengeCommit(uint256 id, bytes32 commitment) external delegated {
        _job(id);
        (Challenge storage ch, uint8 round) = _latest(id);
        if (ch.state != ChallengeState.Open) revert Closed();
        _take(id, ch.r, round, commitment);
        emit ChallengeCommitted(id, msg.sender);
    }

    function challengeReveal(uint256 id, bytes32 verdict, bytes32 salt) external delegated {
        Job storage j = _job(id);
        (Challenge storage ch,) = _latest(id);
        Round storage r = ch.r;
        if (ch.state == ChallengeState.Open) _revealOpen(r);
        else if (ch.settleAt == 0 || block.timestamp >= ch.settleAt) revert Closed();
        uint8 same = _reveal(r, verdict, salt);
        emit ChallengeRevealed(id, msg.sender, verdict);

        if (ch.state != ChallengeState.Open) {
            bool ok = verdict == ch.result;
            if (ok) j.agreedBy += 1;
            _judge(msg.sender, ok);
            if (r.reveals == r.commits) { ch.settleAt = 0; emit Settled(id); }
            return;
        }
        if (same >= QUORUM) _resolve(id, j, ch, verdict);
        else if (r.reveals == r.commits && (r.commits == SEATS || block.timestamp >= r.start + commitWindow)) _dispute(id, j, ch, false);
    }

    function challengeExpire(uint256 id) external delegated {
        Job storage j = _job(id);
        (Challenge storage ch,) = _latest(id);
        if (ch.state != ChallengeState.Open) revert Closed();
        if (block.timestamp < ch.r.start + jobTimeout) revert TooEarly();
        _dispute(id, j, ch, true);
    }

    /// The round reached a quorum on `verdict`. Only credits move (no calls out).
    function _resolve(uint256 id, Job storage j, Challenge storage ch, bytes32 verdict) private {
        Round storage r1 = j.r;
        Round storage r2 = ch.r;
        ch.result = verdict;
        bytes32 old = j.result;
        bool overturned = verdict != old;
        ch.state = overturned ? ChallengeState.Overturned : ChallengeState.Confirmed;
        uint256 pot = ch.bond; // shared by the payees below (the challenger's part comes off first)
        if (overturned) {
            j.result = verdict;
            uint256 slashed;
            for (uint8 i = 0; i < r1.commits; i++) {
                if (!r1.revealed[i] || r1.verdictOf[i] != old) continue;
                address w = r1.seat[i];
                workers[w].rejected += 1;
                slashed += _penalize(w, CHALLENGE_SLASH_BPS, false);
                _record(w, true);
            }
            if (verdict == ch.claim) {
                // The challenger was right: bond back plus half of the slash.
                uint256 toChallenger = slashed / 2;
                credit[ch.challenger] += ch.bond + toChallenger;
                pot = slashed - toChallenger;
            } else {
                // Overturned, but not to what the challenger said: its bond is lost too.
                pot += slashed;
            }
        }
        uint8 n1;
        for (uint8 i = 0; i < r1.commits; i++) if (r1.revealed[i] && r1.verdictOf[i] == verdict) n1++;
        uint8 n2;
        for (uint8 i = 0; i < r2.commits; i++) if (r2.revealed[i] && r2.verdictOf[i] == verdict) n2++;
        // Confirmed: half for this round, half for round 1's winners. Overturned:
        // one equal share each for this round's winners and vindicated round-1 seats.
        uint256 s2;
        uint256 s1;
        if (overturned) {
            s1 = s2 = pot / (uint256(n1) + n2);
            j.agreedBy = n1 + n2;
        } else {
            s2 = (pot / 2) / n2;
            s1 = (pot - pot / 2) / n1;
            j.agreedBy += n2;
        }
        uint256 paid;
        for (uint8 i = 0; i < r1.commits; i++) {
            if (r1.revealed[i] && r1.verdictOf[i] == verdict) { credit[r1.seat[i]] += s1; paid += s1; }
        }
        for (uint8 i = 0; i < r2.commits; i++) {
            address w = r2.seat[i];
            if (r2.revealed[i] && r2.verdictOf[i] == verdict) { credit[w] += s2; paid += s2; _judge(w, true); }
            else if (r2.revealed[i]) _judge(w, false);
            else ch.settleAt = uint64(block.timestamp) + commitWindow;
        }
        _toCommunity(pot - paid); // rounding dust
        emit ChallengeResolved(id, ch.state, verdict);
    }

    /// No quorum: DISPUTE_KEEP_BPS of the bond goes to the seats that
    /// revealed (or the community fund), the rest back; the verdict stands,
    /// Disputed, and a new challenge may open (up to MAX_CHALLENGES).
    function _dispute(uint256 id, Job storage j, Challenge storage ch, bool timedOut) private {
        ch.state = ChallengeState.Disputed;
        Round storage r = ch.r;
        uint256 keep = (ch.bond * DISPUTE_KEEP_BPS) / 10_000;
        credit[ch.challenger] += ch.bond - keep;
        uint256 share = r.reveals == 0 ? 0 : keep / r.reveals;
        for (uint8 i = 0; i < r.commits; i++) {
            if (r.revealed[i]) credit[r.seat[i]] += share;
            else if (timedOut) _miss(id, r.seat[i]);
        }
        _toCommunity(keep - share * r.reveals);
        // Another challenge may open for one more challenge window; round-1
        // bonds stay through it. At the cap the window closes now.
        if (j.chN < MAX_CHALLENGES) {
            j.challengeUntil = uint64(block.timestamp + _challengeWindow());
            _holdRound1(j);
        } else if (j.challengeUntil > block.timestamp) {
            j.challengeUntil = uint64(block.timestamp);
        }
        emit ChallengeResolved(id, ChallengeState.Disputed, j.result);
    }
}

/// @title NeuroJobs: the Neuro ZETAPHY job market (testnet, stage 1-2)
/// @notice Someone asks for a contract to be checked and pays a fee in ZETAPHY.
///         Up to three bonded node runners each compute Neuro's verdict on their
///         own machine. The verdict stands once two of them agree, and those two
///         share the fee plus a reward from the pool.
///
///         Commit-reveal stops a runner from copying another's answer: runners
///         first post keccak256(verdict, runner, salt), and reveal only after
///         all seats are taken or the commit window closes, and before the
///         round's hard deadline (start + jobTimeout).
///
///         Payouts are credited, then pulled with withdraw() (no ETH is pushed
///         to arbitrary addresses inside the job logic).
///
///         Seats are not first-come: per job, a lottery weighted by bond
///         decides who may commit (eligible()). Only runners that registered
///         before the job count, and splitting one bond over many addresses
///         does not raise the odds. The denominator (totalActiveBond) is
///         snapshotted when the round opens, so bonds registered or withdrawn
///         later cannot push drawn runners out. Pool rewards are capped at a
///         quarter of the fee per winner and per day, so requesting jobs for
///         oneself does not pay.
///
///         Lottery bound to a block nobody picks: a request records nothing
///         random. For a round opened in block B:
///           rand = keccak256(seed, blockhash(B + 1), round)
///         usable from block B + 2. seed comes from the request (requester,
///         chain, target, time, the requester's own counter). The value is
///         fixed once B + 1 exists, whoever computes it and whenever: a commit
///         that reverts (NotChosen) and is retried every block, or a contract
///         that calls draw() only when it likes the outcome, gets the same
///         rand. eligible() computes it lazily (a view); the first commit or
///         draw(id) stores it. Limits: (a) blockhash only covers 256 blocks;
///         if nobody stored the draw by then, draw() moves the round to the
///         current block (Redrawn) and a new block hash decides; a party
///         that dislikes the draw cannot cause this while any runner is
///         watching, as any draw()/commit stores it. (b) The proposer of
///         block B + 1 can grind that block's contents (and so its hash) and
///         try many candidates: that is the remaining bias, a validator one.
///         (c) A chain whose BLOCKHASH returns 0 inside the window (old
///         zetaphyd) uses keccak256(seed, 1, round): it works, and is as
///         predictable as the request data alone (the unit-test EVM now gives
///         block hashes; zetaphyd v3+ does too).
///
///         Fee: 90% to the runners whose verdict stood, 5% burned (sent to
///         0x…dEaD, locked forever), 5% to the community fund (credited; it
///         withdraws like a runner). Rounding dust goes to the community
///         fund, so fee = runners + burned + community to the wei. A failed
///         or expired job refunds the fee minus FAIL_BURN_BPS (5%), which is
///         burned: whoever makes fake or unanswerable requests pays for them.
///
///         Bodies (runners eligible per job) are elastic:
///           bodies = DEFENDERS + ceil(requests per minute / CAPACITY_PER_BODY)
///         capped by NeuroControl.maxBodies(). Requests per minute is the
///         busiest recent minute, fading linearly to zero over DECAY_MINUTES.
///         Only requests that pass every check count, and with a NeuroControl
///         only chains on its allowlist (chainAllowed) are accepted.
///
///         Immune system: 4 defender seats, filled by regrow() (anyone may
///         call it) from NeuroControl's voted roster, at most
///         maxRegrowPerHour refills per hour. Defenders do not go by the
///         lottery, and at most ONE defender sits on any round, in every
///         phase of the window, unless no active runner is anything but a
///         seated defender (then defenders fill the seats, so jobs never
///         stall). Runners call heartbeat() (a commit or reveal counts too);
///         a defender silent for longer than NeuroControl.defenderTimeout()
///         stops being a defender at once and loses its seat at regrow().
///
///         Strikes: a rejected verdict, and a seat that committed but never
///         revealed, each cost PENALTY_BPS of the bond and a strike.
///         QUARANTINE_AFTER strikes within a runner's last STRIKE_WINDOW
///         judged seats put it in quarantine: not active, out of
///         totalActiveBond, unbonding, defender seat vacated, register()
///         refused until governance releases it (NeuroControl.release).
///         A penalty that leaves the bond below workerBond also deactivates
///         the runner and starts its unbond timer (withdrawBond after
///         unbondDelay and heldUntil; register() again to top up instead).
///
///         Unrevealed seats: once a quorum forms, a seat that has not
///         revealed yet gets a grace of commitWindow seconds to reveal. After
///         the grace anyone may call settle(id): every seat still unrevealed
///         gets the penalty and a strike. A job that times out (expire())
///         does the same at once.
///
///         Bond holds: a seat's bond stays (heldUntil) until start +
///         2 x jobTimeout of every round it sat on, and a round-1 seat's until
///         challengeUntil + 2 x jobTimeout, moved on when a challenge opens or
///         ends Disputed. Every reveal has a hard deadline, so every slash
///         lands before the hold ends (expire()/settle() have the second
///         jobTimeout to be called).
///
///         Challenges: until challengeUntil (finalize time + challengeWindow,
///         or jobTimeout when 0) anyone may call challenge(id, claim) with a
///         bond of at least max(2 x fee, NeuroControl.challengeBond()) and
///         the verdict it says is right (claim, not the current result). That
///         opens a challenge round: 3 fresh seats by the same lottery (its own
///         start block), never a seat of an earlier round nor any challenger
///         so far; commit-reveal and 2 of 3, hard deadline start + jobTimeout.
///           - Overturned to the claim: each round-1 runner that revealed the
///             overturned verdict loses CHALLENGE_SLASH_BPS (50%) of its bond
///             and gets a strike; the challenger gets its bond back plus half
///             the slash; the other half goes to the round's winners and the
///             round-1 seats that had revealed the new verdict.
///           - Overturned to a verdict that is neither the old one nor the
///             claim: the same slash, but the challenger's whole bond joins
///             the pot (it was wrong too).
///           - Confirmed: the challenger's bond is shared, half by the round's
///             winners, half by round 1's winners.
///           - No quorum (all revealed and none agree, or challengeExpire
///             after jobTimeout): DISPUTE_KEEP_BPS (20%) of the bond goes to
///             the round's seats that revealed (the community fund if none),
///             80% back; the verdict stands, Disputed, and a new challenge may
///             open within a fresh challenge window, up to MAX_CHALLENGES (2)
///             challenges: 3 rounds in all. So a challenge that ends nowhere
///             costs 20% and does not lock out real challengers.
///         Rounding dust always goes to the community fund (to the wei).
///
///         The challenge entry points run in NeuroJobsChallenges (deployed by
///         this constructor) through delegatecall, so NeuroJobs stays under
///         the 24,576-byte code limit; same storage, same address, same ABI.
///
///         NeuroControl's paused() stops new requests, challenges and commits
///         only; reveals, expiry, refunds and withdrawals keep working.
///         Without a NeuroControl nothing is paused, jobs carry skill 0, any
///         chain key is accepted, there are no defenders, bodies are uncapped,
///         challenges need 2 x fee and last jobTimeout, and the community share
///         goes to the reward pool.
contract NeuroJobs is NeuroJobsBase {
    /// The challenge logic (NeuroJobsChallenges), deployed by the constructor.
    address public immutable challengeLogic;

    constructor(uint256 bond_, uint256 reward_, uint256 minFee_, uint64 commitWindow_, uint64 timeout_, uint64 unbondDelay_, uint256 dailyRewardCap_)
        NeuroJobsBase(bond_, reward_, minFee_, commitWindow_, timeout_, unbondDelay_, dailyRewardCap_)
    {
        challengeLogic = address(new NeuroJobsChallenges(bond_, reward_, minFee_, commitWindow_, timeout_, unbondDelay_, dailyRewardCap_));
    }

    /// Wires in NeuroControl. Once, by the deployer.
    function setControl(INeuroKnobs control_) external {
        if (msg.sender != deployer) revert NotDeployer();
        if (address(control) != address(0) || address(control_) == address(0)) revert BadValue();
        control = control_;
        emit ControlSet(address(control_));
    }

    // ---- pool and runners ----

    function fund() external payable {
        if (msg.value == 0) revert BadValue();
        rewardPool += msg.value;
        emit Funded(msg.sender, msg.value);
    }

    /// Joins, or comes back (tops up a bond below workerBond, or cancels
    /// unbonding). Only later jobs count it (since = now).
    function register() external payable {
        Worker storage w = workers[msg.sender];
        if (w.active) revert AlreadyIn();
        if (quarantined(msg.sender)) revert InQuarantine();
        uint256 bond = uint256(w.bond) + msg.value;
        if (bond < workerBond) revert BadValue();
        w.bond = uint128(bond);
        w.active = true;
        w.unbondAt = 0;
        w.since = uint64(block.timestamp);
        w.lastSeen = uint64(block.timestamp);
        activeWorkers += 1;
        totalActiveBond += bond;
        emit Registered(msg.sender, bond);
    }

    /// "Still here": keeps a defender seat (see defenderTimeout). Costs only gas.
    function heartbeat() external {
        Worker storage w = workers[msg.sender];
        if (!w.active) revert NotWorker();
        w.lastSeen = uint64(block.timestamp);
    }

    function requestUnbond() external {
        if (!workers[msg.sender].active) revert NotWorker();
        _deactivate(msg.sender);
    }

    /// After unbondDelay, and after heldUntil (see bond holds).
    function withdrawBond() external {
        Worker storage w = workers[msg.sender];
        if (w.active || w.unbondAt == 0 || block.timestamp < w.unbondAt || block.timestamp < w.heldUntil) revert TooEarly();
        uint256 amount = w.bond;
        w.bond = 0;
        w.unbondAt = 0;
        credit[msg.sender] += amount;
    }

    function withdraw() external {
        uint256 amount = credit[msg.sender];
        if (amount == 0) revert Nothing();
        credit[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: amount}("");
        require(ok, "transfer failed");
    }

    // ---- jobs ----

    /// @param chain   chain key as bytes32, e.g. "bsc"
    /// @param target  address on that chain, at most MAX_TARGET bytes
    function request(bytes32 chain, string calldata target) external payable returns (uint256 id) {
        return _request(msg.sender, chain, target);
    }

    /// Same as request(), but a refund goes to `refundTo` (StableGateway).
    function requestFor(address refundTo, bytes32 chain, string calldata target) external payable returns (uint256 id) {
        if (refundTo == address(0)) revert BadValue();
        return _request(refundTo, chain, target);
    }

    function _request(address requester, bytes32 chain, string calldata target) private returns (uint256 id) {
        if (msg.value < minFee || chain == bytes32(0) || bytes(target).length == 0 || bytes(target).length > MAX_TARGET) revert BadValue();
        bytes32 skill;
        if (address(control) != address(0)) {
            if (control.paused()) revert Paused();
            skill = control.activeSkill();
            if (skill == bytes32(0)) revert NoSkill();
            if (!control.chainAllowed(chain)) revert UnknownChain();
        }
        _countRequest();
        id = jobs.length;
        Job storage j = jobs.push();
        j.requester = requester;
        _open(j.r);
        // Not the job id: jobs slipped in first must not move the seed.
        j.seed = keccak256(abi.encode(requester, chain, target, block.timestamp, requestCount[requester]++));
        j.status = Status.Open;
        j.chain = chain;
        j.target = target;
        j.fee = msg.value;
        j.skill = skill;
        uint256 b = bodies();
        uint256 seated = _seatedDefenders();
        j.bodies = uint16(b);
        j.drawn = uint16(b > seated ? b - seated : 0);
        emit JobRequested(id, chain, target, msg.value);
        emit JobSized(id, skill, b, j.drawn);
    }

    /// Stores the lottery of the round taking seats (round 1 while the job
    /// is open, else the open challenge round). Anyone; once per round; from
    /// block startBlock + 2. If the lottery block fell out of the 256-block
    /// window unused, moves the round to this block instead (Redrawn).
    function draw(uint256 id) external {
        Job storage j = _job(id);
        (Challenge storage ch, uint8 round) = _latest(id);
        Round storage r;
        if (j.status == Status.Open && j.r.rand == 0) { r = j.r; round = 1; }
        else if (ch.state == ChallengeState.Open && ch.r.rand == 0) r = ch.r;
        else revert Nothing();
        bytes32 x = _rand(j.seed, r, round);
        if (x == 0) {
            if (block.number <= uint256(r.startBlock) + 1) revert TooEarly();
            r.startBlock = uint64(block.number);
            emit Redrawn(id, round, r.startBlock);
            return;
        }
        r.rand = x;
        emit Drawn(id, round, x);
    }

    /// @param commitment keccak256(abi.encode(verdict, msg.sender, salt))
    function commit(uint256 id, bytes32 commitment) external {
        Job storage j = _job(id);
        if (j.status != Status.Open) revert Closed();
        _take(id, j.r, 1, commitment);
        emit Committed(id, msg.sender);
    }

    /// Also open after a quorum, until settleAt, for a seat that had not
    /// revealed yet: it is judged against the result (no fee share).
    function reveal(uint256 id, bytes32 verdict, bytes32 salt) external {
        Job storage j = _job(id);
        Round storage r = j.r;
        if (j.status == Status.Open) _revealOpen(r);
        else if (j.settleAt == 0 || block.timestamp >= j.settleAt) revert Closed();
        uint8 same = _reveal(r, verdict, salt);
        emit Revealed(id, msg.sender, verdict);

        if (j.status != Status.Open) {
            // Late reveal inside the grace after a quorum.
            bool ok = verdict == j.result;
            if (ok) j.agreedBy += 1;
            _judge(msg.sender, ok);
            if (r.reveals == r.commits) { j.settleAt = 0; emit Settled(id); }
            return;
        }

        if (same >= QUORUM) _finalize(id, j, verdict);
        else if (r.reveals == r.commits && (r.commits == SEATS || block.timestamp >= r.start + commitWindow)) {
            // Everyone who committed has revealed and no two agree.
            _fail(id, j, false);
        }
    }

    /// Anyone can close a job that ran out of time without a quorum.
    function expire(uint256 id) external {
        Job storage j = _job(id);
        if (j.status != Status.Open) revert Closed();
        if (block.timestamp < j.r.start + jobTimeout) revert TooEarly();
        _fail(id, j, true);
    }

    /// Anyone, once the reveal grace after a quorum is over (in round 1 or
    /// the latest challenge round): every seat that committed and still has
    /// not revealed gets the penalty and a strike.
    function settle(uint256 id) external {
        Job storage j = _job(id);
        (Challenge storage ch,) = _latest(id);
        bool any;
        if (_settleRound(id, j.r, j.settleAt)) { j.settleAt = 0; any = true; }
        if (_settleRound(id, ch.r, ch.settleAt)) { ch.settleAt = 0; any = true; }
        if (!any) {
            if (j.settleAt != 0 || ch.settleAt != 0) revert TooEarly();
            revert Nothing();
        }
        emit Settled(id);
    }

    // ---- challenge rounds (NeuroJobsChallenges, by delegatecall) ----

    /// Opens a challenge round (see above). The whole msg.value is the bond;
    /// `claim` is the verdict the challenger says is right.
    function challenge(uint256, bytes32) external payable { _delegate(); }
    function challengeCommit(uint256, bytes32) external { _delegate(); }
    /// Like reveal(), for a seat of the open (or just decided) challenge round.
    function challengeReveal(uint256, bytes32, bytes32) external { _delegate(); }
    /// Anyone, jobTimeout after the challenge opened, if the round found no quorum.
    function challengeExpire(uint256) external { _delegate(); }

    function _delegate() private {
        address impl = challengeLogic;
        assembly {
            calldatacopy(0, 0, calldatasize())
            let ok := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            if iszero(ok) { revert(0, returndatasize()) }
            return(0, returndatasize())
        }
    }

    // ---- views ----

    function jobCount() external view returns (uint256) {
        return jobs.length;
    }

    function challengeCount() external view returns (uint256) {
        return challenged.length;
    }

    function getJob(uint256 id) external view returns (
        address requester, uint64 created, Status status, bytes32 chain, string memory target,
        uint256 fee, bytes32 result, uint8 commits, uint8 reveals, address[3] memory seat
    ) {
        Job storage j = _job(id);
        return (j.requester, j.r.start, j.status, j.chain, j.target, j.fee, j.result, j.r.commits, j.r.reveals, j.r.seat);
    }

    /// May `w` take a round-1 seat on job `id` right now? False until the
    /// lottery block exists (startBlock + 2). A seated defender may if no
    /// defender sits on the job yet (or only defenders are active). Everyone
    /// else goes by a bond-weighted lottery: about `drawn` runners qualify
    /// at first, twice as many (at least 2 x SEATS) after the first third
    /// of the commit window, and every runner in the last third. Only
    /// runners active since before the job, never quarantined ones.
    function eligible(uint256 id, address w) external view returns (bool ok) {
        if (id >= jobs.length) return false;
        (ok,) = _eligible(id, jobs[id].r, w, 1);
    }

    /// Same for the open challenge round: never a seat of an earlier round or a challenger.
    function challengeEligible(uint256 id, address w) external view returns (bool ok) {
        if (id >= jobs.length) return false;
        (Challenge storage ch, uint8 round) = _latest(id);
        if (ch.state != ChallengeState.Open) return false;
        (ok,) = _eligible(id, ch.r, w, round);
    }

    /// The skill a job was requested under, its body counts, when the reveal
    /// grace after a quorum ends (0 = nothing pending), and its round-1
    /// lottery (0 = not available yet; computed even before anyone stores it).
    function jobInfo(uint256 id) external view returns (bytes32 skill, uint256 bodies_, uint256 drawn, uint64 settleAt, bytes32 rand) {
        Job storage j = _job(id);
        return (j.skill, j.bodies, j.drawn, j.settleAt, _rand(j.seed, j.r, 1));
    }

    /// How sure the verdict is: `agreedBy` distinct runners revealed it, the
    /// latest challenge state, until when it can be challenged, and
    /// `settled`: no challenge is possible or running any more.
    function assurance(uint256 id) external view returns (uint8 agreedBy, ChallengeState state, uint64 challengeUntil, bool settled) {
        Job storage j = _job(id);
        (Challenge storage ch,) = _latest(id);
        state = ch.state;
        settled = j.status == Status.Done && state != ChallengeState.Open
            && (state == ChallengeState.Confirmed || state == ChallengeState.Overturned || block.timestamp >= j.challengeUntil);
        return (j.agreedBy, state, j.challengeUntil, settled);
    }

    /// The latest challenge round of job `id` (see challengeRound for which one).
    function challengeInfo(uint256 id) external view returns (
        address challenger, ChallengeState state, uint256 bond, uint64 start, bytes32 rand,
        uint8 commits, uint8 reveals, address[3] memory seat, bytes32 result, uint64 settleAt
    ) {
        _job(id);
        (Challenge storage ch, uint8 round) = _latest(id);
        rand = _rand(jobs[id].seed, ch.r, round);
        challenger = ch.challenger;
        state = ch.state;
        bond = ch.bond;
        start = ch.r.start;
        commits = ch.r.commits;
        reveals = ch.r.reveals;
        seat = ch.r.seat;
        result = ch.result;
        settleAt = ch.settleAt;
    }

    /// How many challenges job `id` has had (the latest is round count + 1)
    /// and what the latest challenger claimed.
    function challengeRound(uint256 id) external view returns (uint8 count, bytes32 claim) {
        _job(id);
        (Challenge storage ch,) = _latest(id);
        return (jobs[id].chN, ch.claim);
    }

    /// Requests per minute right now, times DECAY_MINUTES.
    function load() public view returns (uint256) {
        uint64 m = uint64(block.timestamp / 60);
        uint256 a = _fade(loadCount, loadMinute, m);
        uint256 b = _fade(peakCount, peakMinute, m);
        return a > b ? a : b;
    }

    /// Bodies for a job requested now: DEFENDERS + ceil(requests per minute
    /// / CAPACITY_PER_BODY), at most NeuroControl.maxBodies().
    function bodies() public view returns (uint256 n) {
        uint256 unit = DECAY_MINUTES * CAPACITY_PER_BODY;
        n = DEFENDERS + (load() + unit - 1) / unit;
        uint256 cap = address(control) != address(0) ? control.maxBodies() : type(uint16).max;
        if (n > cap) n = cap;
    }

    function defenders() external view returns (address[4] memory) {
        return defender;
    }

    // ---- immune system ----

    /// Anyone may call it. Vacates defender seats whose runner is no longer
    /// fit, then refills empty seats from NeuroControl's roster, at most
    /// maxRegrowPerHour refills per clock hour.
    function regrow() external returns (uint256 filled) {
        if (address(control) == address(0)) revert NoControl();
        for (uint256 i = 0; i < DEFENDERS; i++) {
            address d = defender[i];
            if (d != address(0) && !_fit(d)) {
                defender[i] = address(0);
                emit DefenderVacated(d, i);
            }
        }
        uint64 hour = uint64(block.timestamp / 1 hours);
        if (regrowHour != hour) { regrowHour = hour; regrownThisHour = 0; }
        uint256 cap = control.maxRegrowPerHour();
        address[] memory r = control.roster();
        uint256 next = 0;
        for (uint256 i = 0; i < DEFENDERS && regrownThisHour < cap; i++) {
            if (defender[i] != address(0)) continue;
            for (; next < r.length; next++) {
                address cand = r[next];
                if (!_seated(cand) && _fit(cand)) {
                    defender[i] = cand;
                    regrownThisHour += 1;
                    filled += 1;
                    emit DefenderSeated(cand, i);
                    next++;
                    break;
                }
            }
            if (next >= r.length && defender[i] == address(0)) break;
        }
    }

    // ---- internals ----

    function _finalize(uint256 id, Job storage j, bytes32 verdict) private {
        Round storage r = j.r;
        j.status = Status.Done;
        j.result = verdict;
        j.challengeUntil = uint64(block.timestamp + _challengeWindow());
        uint8 winners = 0;
        for (uint8 i = 0; i < r.commits; i++) if (r.revealed[i] && r.verdictOf[i] == verdict) winners++;
        j.agreedBy = winners;
        uint256 burnCut = (j.fee * BURN_BPS) / 10_000;
        uint256 fundCut = (j.fee * COMMUNITY_BPS) / 10_000;
        uint256 toRunners = j.fee - burnCut - fundCut;
        uint256 share = toRunners / winners;
        fundCut += toRunners - share * winners; // rounding dust
        // Pool reward per winner: at most jobReward and at most a quarter of
        // the fee, within the daily cap.
        uint256 reward = jobReward < j.fee / 4 ? jobReward : j.fee / 4;
        uint64 today = uint64(block.timestamp / 1 days);
        if (rewardDay != today) { rewardDay = today; rewardedToday = 0; }
        // Every round-1 seat may be slashed by a challenge: its bond stays until then.
        _holdRound1(j);
        for (uint8 i = 0; i < r.commits; i++) {
            address w = r.seat[i];
            if (r.revealed[i] && r.verdictOf[i] == verdict) {
                uint256 pay = share;
                if (reward > 0 && rewardPool >= reward && rewardedToday + reward <= dailyRewardCap) {
                    rewardPool -= reward;
                    rewardedToday += reward;
                    pay += reward;
                }
                credit[w] += pay;
                _judge(w, true);
            } else if (r.revealed[i]) {
                _judge(w, false);
            } else {
                // Not revealed yet: a grace to reveal, then settle() judges it.
                j.settleAt = uint64(block.timestamp) + commitWindow;
            }
        }
        _toCommunity(fundCut);
        totalBurned += burnCut;
        emit FeeSplit(id, share * winners, burnCut, fundCut);
        emit Finalized(id, verdict);
        // Last: BURN has no code, so this cannot call back.
        if (burnCut > 0) {
            (bool ok,) = BURN.call{value: burnCut}("");
            require(ok, "burn failed");
        }
    }

    function _fail(uint256 id, Job storage j, bool timedOut) private {
        j.status = Status.Failed;
        uint256 burnCut = (j.fee * FAIL_BURN_BPS) / 10_000;
        credit[j.requester] += j.fee - burnCut;
        if (timedOut) {
            for (uint8 i = 0; i < j.r.commits; i++) if (!j.r.revealed[i]) _miss(id, j.r.seat[i]);
        }
        totalBurned += burnCut;
        emit FeeSplit(id, 0, burnCut, 0);
        emit JobFailed(id);
        // Last: BURN has no code, so this cannot call back.
        if (burnCut > 0) {
            (bool ok,) = BURN.call{value: burnCut}("");
            require(ok, "burn failed");
        }
    }

    function _seated(address w) private view returns (bool) {
        for (uint256 i = 0; i < DEFENDERS; i++) if (defender[i] == w) return true;
        return false;
    }

    /// N requests counted at minute `from`, seen at minute `m`: N*(DECAY-age), 0 after DECAY_MINUTES.
    function _fade(uint256 n, uint64 from, uint64 m) private pure returns (uint256) {
        uint256 age = m - from;
        return age >= DECAY_MINUTES ? 0 : n * (DECAY_MINUTES - age);
    }

    function _countRequest() private {
        uint64 m = uint64(block.timestamp / 60);
        if (m != loadMinute) {
            // The finished minute becomes the peak if it outweighs the fading one.
            if (_fade(loadCount, loadMinute, m) >= _fade(peakCount, peakMinute, m)) { peakCount = loadCount; peakMinute = loadMinute; }
            loadMinute = m;
            loadCount = 0;
        }
        loadCount += 1;
    }
}

contracts/NeuroValidation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IValidationRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

interface IIdentityRegistry {
    function ownerOf(uint256 tokenId) external view returns (address);
    function getApproved(uint256 tokenId) external view returns (address);
    function isApprovedForAll(address owner, address operator) external view returns (bool);
    function webEndpoint(uint256 agentId) external view returns (string memory);
}

/// @title NeuroValidation: ERC-8004 Validation Registry answered by Neuro runners
/// @notice The ERC-8004 Validation Registry interface. Validators here are the
///         bonded NeuroJobs runners with a track record (active, at least
///         `minAgreed` accepted verdicts, no more rejected than accepted):
///         stake-secured re-execution, which ERC-8004 calls "crypto-economic"
///         trust. A runner posts Neuro's verdict on an agent (a contract's
///         identity) as a validation response: the verdict hash and a 0-100
///         score.
///
///         - `validationRequest` / `validationResponse` follow the spec: the
///           agent's owner or operator asks a named validator, and only that
///           validator answers (and it must be a runner when it answers).
///         - `postVerdict` lets a runner publish a verdict on any agent without
///           a request, because an unclaimed contract identity has no owner to
///           ask, and an owner must not be able to keep Neuro's verdicts off
///           its identity. It emits the same two spec events.
///         - Each runner has ONE verdict slot per agent, at
///           `verdictRequestHash(agentId, runner)`. A newer verdict replaces the
///           older one. Verdict slots live in their own namespace: their hash
///           starts with VERDICT_TAG, and `validationRequest` refuses any hash
///           that does, so nobody can pre-create a runner's slot under another
///           agent and steal its verdicts.
///         - `getSummary` counts each validator once per agent: its latest
///           answer there (a verdict or a spec response). One runner cannot
///           outweigh the others by answering many times.
///         - A spec `requestHash` is first come, first served (the spec reads
///           by the bare hash, so it cannot be bound to the requester). Make it
///           commit to the request (e.g. keccak of agentId, validator and the
///           request file); if someone takes it first, `validationRequest`
///           reverts `Exists` and nothing of yours is written, so pick a new
///           hash. Validators should check `getValidationStatus(h).agentId`
///           before answering.
contract NeuroValidation {
    struct ValidationStatus {
        address validatorAddress;
        uint256 agentId;
        uint8 response;      // 0..100
        bytes32 responseHash;
        string tag;
        uint256 lastUpdate;
        bool hasResponse;
    }

    address public immutable identityRegistry;
    IValidationRunners public immutable runners;
    uint32 public immutable minAgreed;
    uint256 public constant MAX_TAG = 64;
    /// First 4 bytes of every postVerdict slot hash ("NVD1"); spec requests may not use them.
    bytes4 public constant VERDICT_TAG = 0x4e564431;
    bytes32 private constant TAG_MASK = 0xffffffff00000000000000000000000000000000000000000000000000000000;

    mapping(bytes32 => ValidationStatus) private _validations;
    mapping(uint256 => bytes32[]) private _agentValidations;
    mapping(address => bytes32[]) private _validatorRequests;
    /// agentId => validator => requestHash of its latest answer on that agent
    mapping(uint256 => mapping(address => bytes32)) private _latest;

    event ValidationRequest(address indexed validatorAddress, uint256 indexed agentId, string requestURI, bytes32 indexed requestHash);
    event ValidationResponse(address indexed validatorAddress, uint256 indexed agentId, bytes32 indexed requestHash,
        uint8 response, string responseURI, bytes32 responseHash, string tag);

    error BadValue();
    error NotAuthorized();
    error Exists();
    error Unknown();
    error NotValidator();
    error NotRunner();
    error ReservedHash();

    constructor(address identityRegistry_, IValidationRunners runners_, uint32 minAgreed_) {
        if (identityRegistry_ == address(0) || address(runners_) == address(0) || minAgreed_ == 0) revert BadValue();
        identityRegistry = identityRegistry_;
        runners = runners_;
        minAgreed = minAgreed_;
    }

    function getIdentityRegistry() external view returns (address) {
        return identityRegistry;
    }

    /// Is `who` a bonded runner with a track record right now?
    function isRunner(address who) public view returns (bool) {
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(who);
        return active && agreed >= minAgreed && rejected <= agreed;
    }

    // ---------------------------------------------------------- ERC-8004

    function validationRequest(address validatorAddress, uint256 agentId, string calldata requestURI, bytes32 requestHash) external {
        if (validatorAddress == address(0) || requestHash == bytes32(0)) revert BadValue();
        if (isVerdictHash(requestHash)) revert ReservedHash();
        if (_validations[requestHash].validatorAddress != address(0)) revert Exists();
        IIdentityRegistry reg = IIdentityRegistry(identityRegistry);
        address owner = reg.ownerOf(agentId);
        if (msg.sender != owner && !reg.isApprovedForAll(owner, msg.sender) && reg.getApproved(agentId) != msg.sender) revert NotAuthorized();
        _open(validatorAddress, agentId, requestURI, requestHash);
    }

    function validationResponse(bytes32 requestHash, uint8 response, string calldata responseURI, bytes32 responseHash, string calldata tag) external {
        ValidationStatus storage s = _validations[requestHash];
        if (s.validatorAddress == address(0)) revert Unknown();
        if (msg.sender != s.validatorAddress) revert NotValidator();
        if (!isRunner(msg.sender)) revert NotRunner();
        _answer(s, requestHash, response, responseURI, responseHash, tag);
    }

    // ------------------------------------------------------------- Neuro

    /// A runner publishes Neuro's verdict on `agentId`: `verdictHash` is the
    /// verdict (as in NeuroJobs, stored as the responseHash), `score` 0-100
    /// (100 = no problems found). A runner has one verdict slot per agent: a
    /// new post replaces its previous verdict there.
    function postVerdict(uint256 agentId, bytes32 verdictHash, uint8 score, string calldata responseURI, string calldata tag)
        external returns (bytes32 requestHash)
    {
        if (!isRunner(msg.sender)) revert NotRunner();
        if (verdictHash == bytes32(0)) revert BadValue();
        IIdentityRegistry(identityRegistry).ownerOf(agentId); // reverts for an unknown agent
        requestHash = verdictRequestHash(agentId, msg.sender);
        ValidationStatus storage s = _validations[requestHash];
        if (s.validatorAddress == address(0)) {
            string memory uri;
            try IIdentityRegistry(identityRegistry).webEndpoint(agentId) returns (string memory u) { uri = u; } catch {}
            _open(msg.sender, agentId, uri, requestHash);
        } else if (s.agentId != agentId || s.validatorAddress != msg.sender) {
            revert NotAuthorized(); // unreachable while only postVerdict writes tagged slots; kept as a guard
        }
        _answer(s, requestHash, score, responseURI, verdictHash, tag);
    }

    /// The one verdict slot of `runner` on `agentId`. Its first 4 bytes are VERDICT_TAG.
    function verdictRequestHash(uint256 agentId, address runner) public view returns (bytes32) {
        bytes32 h = keccak256(abi.encode("neuro.verdict.v1", address(this), agentId, runner));
        return (h & ~TAG_MASK) | bytes32(VERDICT_TAG);
    }

    /// Is `requestHash` in the postVerdict namespace (closed to validationRequest)?
    function isVerdictHash(bytes32 requestHash) public pure returns (bool) {
        return bytes4(requestHash) == VERDICT_TAG;
    }

    // ------------------------------------------------------------- reads

    function getValidationStatus(bytes32 requestHash) external view returns (
        address validatorAddress, uint256 agentId, uint8 response, bytes32 responseHash, string memory tag, uint256 lastUpdate
    ) {
        ValidationStatus storage s = _validations[requestHash];
        if (s.validatorAddress == address(0)) revert Unknown();
        return (s.validatorAddress, s.agentId, s.response, s.responseHash, s.tag, s.lastUpdate);
    }

    /// Average response of answered validations, optionally only from
    /// `validatorAddresses` and with `tag`. Each validator counts once per
    /// agent: only its latest answer on that agent is read.
    function getSummary(uint256 agentId, address[] calldata validatorAddresses, string calldata tag)
        external view returns (uint64 count, uint8 averageResponse)
    {
        bytes32[] storage list = _agentValidations[agentId];
        bytes32 tagHash = keccak256(bytes(tag));
        uint256 total;
        for (uint256 i; i < list.length; i++) {
            ValidationStatus storage s = _validations[list[i]];
            if (!s.hasResponse) continue;
            if (_latest[agentId][s.validatorAddress] != list[i]) continue; // superseded by a newer answer
            if (bytes(tag).length > 0 && keccak256(bytes(s.tag)) != tagHash) continue;
            if (validatorAddresses.length > 0) {
                bool found;
                for (uint256 j; j < validatorAddresses.length; j++) if (validatorAddresses[j] == s.validatorAddress) { found = true; break; }
                if (!found) continue;
            }
            total += s.response;
            count++;
        }
        averageResponse = count > 0 ? uint8(total / count) : 0;
    }

    function getAgentValidations(uint256 agentId) external view returns (bytes32[] memory) {
        return _agentValidations[agentId];
    }

    function getValidatorRequests(address validatorAddress) external view returns (bytes32[] memory) {
        return _validatorRequests[validatorAddress];
    }

    // ------------------------------------------------------------ internal

    function _open(address validatorAddress, uint256 agentId, string memory requestURI, bytes32 requestHash) internal {
        ValidationStatus storage s = _validations[requestHash];
        s.validatorAddress = validatorAddress;
        s.agentId = agentId;
        s.lastUpdate = block.timestamp;
        _agentValidations[agentId].push(requestHash);
        _validatorRequests[validatorAddress].push(requestHash);
        emit ValidationRequest(validatorAddress, agentId, requestURI, requestHash);
    }

    function _answer(ValidationStatus storage s, bytes32 requestHash, uint8 response, string calldata responseURI, bytes32 responseHash, string calldata tag) internal {
        if (response > 100 || bytes(tag).length > MAX_TAG) revert BadValue();
        s.response = response;
        s.responseHash = responseHash;
        s.tag = tag;
        s.lastUpdate = block.timestamp;
        s.hasResponse = true;
        _latest[s.agentId][s.validatorAddress] = requestHash;
        emit ValidationResponse(s.validatorAddress, s.agentId, requestHash, response, responseURI, responseHash, tag);
    }
}

contracts/QuantumWallet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title QuantumWallet: a smart wallet a quantum computer cannot drain (stage 5)
/// @notice Every action needs an ML-DSA signature (FIPS 204, post-quantum),
///         checked by ZETAPHY's precompile at 0x…0900. Two modes:
///           - hybrid: ECDSA AND ML-DSA must both sign (today's security, plus
///             protection if ECDSA is ever broken)
///           - post-quantum only: no ECDSA key at all (ecdsaOwner = 0)
///         Anyone may submit a signed action and pay its gas (a relay), so the
///         owner needs no other account. Keys rotate only through the wallet
///         itself, i.e. with the current keys' signatures.
contract QuantumWallet {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;

    address public ecdsaOwner;   // 0 = post-quantum only
    uint8 public variant;        // 44 or 65 (ML-DSA parameter set)
    bytes32 public pqKeyHash;    // keccak256 of the ML-DSA public key (the key itself rides in calldata)
    uint256 public nonce;

    /// The signatures for one action. pqPublicKey must hash to pqKeyHash;
    /// ecdsaSig is ignored in post-quantum-only mode.
    struct Auth {
        bytes pqPublicKey;
        bytes pqSig;
        bytes ecdsaSig;
    }

    event Executed(uint256 indexed nonce, address indexed to, uint256 value);
    event KeysChanged(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash);

    error Expired();
    error BadEcdsa();
    error BadPq();
    error WrongKey();
    error BadVariant();
    error OnlySelf();
    error CallFailed(bytes reason);

    constructor(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) payable {
        _setKeys(ecdsaOwner_, variant_, pqKeyHash_);
    }

    receive() external payable {}

    /// The 32 bytes both keys sign for one action.
    function digest(address to, uint256 value, bytes calldata data, uint256 deadline) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY QuantumWallet", block.chainid, address(this), nonce, to, value, keccak256(data), deadline));
    }

    function execute(address to, uint256 value, bytes calldata data, uint256 deadline, Auth calldata auth)
        external returns (bytes memory)
    {
        if (block.timestamp > deadline) revert Expired();
        _authorize(digest(to, value, data, deadline), auth);
        uint256 n = nonce++;
        (bool ok, bytes memory ret) = to.call{value: value}(data);
        if (!ok) revert CallFailed(ret);
        emit Executed(n, to, value);
        return ret;
    }

    function _authorize(bytes32 d, Auth calldata auth) private view {
        if (ecdsaOwner != address(0) && _recover(d, auth.ecdsaSig) != ecdsaOwner) revert BadEcdsa();
        if (keccak256(auth.pqPublicKey) != pqKeyHash) revert WrongKey();
        if (!_pqValid(d, auth.pqPublicKey, auth.pqSig)) revert BadPq();
    }

    /// Rotate keys or switch mode; callable only by execute() on this wallet.
    function setKeys(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) external {
        if (msg.sender != address(this)) revert OnlySelf();
        _setKeys(ecdsaOwner_, variant_, pqKeyHash_);
    }

    function _setKeys(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) private {
        if ((variant_ != 44 && variant_ != 65) || pqKeyHash_ == bytes32(0)) revert BadVariant();
        ecdsaOwner = ecdsaOwner_;
        variant = variant_;
        pqKeyHash = pqKeyHash_;
        emit KeysChanged(ecdsaOwner_, variant_, pqKeyHash_);
    }

    function _pqValid(bytes32 d, bytes calldata pk, bytes calldata sig) private view returns (bool) {
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(variant, d, pk, sig));
        return ok && ret.length == 32 && uint256(bytes32(ret)) == 1;
    }

    function _recover(bytes32 d, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) return address(0);
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) return address(0);
        return ecrecover(d, v, r, s);
    }
}

/// @title QuantumWalletFactory: wallets at an address known before they exist
/// @notice The address depends only on the keys, so funds can be sent to a
///         wallet before it is deployed, and anyone can deploy it later.
contract QuantumWalletFactory {
    event Created(address indexed wallet, address ecdsaOwner, uint8 variant, bytes32 pqKeyHash);

    function create(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash) external returns (address w) {
        w = address(new QuantumWallet{salt: _salt(ecdsaOwner, variant, pqKeyHash)}(ecdsaOwner, variant, pqKeyHash));
        emit Created(w, ecdsaOwner, variant, pqKeyHash);
    }

    function predict(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash) external view returns (address) {
        bytes32 h = keccak256(abi.encodePacked(bytes1(0xff), address(this), _salt(ecdsaOwner, variant, pqKeyHash),
            keccak256(abi.encodePacked(type(QuantumWallet).creationCode, abi.encode(ecdsaOwner, variant, pqKeyHash)))));
        return address(uint160(uint256(h)));
    }

    function _salt(address e, uint8 v, bytes32 k) private pure returns (bytes32) {
        return keccak256(abi.encode(e, v, k));
    }
}

contracts/RewardVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IFundable {
    function fund() external payable;
}

/// @title RewardVault: releases the ZETAPHY reward pool at 10% a year
/// @notice The 500,000,000 ZETAPHY set aside for runners and validators sit
///         here instead of in a key-holder's account. Every day, anyone can
///         call `release()`, which pays out the share of the remaining pool
///         that has vested: 10% of what is left per year, in daily steps
///         (0.9^(1/365) is kept each day), so the pool lasts for decades.
///
///         There is NO withdraw function. Governance can only choose who
///         receives the releases (e.g. NeuroJobs' reward pool, a validator
///         rewards contract), and a change only takes effect DELAY after it
///         is announced, so everyone can see it coming. Nobody can make the
///         vault pay faster than the schedule.
contract RewardVault {
    uint256 private constant RAY = 1e27;
    /// 0.9^(1/365) in RAY: keep^365 = 0.9 (to 1e-25)
    uint256 public constant DAILY_KEEP = 999711382710977687364396358;
    uint256 public constant DELAY = 7 days;
    uint256 public constant MAX_SHARES = 8;

    struct Share {
        address to;
        uint16 bps;      // out of 10,000
        bool callFund;   // pay through `fund()` (NeuroJobs, ComputeMarket) instead of a plain transfer
    }

    uint64 public immutable start;
    uint64 public releasedDays;
    address public governance;
    Share[] private _shares;
    Share[] private _pending;
    uint64 public pendingAt; // 0 = nothing pending

    event Released(uint256 day, uint256 amount);
    event Paid(address indexed to, uint256 amount, bool ok);
    event SharesProposed(uint64 effectiveAt);
    event SharesApplied();
    event GovernanceChanged(address governance);

    error NotGovernance();
    error BadShares();
    error TooEarly();

    constructor(address governance_, Share[] memory shares_) {
        governance = governance_;
        start = uint64(block.timestamp);
        _check(shares_);
        for (uint256 i = 0; i < shares_.length; i++) _shares.push(shares_[i]);
    }

    receive() external payable {}

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    // ---- schedule ----

    function daysElapsed() public view returns (uint256) {
        return (block.timestamp - start) / 1 days;
    }

    /// What `release()` would pay right now.
    function releasable() public view returns (uint256) {
        uint256 n = daysElapsed() - releasedDays;
        if (n == 0) return 0;
        uint256 bal = address(this).balance;
        return bal - (bal * _rpow(DAILY_KEEP, n)) / RAY;
    }

    /// Pays out everything vested since the last release. Anyone may call it.
    function release() public returns (uint256 amount) {
        amount = releasable();
        releasedDays = uint64(daysElapsed()); // before any external call
        if (amount == 0) return 0;
        emit Released(releasedDays, amount);
        uint256 left = amount;
        for (uint256 i = 0; i < _shares.length; i++) {
            Share memory s = _shares[i];
            uint256 part = i + 1 == _shares.length ? left : (amount * s.bps) / 10_000;
            left -= part;
            bool ok;
            if (s.callFund) {
                (ok, ) = s.to.call{value: part}(abi.encodeCall(IFundable.fund, ()));
            } else {
                (ok, ) = s.to.call{value: part}("");
            }
            // A recipient that refuses keeps nothing: the amount stays in the
            // vault (and keeps vesting); a broken recipient cannot block others.
            emit Paid(s.to, ok ? part : 0, ok);
        }
    }

    // ---- recipients ----

    function shares() external view returns (Share[] memory) {
        return _shares;
    }

    function pendingShares() external view returns (Share[] memory) {
        return _pending;
    }

    /// Announces new recipients; they apply DELAY later.
    function proposeShares(Share[] calldata next) external onlyGovernance {
        _check(next);
        delete _pending;
        for (uint256 i = 0; i < next.length; i++) _pending.push(next[i]);
        pendingAt = uint64(block.timestamp + DELAY);
        emit SharesProposed(pendingAt);
    }

    function cancelShares() external onlyGovernance {
        delete _pending;
        pendingAt = 0;
    }

    /// After the delay, anyone may switch to the announced recipients.
    /// What vested before the switch is paid to the old ones first.
    function applyShares() external {
        if (pendingAt == 0 || block.timestamp < pendingAt) revert TooEarly();
        // Take the pending list first: a recipient called during release()
        // must not be able to apply it a second time.
        Share[] memory next = _pending;
        delete _pending;
        pendingAt = 0;
        release();
        delete _shares;
        for (uint256 i = 0; i < next.length; i++) _shares.push(next[i]);
        emit SharesApplied();
    }

    function setGovernance(address next) external onlyGovernance {
        governance = next;
        emit GovernanceChanged(next);
    }

    // ---- internals ----

    function _check(Share[] memory s) private pure {
        if (s.length == 0 || s.length > MAX_SHARES) revert BadShares();
        uint256 total;
        for (uint256 i = 0; i < s.length; i++) {
            if (s[i].to == address(0) || s[i].bps == 0) revert BadShares();
            total += s[i].bps;
        }
        if (total != 10_000) revert BadShares();
    }

    /// x^n in RAY fixed point (exponentiation by squaring, rounding half up).
    function _rpow(uint256 x, uint256 n) private pure returns (uint256 z) {
        z = n % 2 != 0 ? x : RAY;
        for (n /= 2; n != 0; n /= 2) {
            x = (x * x + RAY / 2) / RAY;
            if (n % 2 != 0) z = (z * x + RAY / 2) / RAY;
        }
    }
}

contracts/SaphanTokens.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// ZETAPHY Saphan, token routes: tokens BORN on ZETAPHY go out to an EVM chain and come back
// (the reverse of the v2 ETH routes in HyperlaneLockBoxV2.sol). docs/SAPHAN-TOKENS.md.
//
//   ZETAPHY                                                     destination chain X (Sepolia, Base Sepolia, ...)
//   ZetaphyTokenVault(token, X) --lock: Hyperlane message---->  SaphanSyntheticToken(token, X) queues a mint,
//     escrows the token             (ISM on X: OUR validators   mints after the delay (veto, daily cap, supply cap, pause)
//                                    for origin ZETAPHY)
//     queues a release <-----------burn: Hyperlane message----- sendBack(): burns, dispatches
//     pays after the delay          (ISM on ZETAPHY: Hyperlane's validator(s) for origin X)
//     (veto, daily limit, pause, never more than it locked for X)
//
// One vault per (token, destination) and one synthetic per (token, destination): a hole on chain X (or in X's
// synthetic, or X's validators) can only ask vault(token, X) for a release, and that vault pays at most what was
// locked in it for X. It cannot reach another token's vault or another destination's escrow.
//
// Local copies of the Hyperlane v3 interfaces, checked against hyperlane-xyz/hyperlane-monorepo at commit
// 1aadbba0696ecf96ed4c06f78c978d08db22c0ad (as HyperlaneLockBoxV2.sol): IMailbox dispatch / quoteDispatch,
// IMessageRecipient.handle, ISpecifiesInterchainSecurityModule.interchainSecurityModule. Named apart from the
// other files' copies (the build compiles every file in one unit and names artifacts by contract).

interface ISaphanTokenMailbox {
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256 fee);
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody, bytes calldata customHookMetadata, address customHook) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody, bytes calldata customHookMetadata, address customHook) external view returns (uint256 fee);
}

interface ISaphanTokenIsm {
    function moduleType() external view returns (uint8);
    function verify(bytes calldata metadata, bytes calldata message) external returns (bool);
}

/// ThreatRegistry's hold view for ZETAPHY addresses (as BridgeGuard uses it).
interface ISaphanTokenThreats {
    function isContractHeld(address who) external view returns (bool, uint8);
}

/// @title SaphanTokenEndpoint: what both ends of a token route share
/// @notice Sending: the subclass takes the tokens (_take: the vault escrows, the synthetic burns), then this
///         dispatches a 288-byte body through the local Mailbox to the one remote contract:
///           abi.encode(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to,
///                      uint256 amount, uint256 dstChainId, address dstContract, address originToken)
///         `originToken` is the token's address on ZETAPHY (the same on both ends), so a message of token A can
///         never be taken by token B's endpoint even if every other field matched.
///         Receiving: handle() takes a message only from the Mailbox (after the ISM this contract names, never the
///         Mailbox default, never zero), from the remote domain and the remote contract (sender), whose body names
///         the remote chain and contract as the source, this chain and contract as the destination, and this
///         route's origin token; each message once. It never pays at once: the payout is queued (Queued) and anyone
///         claims it after `delay`, while not vetoed, not paused and within the daily limit (over it, it waits for
///         the next UTC day); the subclass adds its own bound (_pay: the vault's backing, the synthetic's supply
///         cap). A message is never refused for a limit or a pause, so nothing depends on the relayer retrying.
///         Starts PAUSED (deployed closed): opening is governance's unpause, on both ends.
///         Roles: governance (a timelock: 48 h) unpauses, lifts vetoes, raises limits, changes the ISM; guardians
///         (a multisig) only reduce risk, at once: pause, veto, lower the daily limit, lengthen the delay.
abstract contract SaphanTokenEndpoint {
    struct Pending {
        address to;
        uint64 readyAt;      // zero: no such message
        bool done;
        bool vetoed;
        uint256 amount;
    }

    /// The message body (288 bytes, abi.encode of these fields in this order).
    struct Body {
        uint256 srcChainId;
        address srcContract;
        uint256 srcNonce;
        address sender;
        address to;
        uint256 amount;
        uint256 dstChainId;
        address dstContract;
        address originToken;
    }

    ISaphanTokenMailbox public immutable mailbox;
    uint32 public immutable remoteDomain;     // the other end's Hyperlane domain
    uint256 public immutable remoteChainId;   // the other end's EVM chain id, as it writes it into bodies
    bytes32 public immutable remote;          // the other end's contract (the only sender, the only recipient)
    address public immutable hook;            // zero = the Mailbox default hook
    address public immutable originToken;     // the token's address on ZETAPHY

    uint64 public constant MAX_DELAY = 30 days;
    uint256 public constant BODY_LENGTH = 288;

    address public governance;
    mapping(address => bool) public guardian;
    /// Hyperlane reads this (ISpecifiesInterchainSecurityModule). Never zero.
    ISaphanTokenIsm public interchainSecurityModule;
    bool public paused;
    uint256 public dailyLimit;                // token units paid out (released / minted) per UTC day
    uint256 public paidToday;
    uint64 public day;
    uint64 public delay;                      // seconds between a message and its claim

    uint256 public nonce;                     // messages sent
    uint256 public received;                  // messages recorded (the relayer workflow compares it with the other end's nonce)
    mapping(bytes32 => Pending) public pending; // by keccak256(body)
    uint256 private entered = 1;

    event Sent(uint256 indexed nonce, address indexed sender, address indexed to, uint256 amount, bytes32 messageId);
    event Queued(bytes32 indexed id, uint256 indexed srcNonce, address sender, address indexed to, uint256 amount, uint64 readyAt);
    event Paid(bytes32 indexed id, address indexed to, uint256 amount);
    event Vetoed(bytes32 indexed id, address indexed by);
    event VetoLifted(bytes32 indexed id);
    event Paused(address indexed by);
    event Unpaused();
    event IsmSet(address ism);
    event GovernanceSet(address governance);
    event GuardianSet(address indexed who, bool on);
    event DailyLimitSet(uint256 limit);
    event DelaySet(uint64 delay);

    error NotGovernance();
    error NotGuardian();
    error NotMailbox();
    error WrongOrigin(uint32 origin);
    error WrongSender(bytes32 sender);
    error WrongSource();
    error WrongDestination();
    error WrongToken(address token);
    error BadBody();
    error Replay(bytes32 id);
    error NoValue();
    error IsPaused();
    error NoMessage();
    error AlreadyDone();
    error IsVetoed();
    error NotReady(uint64 readyAt);
    error OverLimit(uint256 remaining);
    error PayFailed();
    error Fee(uint256 needed);
    error Reentered();

    /// Deploy settings shared by both ends (one tuple: fewer constructor arguments).
    struct Config {
        ISaphanTokenMailbox mailbox;
        uint32 remoteDomain;
        uint256 remoteChainId;
        bytes32 remote;
        address hook;
        address originToken;
        ISaphanTokenIsm ism;
        address governance;
        address guardian;
        uint256 dailyLimit;
        uint64 delay;
    }

    constructor(Config memory c) {
        require(address(c.mailbox) != address(0) && c.remote != bytes32(0) && c.remoteChainId != 0 && c.originToken != address(0)
            && address(c.ism) != address(0) && c.governance != address(0) && c.delay <= MAX_DELAY, "config");
        mailbox = c.mailbox;
        remoteDomain = c.remoteDomain;
        remoteChainId = c.remoteChainId;
        remote = c.remote;
        hook = c.hook;
        originToken = c.originToken;
        interchainSecurityModule = c.ism;
        governance = c.governance;
        dailyLimit = c.dailyLimit;
        delay = c.delay;
        paused = true;
        emit IsmSet(address(c.ism));
        emit GovernanceSet(c.governance);
        emit DailyLimitSet(c.dailyLimit);
        emit DelaySet(c.delay);
        emit Paused(msg.sender);
        if (c.guardian != address(0)) { guardian[c.guardian] = true; emit GuardianSet(c.guardian, true); }
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }
    modifier onlyGuardian() { if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian(); _; }
    modifier nonReentrant() { if (entered != 1) revert Reentered(); entered = 2; _; entered = 1; }

    // ---------------------------------------------------------------- what the two ends do differently

    /// Takes `amount` from msg.sender for a send (the vault escrows it, the synthetic burns it).
    function _take(address from, uint256 amount) internal virtual;
    /// Pays a claimed message (the vault releases within its backing, the synthetic mints within its cap).
    function _pay(address to, uint256 amount) internal virtual;

    // ---------------------------------------------------------------- sending

    function body(uint256 n, address sender, address to, uint256 amount) public view returns (bytes memory) {
        return abi.encode(block.chainid, address(this), n, sender, to, amount, remoteChainId, address(uint160(uint256(remote))), originToken);
    }

    /// The Mailbox fee for the next send (msg.value of the send).
    function quote(address to, uint256 amount) public view returns (uint256) {
        return _quote(body(nonce, msg.sender, to, amount));
    }

    function _send(address to, uint256 amount) internal returns (bytes32 messageId) {
        if (paused) revert IsPaused();
        require(amount > 0 && to != address(0), "send");
        uint256 n = nonce++;
        bytes memory b = body(n, msg.sender, to, amount);
        uint256 fee = _quote(b);
        if (msg.value < fee) revert Fee(fee);
        _take(msg.sender, amount);
        messageId = hook == address(0)
            ? mailbox.dispatch{value: fee}(remoteDomain, remote, b)
            : mailbox.dispatch{value: fee}(remoteDomain, remote, b, "", hook);
        emit Sent(n, msg.sender, to, amount, messageId);
        if (msg.value > fee) {
            (bool ok, ) = msg.sender.call{value: msg.value - fee}("");
            if (!ok) revert PayFailed();
        }
    }

    function _quote(bytes memory b) private view returns (uint256) {
        return hook == address(0) ? mailbox.quoteDispatch(remoteDomain, remote, b) : mailbox.quoteDispatch(remoteDomain, remote, b, "", hook);
    }

    // ---------------------------------------------------------------- receiving

    /// Called by the Mailbox after interchainSecurityModule verified the message.
    function handle(uint32 origin, bytes32 sender, bytes calldata b) external payable {
        if (msg.sender != address(mailbox)) revert NotMailbox();
        if (msg.value != 0) revert NoValue();
        if (origin != remoteDomain) revert WrongOrigin(origin);
        if (sender != remote) revert WrongSender(sender);
        if (b.length != BODY_LENGTH) revert BadBody();
        Body memory m = abi.decode(b, (Body));
        if (m.srcChainId != remoteChainId || bytes32(uint256(uint160(m.srcContract))) != remote) revert WrongSource();
        if (m.dstChainId != block.chainid || m.dstContract != address(this)) revert WrongDestination();
        if (m.originToken != originToken) revert WrongToken(m.originToken);
        if (m.to == address(0) || m.amount == 0) revert BadBody();
        bytes32 id = keccak256(b);
        if (pending[id].readyAt != 0) revert Replay(id);
        uint64 readyAt = uint64(block.timestamp) + delay;
        pending[id] = Pending(m.to, readyAt, false, false, m.amount);
        received += 1;
        emit Queued(id, m.srcNonce, m.sender, m.to, m.amount, readyAt);
    }

    /// Anyone: pays a queued message to its receiver once every check passes.
    function claim(bytes32 id) external nonReentrant {
        Pending storage p = pending[id];
        if (p.readyAt == 0) revert NoMessage();
        if (p.done) revert AlreadyDone();
        if (p.vetoed) revert IsVetoed();
        if (paused) revert IsPaused();
        if (block.timestamp < p.readyAt) revert NotReady(p.readyAt);
        uint64 today = uint64(block.timestamp / 1 days);
        if (day != today) { day = today; paidToday = 0; }
        uint256 amount = p.amount;
        if (paidToday + amount > dailyLimit) revert OverLimit(dailyLimit > paidToday ? dailyLimit - paidToday : 0);
        p.done = true;
        paidToday += amount;
        emit Paid(id, p.to, amount);
        _pay(p.to, amount);
    }

    /// What can still be paid out today.
    function remainingToday() external view returns (uint256) {
        uint256 used = day == uint64(block.timestamp / 1 days) ? paidToday : 0;
        return dailyLimit > used ? dailyLimit - used : 0;
    }

    // ---------------------------------------------------------------- guardians: only reduce risk, at once

    function pause() external onlyGuardian { paused = true; emit Paused(msg.sender); }

    /// Stops a queued payout that is not paid yet (during its delay, or while it waits for a limit).
    function veto(bytes32 id) external onlyGuardian {
        Pending storage p = pending[id];
        if (p.readyAt == 0) revert NoMessage();
        if (p.done) revert AlreadyDone();
        p.vetoed = true;
        emit Vetoed(id, msg.sender);
    }

    function lowerDailyLimit(uint256 v) external onlyGuardian {
        require(v < dailyLimit, "lower only");
        dailyLimit = v;
        emit DailyLimitSet(v);
    }

    function raiseDelay(uint64 d) external onlyGuardian {
        require(d > delay && d <= MAX_DELAY, "raise only");
        delay = d;
        emit DelaySet(d);
    }

    // ---------------------------------------------------------------- governance (a timelock)

    function unpause() external onlyGov { paused = false; emit Unpaused(); }

    function liftVeto(bytes32 id) external onlyGov {
        Pending storage p = pending[id];
        if (p.readyAt == 0) revert NoMessage();
        p.vetoed = false;
        emit VetoLifted(id);
    }

    function setDailyLimit(uint256 v) external onlyGov { dailyLimit = v; emit DailyLimitSet(v); }

    function setDelay(uint64 d) external onlyGov {
        require(d <= MAX_DELAY, "delay");
        delay = d;
        emit DelaySet(d);
    }

    /// A new ISM (e.g. more validators, a higher threshold). Never zero.
    function setInterchainSecurityModule(ISaphanTokenIsm ism) external onlyGov {
        require(address(ism) != address(0), "ism");
        interchainSecurityModule = ism;
        emit IsmSet(address(ism));
    }

    function setGuardian(address who, bool on) external onlyGov { guardian[who] = on; emit GuardianSet(who, on); }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "governance");
        governance = g;
        emit GovernanceSet(g);
    }
}

/// @title ZetaphyTokenVault: the ZETAPHY side of one token to one destination chain
/// @notice lock(to, amount) escrows `amount` of `originToken` (msg.value = quote(): the Mailbox fee) and sends a
///         mint to that destination's SaphanSyntheticToken. A release (a burn on the destination) is paid from this
///         vault only, after the delay, and never more than `locked` (everything locked here minus everything
///         released here): a compromise of one destination drains at most its own escrow, never another
///         destination's or another token's.
///         The token: any ERC-20 on ZETAPHY that governance adds (deploys a vault for), including the native coin
///         through its ERC-20 precompile (0xEeee…EEeE: approve, then lock). Refused: tokens that deliver less than
///         asked (fee-on-transfer: OddToken), that return false, or whose decimals() differ from the chain table's.
///         Not supported (governance must not add them): rebasing tokens, tokens with blocklists or admin
///         transfers (a vault's balance must only move through this contract). Transfers with no return value
///         (USDT style) are accepted.
///         Extra safety: `lockCap` bounds everything ever outstanding to this destination (and so the synthetic
///         supply that can exist); a ThreatRegistry (optional) holds a flagged sender (no lock) or receiver (the
///         release waits until the hold ends, as BridgeGuard's vaccine does).
contract ZetaphyTokenVault is SaphanTokenEndpoint {
    uint8 public immutable decimals;          // the token's, checked at deploy (the synthetic has the same)
    uint256 public locked;                    // backing: locked minus released
    uint256 public lockCap;                   // `locked` may never exceed this (governance raises, guardians lower)
    ISaphanTokenThreats public threats;       // zero: no hold check

    event LockCapSet(uint256 cap);
    event ThreatsSet(address registry);
    event ExcessRecovered(address indexed to, uint256 amount);

    error OddToken(uint256 received);
    error TransferFailed();
    error OverCap(uint256 cap);
    error OverBacking(uint256 locked);
    error Held(address who);

    /// `c.remote`: the destination's SaphanSyntheticToken; `c.originToken`: the token on ZETAPHY.
    constructor(Config memory c, uint8 decimals_, uint256 lockCap_, ISaphanTokenThreats threats_) SaphanTokenEndpoint(c) {
        address token_ = c.originToken;
        require(token_.code.length > 0 || token_ == 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE, "token");
        (bool ok, bytes memory ret) = token_.staticcall(abi.encodeWithSignature("decimals()"));
        require(ok && ret.length == 32 && abi.decode(ret, (uint256)) == decimals_, "decimals");
        decimals = decimals_;
        lockCap = lockCap_;
        threats = threats_;
        emit LockCapSet(lockCap_);
        emit ThreatsSet(address(threats_));
    }

    /// Escrows `amount` here and sends a mint of the same amount (same decimals) to `to` on the destination.
    function lock(address to, uint256 amount) external payable nonReentrant returns (bytes32 messageId) {
        messageId = _send(to, amount);
    }

    function _take(address from, uint256 amount) internal override {
        if (_held(from)) revert Held(from);
        if (locked + amount > lockCap) revert OverCap(lockCap);
        uint256 before = _balance();
        _call(abi.encodeWithSignature("transferFrom(address,address,uint256)", from, address(this), amount));
        uint256 got = _balance() - before;
        if (got != amount) revert OddToken(got);
        locked += amount;
    }

    function _pay(address to, uint256 amount) internal override {
        if (_held(to)) revert Held(to);
        if (amount > locked) revert OverBacking(locked);
        locked -= amount;
        _call(abi.encodeWithSignature("transfer(address,uint256)", to, amount));
    }

    function _balance() private view returns (uint256) {
        (bool ok, bytes memory ret) = originToken.staticcall(abi.encodeWithSignature("balanceOf(address)", address(this)));
        if (!ok || ret.length < 32) revert TransferFailed();
        return abi.decode(ret, (uint256));
    }

    /// A token call that must succeed and, if it returns anything, return true.
    function _call(bytes memory data) private {
        (bool ok, bytes memory ret) = originToken.call(data);
        if (!ok || (ret.length != 0 && (ret.length < 32 || !abi.decode(ret, (bool))))) revert TransferFailed();
    }

    function _held(address who) private view returns (bool h) {
        ISaphanTokenThreats t = threats;
        if (address(t) == address(0)) return false;
        (h, ) = t.isContractHeld(who);
    }

    function lowerLockCap(uint256 v) external onlyGuardian {
        require(v < lockCap, "lower only");
        lockCap = v;
        emit LockCapSet(v);
    }

    function setLockCap(uint256 v) external onlyGov { lockCap = v; emit LockCapSet(v); }

    function setThreats(ISaphanTokenThreats r) external onlyGov { threats = r; emit ThreatsSet(address(r)); }

    /// Tokens sent here without lock() are not backing; governance may send them on. Never touches `locked`.
    function recoverExcess(address to) external onlyGov nonReentrant {
        uint256 b = _balance();
        require(to != address(0) && b > locked, "no excess");
        _call(abi.encodeWithSignature("transfer(address,uint256)", to, b - locked));
        if (_balance() < locked) revert OverBacking(locked);
        emit ExcessRecovered(to, b - locked);
    }
}

/// @title SaphanSyntheticToken: a ZETAPHY token on one destination chain (e.g. zZETAPHY on Base Sepolia)
/// @notice An ERC-20 that exists only through its vault on ZETAPHY: minted only for messages from ZETAPHY's
///         domain and that vault (verified by a multisig ISM of OUR validators for origin ZETAPHY), after the mint
///         delay, within the daily mint limit and the supply cap, while not vetoed or paused. sendBack(to, amount)
///         burns the caller's tokens and sends the release to the vault (msg.value = quote()).
///         Its value is exactly the vault's safety: one synthetic is a claim on one token locked in
///         ZetaphyTokenVault(token, this chain); if that vault, our validators or ZETAPHY fail, it can be worth
///         less or nothing.
contract SaphanSyntheticToken is SaphanTokenEndpoint {
    string public name;
    string public symbol;
    uint8 public immutable decimals;          // the origin token's
    uint256 public totalSupply;
    uint256 public supplyCap;                 // totalSupply may never exceed this (governance raises, guardians lower)
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event SupplyCapSet(uint256 cap);

    error OverCap(uint256 cap);

    /// `c.remote`: the ZetaphyTokenVault on ZETAPHY (domain c.remoteDomain, chain c.remoteChainId).
    constructor(string memory name_, string memory symbol_, uint8 decimals_, Config memory c, uint256 supplyCap_) SaphanTokenEndpoint(c) {
        require(bytes(name_).length > 0 && bytes(symbol_).length > 0 && decimals_ <= 36, "token");
        name = name_;
        symbol = symbol_;
        decimals = decimals_;
        supplyCap = supplyCap_;
        emit SupplyCapSet(supplyCap_);
    }

    /// Burns `amount` of the caller's tokens and sends their release on ZETAPHY to `to`.
    function sendBack(address to, uint256 amount) external payable nonReentrant returns (bytes32 messageId) {
        messageId = _send(to, amount);
    }

    function _take(address from, uint256 amount) internal override {
        require(balanceOf[from] >= amount, "balance");
        balanceOf[from] -= amount;
        totalSupply -= amount;
        emit Transfer(from, address(0), amount);
    }

    function _pay(address to, uint256 amount) internal override {
        if (totalSupply + amount > supplyCap) revert OverCap(supplyCap);
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function approve(address s, uint256 v) external returns (bool) { allowance[msg.sender][s] = v; emit Approval(msg.sender, s, v); return true; }
    function transfer(address to, uint256 v) external returns (bool) { _move(msg.sender, to, v); return true; }
    function transferFrom(address f, address to, uint256 v) external returns (bool) {
        uint256 a = allowance[f][msg.sender];
        if (a != type(uint256).max) { require(a >= v, "allowance"); allowance[f][msg.sender] = a - v; }
        _move(f, to, v);
        return true;
    }
    function _move(address f, address to, uint256 v) private {
        require(to != address(0) && balanceOf[f] >= v, "transfer");
        balanceOf[f] -= v;
        balanceOf[to] += v;
        emit Transfer(f, to, v);
    }

    function lowerSupplyCap(uint256 v) external onlyGuardian {
        require(v < supplyCap, "lower only");
        supplyCap = v;
        emit SupplyCapSet(v);
    }

    function setSupplyCap(uint256 v) external onlyGov { supplyCap = v; emit SupplyCapSet(v); }
}

contracts/SimpleMultisig.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title SimpleMultisig: k-of-n owners for ZETAPHY admin roles (testnet)
/// @notice Holds governance of BridgeGuard / BridgeAirlock / StableGateway so
///         that no single key can change limits, prices or lanes. Any owner
///         proposes a call; it runs once `threshold` owners confirmed it.
///         Owners and the threshold change only through the multisig itself.
///         On mainnet prefer an audited Safe; this is small on purpose.
contract SimpleMultisig {
    struct Proposal {
        address to;
        uint256 value;
        bytes data;
        bool executed;
        uint8 confirmations;
    }

    address[] public owners;
    mapping(address => bool) public isOwner;
    uint8 public threshold;
    Proposal[] public proposals;
    mapping(uint256 => mapping(address => bool)) public confirmed;

    event Proposed(uint256 indexed id, address indexed by, address to, uint256 value);
    event Confirmed(uint256 indexed id, address indexed by);
    event Revoked(uint256 indexed id, address indexed by);
    event Executed(uint256 indexed id);

    error NotOwner();
    error BadConfig();
    error Done();
    error Twice();
    error NotEnough();
    error CallFailed(bytes reason);

    constructor(address[] memory owners_, uint8 threshold_) {
        _setOwners(owners_, threshold_);
    }

    receive() external payable {}

    modifier onlyOwner() { if (!isOwner[msg.sender]) revert NotOwner(); _; }

    function propose(address to, uint256 value, bytes calldata data) external onlyOwner returns (uint256 id) {
        id = proposals.length;
        proposals.push(Proposal(to, value, data, false, 0));
        emit Proposed(id, msg.sender, to, value);
        _confirm(id);
    }

    function confirm(uint256 id) external onlyOwner { _confirm(id); }

    function revoke(uint256 id) external onlyOwner {
        Proposal storage p = proposals[id];
        if (p.executed) revert Done();
        if (!confirmed[id][msg.sender]) revert NotEnough();
        confirmed[id][msg.sender] = false;
        p.confirmations -= 1;
        emit Revoked(id, msg.sender);
    }

    function execute(uint256 id) external onlyOwner returns (bytes memory) {
        Proposal storage p = proposals[id];
        if (p.executed) revert Done();
        if (p.confirmations < threshold) revert NotEnough();
        p.executed = true;
        (bool ok, bytes memory ret) = p.to.call{value: p.value}(p.data);
        if (!ok) revert CallFailed(ret);
        emit Executed(id);
        return ret;
    }

    /// Change owners / threshold: only as a proposal executed by the multisig.
    function setOwners(address[] calldata owners_, uint8 threshold_) external {
        if (msg.sender != address(this)) revert NotOwner();
        for (uint256 i = 0; i < owners.length; i++) isOwner[owners[i]] = false;
        _setOwners(owners_, threshold_);
    }

    function ownerCount() external view returns (uint256) { return owners.length; }
    function proposalCount() external view returns (uint256) { return proposals.length; }

    function _confirm(uint256 id) private {
        Proposal storage p = proposals[id];
        if (p.executed) revert Done();
        if (confirmed[id][msg.sender]) revert Twice();
        confirmed[id][msg.sender] = true;
        p.confirmations += 1;
        emit Confirmed(id, msg.sender);
    }

    function _setOwners(address[] memory owners_, uint8 threshold_) private {
        if (threshold_ < 2 || threshold_ > owners_.length || owners_.length > 20) revert BadConfig();
        delete owners;
        for (uint256 i = 0; i < owners_.length; i++) {
            address o = owners_[i];
            if (o == address(0) || isOwner[o]) revert BadConfig();
            isOwner[o] = true;
            owners.push(o);
        }
        threshold = threshold_;
    }
}

contracts/StableGateway.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IERC20Permit {
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function transfer(address to, uint256 value) external returns (bool);
    function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external;
}

interface INeuroJobs {
    function requestFor(address refundTo, bytes32 chain, string calldata target) external payable returns (uint256);
}

/// ZetaphyOracle's consumer surface: a USD price (18 decimals) or a revert.
interface IPriceOracle {
    function price(address asset) external view returns (uint256 value, uint256 updatedAt);
}

/// @title StableGateway: use the Neuro network paying only in a stablecoin
/// @notice A user who holds a stablecoin but no ZETAPHY signs a job request.
///         Anyone (a "relayer") submits it and pays the gas; in the same
///         transaction the gateway takes the user's stablecoin (the cost of
///         the ZETAPHY fee, plus the relayer's tip) and pays the job fee in
///         ZETAPHY from its own reserve.
///         Price: ZetaphyOracle.price(zetaAsset) (ZETAPHY in USD, guarded: TWAP of
///         the DEX, Pyth, deviation, staleness, circuit breaker), and for each
///         accepted stablecoin either its own oracle price or a $1 peg. When the
///         oracle has no valid price the request reverts (PriceUnavailable, with
///         the oracle's reason): never a silently wrong price.
///         TESTNET FALLBACK: a fixed price per token (stablecoin units per 1
///         ZETAPHY), used ONLY while governance switched testnetFixedPrices on
///         (TestnetFixedPricesSet event; priceSource() says so). It is not a
///         market price; it exists for testnet bring-up before the oracle has a
///         TWAP window, and is off by default.
///         Roles: the owner (the ZetaphyTimelock) sets everything and moves funds;
///         guardians (named by the owner) may pause requests at once.
contract StableGateway {
    INeuroJobs public immutable jobs;
    address public owner;
    mapping(address => bool) public guardian;
    bool public paused;

    IPriceOracle public oracle;
    /// The asset id of ZETAPHY in the oracle (the DEX's wrapped ZETAPHY).
    address public zetaAsset;

    struct TokenConfig {
        bool accepted;
        bool oraclePriced;   // false: counted as $1 (a USD stablecoin)
        uint8 decimals;
    }
    mapping(address => TokenConfig) public tokens;

    /// TESTNET ONLY: stablecoin base units per 1 ZETAPHY (1e18 wei), used only while testnetFixedPrices is on.
    bool public testnetFixedPrices;
    mapping(address => uint256) public testnetFixedPrice;
    mapping(address => uint256) public nonces;

    bytes32 public constant REQUEST_TYPEHASH = keccak256(
        "JobRequest(address user,address token,bytes32 chain,string target,uint256 fee,uint256 tip,uint256 maxCost,uint256 nonce,uint256 deadline)");
    uint256 private immutable _chainId;
    bytes32 private immutable _domain;

    struct JobRequest {
        address user;
        address token;
        bytes32 chain;
        string target;
        uint256 fee;      // ZETAPHY (wei) the job pays
        uint256 tip;      // stablecoin units to the relayer
        uint256 maxCost;  // the most stablecoin the user agrees to spend (cost + tip)
        uint256 nonce;
        uint256 deadline;
    }

    struct Permit { uint256 value; uint256 deadline; uint8 v; bytes32 r; bytes32 s; }

    event OracleSet(address oracle, address zetaAsset);
    event TokenSet(address indexed token, bool accepted, bool oraclePriced, uint8 decimals);
    event TestnetFixedPricesSet(bool on);
    event TestnetFixedPriceSet(address indexed token, uint256 pricePerZeta);
    event Paid(uint256 indexed jobId, address indexed user, address indexed token, uint256 cost, uint256 tip, address relayer);
    event OwnerChanged(address owner);
    event GuardianSet(address indexed who, bool on);
    event Paused(address indexed by);
    event Unpaused();

    error NotOwner();
    error NotGuardian();
    error GatewayPaused();
    error Expired();
    error BadNonce();
    error BadSignature();
    error NotAccepted();
    error TooExpensive();
    error ReserveLow();
    error NoPriceSource();
    error PriceUnavailable(bytes reason);

    constructor(INeuroJobs jobs_) {
        jobs = jobs_;
        owner = msg.sender;
        _chainId = block.chainid;
        _domain = _buildDomain();
    }

    receive() external payable {} // ZETAPHY reserve top-up

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    function setOwner(address o) external onlyOwner {
        owner = o;
        emit OwnerChanged(o);
    }

    function setGuardian(address who, bool on) external onlyOwner {
        guardian[who] = on;
        emit GuardianSet(who, on);
    }

    /// A guardian (or the owner) stops new requests at once; only the owner restarts them.
    function pause() external {
        if (!guardian[msg.sender] && msg.sender != owner) revert NotGuardian();
        paused = true;
        emit Paused(msg.sender);
    }

    function unpause() external onlyOwner {
        paused = false;
        emit Unpaused();
    }

    function setOracle(IPriceOracle o, address zetaAsset_) external onlyOwner {
        oracle = o;
        zetaAsset = zetaAsset_;
        emit OracleSet(address(o), zetaAsset_);
    }

    /// Accept (or stop accepting) a stablecoin; oraclePriced: its own oracle price, else $1.
    function setToken(address token, bool accepted, bool oraclePriced, uint8 decimals) external onlyOwner {
        require(decimals <= 30, "decimals");
        tokens[token] = TokenConfig(accepted, oraclePriced, decimals);
        emit TokenSet(token, accepted, oraclePriced, decimals);
    }

    /// TESTNET ONLY: switch the fixed prices on (they replace the oracle) or off.
    function setTestnetFixedPrices(bool on) external onlyOwner {
        testnetFixedPrices = on;
        emit TestnetFixedPricesSet(on);
    }

    /// TESTNET ONLY: stablecoin units per 1 ZETAPHY, used only while testnetFixedPrices is on.
    function setTestnetFixedPrice(address token, uint256 price) external onlyOwner {
        testnetFixedPrice[token] = price;
        emit TestnetFixedPriceSet(token, price);
    }

    /// Stablecoin proceeds go to the treasury the operator names.
    function sweep(address token, address to, uint256 amount) external onlyOwner {
        require(IERC20Permit(token).transfer(to, amount), "transfer failed");
    }

    function withdrawReserve(address payable to, uint256 amount) external onlyOwner {
        (bool ok,) = to.call{value: amount}("");
        require(ok, "transfer failed");
    }

    /// Where quote() takes its price from.
    function priceSource() external view returns (string memory) {
        if (testnetFixedPrices) return "TESTNET FIXED PRICE (set by governance, not a market price)";
        if (address(oracle) == address(0)) return "none";
        return "ZetaphyOracle";
    }

    /// Stablecoin cost of a job fee, rounded up.
    function quote(address token, uint256 fee) public view returns (uint256) {
        TokenConfig memory t = tokens[token];
        if (!t.accepted) revert NotAccepted();
        if (testnetFixedPrices) {
            uint256 p = testnetFixedPrice[token];
            if (p == 0) revert NotAccepted();
            return (fee * p + 1e18 - 1) / 1e18;
        }
        if (address(oracle) == address(0)) revert NoPriceSource();
        uint256 zetaUsd = _price(zetaAsset);
        uint256 tokenUsd = t.oraclePriced ? _price(token) : 1e18;
        // fee (18 decimals) x ZETAPHY's USD price / the token's USD price, in the token's units, rounded up
        uint256 usd = fee * zetaUsd;                       // USD x 1e36
        uint256 den = tokenUsd * 1e18;
        return (usd * (10 ** uint256(t.decimals)) + den - 1) / den;
    }

    function _price(address asset) private view returns (uint256 v) {
        try oracle.price(asset) returns (uint256 value, uint256) { v = value; } catch (bytes memory reason) { revert PriceUnavailable(reason); }
        if (v == 0) revert PriceUnavailable("");
    }

    function DOMAIN_SEPARATOR() public view returns (bytes32) {
        return block.chainid == _chainId ? _domain : _buildDomain();
    }

    function hashRequest(JobRequest calldata q) public view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR(), keccak256(abi.encode(
            REQUEST_TYPEHASH, q.user, q.token, q.chain, keccak256(bytes(q.target)), q.fee, q.tip, q.maxCost, q.nonce, q.deadline))));
    }

    /// The user already approved this gateway for the stablecoin.
    function request(JobRequest calldata q, bytes calldata sig) external returns (uint256) {
        return _request(q, sig);
    }

    /// Same, with an EIP-2612 permit so the user needs no approve transaction (no gas at all).
    function requestWithPermit(JobRequest calldata q, bytes calldata sig, Permit calldata p) external returns (uint256) {
        // A failed permit is fine if an allowance already exists (e.g. someone front-ran the permit).
        try IERC20Permit(q.token).permit(q.user, address(this), p.value, p.deadline, p.v, p.r, p.s) {} catch {}
        return _request(q, sig);
    }

    function _request(JobRequest calldata q, bytes calldata sig) private returns (uint256 jobId) {
        if (paused) revert GatewayPaused();
        if (block.timestamp > q.deadline) revert Expired();
        if (q.nonce != nonces[q.user]) revert BadNonce();
        if (_recover(hashRequest(q), sig) != q.user) revert BadSignature();
        nonces[q.user] = q.nonce + 1;

        uint256 cost = quote(q.token, q.fee);
        if (cost + q.tip > q.maxCost) revert TooExpensive();
        if (address(this).balance < q.fee) revert ReserveLow();

        require(IERC20Permit(q.token).transferFrom(q.user, address(this), cost), "payment failed");
        if (q.tip > 0) require(IERC20Permit(q.token).transferFrom(q.user, msg.sender, q.tip), "tip failed");
        jobId = jobs.requestFor{value: q.fee}(q.user, q.chain, q.target);
        emit Paid(jobId, q.user, q.token, cost, q.tip, msg.sender);
    }

    function _recover(bytes32 digest, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) revert BadSignature();
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) revert BadSignature();
        address a = ecrecover(digest, v, r, s);
        if (a == address(0)) revert BadSignature();
        return a;
    }

    function _buildDomain() private view returns (bytes32) {
        return keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256(bytes("ZETAPHY StableGateway")), keccak256(bytes("1")), block.chainid, address(this)));
    }
}

contracts/TestStable.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title TestStable: testnet-only stand-in for USDC / USDT on ZETAPHY testnet
/// @notice Worthless by design. Anyone can take 1,000 from the faucet once a
///         day. Real USDC arrives only through the bridge in stage 3.
///         ERC-20 + EIP-2612 permit, 6 decimals like USDC/USDT.
contract TestStable {
    string public name;
    string public symbol;
    uint8 public constant decimals = 6;
    uint256 public constant FAUCET_AMOUNT = 1_000 * 10 ** 6;
    uint256 public constant FAUCET_EVERY = 1 days;

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => uint256) public nonces;
    mapping(address => uint256) public lastFaucet;

    bytes32 public constant PERMIT_TYPEHASH =
        keccak256("Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)");
    uint256 private immutable _chainId;
    bytes32 private immutable _domain;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(string memory name_, string memory symbol_) {
        name = name_;
        symbol = symbol_;
        _chainId = block.chainid;
        _domain = _buildDomain();
    }

    function faucet() external {
        _drip(msg.sender);
    }

    /// Lets a relay pay the gas for someone who has no ZETAPHY yet.
    function faucetTo(address to) external {
        _drip(to);
    }

    function _drip(address to) private {
        require(to != address(0), "to zero");
        require(block.timestamp >= lastFaucet[to] + FAUCET_EVERY, "faucet: once a day");
        lastFaucet[to] = block.timestamp;
        totalSupply += FAUCET_AMOUNT;
        balanceOf[to] += FAUCET_AMOUNT;
        emit Transfer(address(0), to, FAUCET_AMOUNT);
    }

    function DOMAIN_SEPARATOR() public view returns (bytes32) {
        return block.chainid == _chainId ? _domain : _buildDomain();
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transfer(address to, uint256 value) external returns (bool) {
        _move(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        uint256 a = allowance[from][msg.sender];
        if (a != type(uint256).max) {
            require(a >= value, "allowance");
            allowance[from][msg.sender] = a - value;
        }
        _move(from, to, value);
        return true;
    }

    function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external {
        require(block.timestamp <= deadline, "permit: expired");
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR(),
            keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, value, nonces[owner]++, deadline))));
        require(uint256(s) <= 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0, "permit: bad s");
        address signer = ecrecover(digest, v, r, s);
        require(signer != address(0) && signer == owner, "permit: bad signature");
        allowance[owner][spender] = value;
        emit Approval(owner, spender, value);
    }

    function _move(address from, address to, uint256 value) private {
        require(to != address(0), "to zero");
        uint256 b = balanceOf[from];
        require(b >= value, "balance");
        unchecked { balanceOf[from] = b - value; }
        balanceOf[to] += value;
        emit Transfer(from, to, value);
    }

    function _buildDomain() private view returns (bytes32) {
        return keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256(bytes(name)), keccak256(bytes("1")), block.chainid, address(this)));
    }
}

contracts/ThreatRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

/// The parts of NeuroIdentity (ERC-8004 identity registry) this registry reads:
/// who has claimed the identity of a target ("eip155:<id>:0x<lowercase hex>").
interface IIdentityOwners {
    function agentOfTarget(bytes32 caip10Hash) external view returns (uint256);
    function ownerOf(uint256 agentId) external view returns (address);
}

/// @title ThreatRegistry: Neuro's immune system (stage 4)
/// @notice A flag here states a reproducible fact about code, not guilt: what
///         the code can do, or did in a reproducible test (Reason), with the
///         evidence that shows it (a Neuro reportHash or the hash of another
///         reproducible report, plus a short URI). Active, bonded NeuroJobs
///         runners with a track record vote to flag a key. At QUORUM distinct
///         votes the key is flagged, and every Neuro instance that reads this
///         registry warns about it, on every chain. A flag is cleared the same
///         way (QUORUM votes to clear).
///
///         Keys:
///           - a code fingerprint (Neuro's fp1: sha256 of the code with
///             addresses/immutables masked), so every copy of the code is found
///           - codeKey(h):         EVM code with extcodehash h on ZETAPHY
///           - addressKey(id, a):  address a on the chain with EVM id `id`
///         voteBatch lets a runner vote on a fingerprint together with the code
///         hashes and addresses it found for it, in one tx (one evidence for the
///         batch); each key still needs its own quorum. BridgeAirlock / BridgeGuard
///         hold (and, once enforced, refuse) flagged sources and recipients, and
///         the ZETAPHY wallet refuses to sign calls to code with an enforced flag.
///
///         Evidence: every flag vote carries one (reportHash != 0, uri at most
///         MAX_URI bytes); every vote's evidence is in its Voted event, and the
///         evidence of the round's first flag vote (the one whose reason the flag
///         shows) is stored: evidenceOf(key).
///
///         Right of reply: the parties behind a key may post responses (at most
///         MAX_RESPONSE bytes each) that wallets show next to the flag, each with
///         its author's address. Responses are kept per (key, author): an author
///         changes or removes (empty text) only its own, never another's; at most
///         MAX_RESPONSES per key (a new author past that replaces the oldest one,
///         never the governance-assigned responder's). responseAt(key, i) lists
///         them: the governance-assigned responder's first, then newest first;
///         responseOf(key) is responseAt(key, 0).
///         Who may answer for a key (respond / appeal, `mayAnswer`):
///           - addressKey(block.chainid, a) for an address a on ZETAPHY: a itself or,
///             for a contract, its current owner();
///           - addressKey(id, a) on any EVM chain (and on ZETAPHY): the owner of
///             the claimed ERC-8004 identity of "eip155:<id>:<a>" in NeuroIdentity
///             (optional: `identity`, zero = off);
///           - codeKey(h) and fp1 keys: ONLY the responder governance assigned to
///             the key (`responder`). Anyone can deploy a contract with the same
///             code and an owner() of their choosing, so code and fingerprint keys
///             have no on-chain owner to ask;
///           - any key: once governance assigned a responder, only it may answer
///             for that key (setResponder(key, 0) gives address keys back to the
///             routes above). Others' existing responses stay until their authors
///             remove them.
///         A response never changes the flag.
///
///         Appeal: whoever may answer for a flagged key (mayAnswer: so for code and
///         fp1 keys only their assigned responder) may appeal(key), paying
///         `appealBond` (appeals are off until governance sets a community fund).
///         That opens an appeal round, voted with voteAppeal, by runners who
///         neither voted for the flag nor backed it (voted/backed of the round that
///         set it, `flagRound`): fresh eyes. The appellant cannot vote in it.
///           - QUORUM appeal votes to clear: the flag is cleared, the bond is
///             refunded, and each runner who set the flag gets a strike
///             (`strikes`, a public record only: see below).
///           - QUORUM appeal votes to keep: the flag stands; the bond goes to the
///             community fund (not to the voters, so reviewers gain nothing by
///             keeping a flag).
///           - Neither within `appealWindow`: anyone may expireAppeal; the bond is
///             refunded (nobody reviewed it: not the appellant's fault).
///           - The flag cleared otherwise meanwhile (the normal clear vote,
///             governance protecting the key): the bond is refunded.
///         Funds are never pushed inside these calls: refunds are credited
///         (`owed`, taken with withdraw) and the fund's share with payFund, so
///         a failing receiver cannot block a vote. payFund pays the last non-zero
///         community fund governance set (`fundPayee`), so turning appeals off
///         (fund = 0) never sends kept bonds to address(0). Strikes slash nothing: the
///         runners' bonds are in NeuroJobs, and an automatic penalty would let a
///         colluding appeal quorum silence honest runners; governance and the
///         runners' tools can read them.
///
///         Checks on the runners (a small quorum must not freeze bridges or wallets):
///           - Warning, hold and enforcement. isFlagged / is*Flagged answer at
///             once (Neuro warns, the wallet shows a warning). is*Held answer true
///             once a flag is `holdDelay` old (a governance knob, e.g. 10 minutes,
///             below enforceDelay), or at once when it is fast (below) or a guardian
///             or governance called holdNow(key). Things that only HOLD (reversible:
///             BridgeAirlock's release, BridgeGuard's inbound queue and outbound)
///             read those, so two runners alone cannot freeze anyone's bridging
///             at once: governance and guardians get holdDelay to look. is*Enforced
///             answer true only once a flag is `enforceDelay` old; everything that
///             REFUSES (BridgeAirlock's ThreatFlagged, NeuroLane watchers, the
///             wallet's refusal) reads those.
///             What ends a hold: the flag cleared (QUORUM clear votes, or an upheld
///             appeal) or governance protecting the key. Nothing else does: a
///             source-chain LockBox has no refund path, so a held transfer waits
///             in BridgeAirlock (and a held mint in BridgeGuard's queue) until then.
///           - Fast lane. A flag is enforced at once (no enforceDelay) when
///             `fastQuorum` distinct runners stand behind it (a supermajority,
///             governance's knob, default 2 x quorum; runners can still add
///             their vote to a flag that is already standing), or when
///             governance or a guardian calls enforceNow(key) (which holds at once
///             too). Clearing (same quorum) or protecting the key lifts it as before.
///           - Protected keys. Governance (the chain's gov module through
///             MsgEVMCall, or a multisig) can protect keys, e.g. the bridge's
///             own contracts and code hashes or a common token's code. A
///             protected key cannot be flagged; protecting a flagged key clears it.
contract ThreatRegistry {
    IRunners public immutable runners;
    uint8 public immutable quorum;
    uint32 public immutable minAgreed; // verdicts a runner must have had accepted to vote

    /// What the code does, or did in a reproducible test. Never a claim about intent.
    enum Reason {
        None,
        CannotSellInSimulation,   // a simulated buy worked, the sell failed or returned almost nothing
        UnlimitedMint,            // an address can mint new tokens without a cap
        OwnerCanBlockTransfers,   // an owner/admin can stop holders from transferring or selling
        OwnerCanMoveHolderFunds,  // an owner/admin can move or burn tokens or funds held by others
        SameNameAsKnownToken,     // same name/symbol as a known token, at a different address
        SweepsApprovedTokens,     // in a test, moved tokens approved to it to an address the holder did not choose
        Other                     // another code fact: see the evidence
    }

    struct Entry {
        bool flagged;
        Reason reason;
        uint64 updatedAt;
        uint32 round;        // bumps on every flag/clear so old votes stop counting
        uint8 votes;
        bool fast;           // enforced at once (fastQuorum or enforceNow)
        uint8 support;       // distinct runners behind the standing flag
        uint64 fastAt;       // when it went fast
    }

    struct Evidence {
        bytes32 reportHash;  // Neuro reportHash, or the hash of another reproducible report
        address by;          // the runner who gave it
        uint64 at;
        string uri;          // where the report can be read (at most MAX_URI bytes)
    }

    struct Response {
        address by;
        uint64 at;
        uint256 chainId;     // the subject answered for (0: a governance-assigned responder)
        address account;
        string text;         // at most MAX_RESPONSE bytes
    }

    struct Appeal {
        address appellant;   // zero: no appeal open
        uint64 openedAt;
        uint32 flagRound;    // the round that set the flag: its voters and backers may not vote
        uint8 clearVotes;
        uint8 keepVotes;
        uint128 bond;
    }

    bytes16 private constant HEX = "0123456789abcdef";
    uint256 public constant MAX_URI = 200;
    uint256 public constant MAX_RESPONSE = 500;
    uint256 public constant MAX_RESPONSES = 8;     // per key
    uint256 public constant MAX_APPEAL_BOND = 1000 ether;
    uint64 public constant MIN_APPEAL_WINDOW = 1 days;
    uint64 public constant MAX_APPEAL_WINDOW = 90 days;

    mapping(bytes32 => Entry) public entries;
    mapping(bytes32 => mapping(uint32 => mapping(address => bool))) public voted;
    /// Runners who backed a standing flag after it was set (fast lane); kept apart
    /// from `voted`, which stays exactly the quorum that set it (ThreatReports pays those).
    mapping(bytes32 => mapping(uint32 => mapping(address => bool))) public backed;
    bytes32[] public flaggedList;
    mapping(bytes32 => Evidence) private _evidence;
    /// Flag voters per round (at most quorum each): the runners an upheld appeal strikes.
    mapping(bytes32 => mapping(uint32 => address[])) private _flaggers;

    /// The chain's gov module (MsgEVMCall) or a multisig.
    address public governance;
    /// Seconds a flag waits before the is*Enforced views (which block) report it.
    uint64 public enforceDelay;
    uint64 public constant MAX_ENFORCE_DELAY = 30 days;
    /// Keys governance vouched for: never flagged.
    mapping(bytes32 => bool) public protectedKey;
    /// Distinct flag votes that enforce a standing flag at once (0: off).
    uint8 public fastQuorum;
    /// Guardians (set by governance) may enforceNow / holdNow; they cannot flag, clear or protect.
    mapping(address => bool) public guardian;
    /// Seconds a flag waits before the is*Held views (which hold bridging) report it.
    uint64 public holdDelay;
    /// A guardian's (or governance's) holdNow: the flag's round it holds at once, and when.
    struct HoldNow { uint32 round; uint64 at; }
    mapping(bytes32 => HoldNow) public heldNow;

    // ---- right of reply and appeal ----
    IIdentityOwners public identity;               // zero: the identity route is off
    mapping(bytes32 => address) public responder;  // governance-assigned; exclusive once set
    mapping(bytes32 => mapping(address => Response)) private _responses; // per (key, author)
    mapping(bytes32 => address[]) private _authors;                      // authors with a response, least recently updated first
    uint128 public appealBond;
    uint64 public appealWindow = 14 days;
    address public communityFund;                  // zero: appeals off
    address public fundPayee;                      // the last non-zero communityFund: where payFund sends
    mapping(bytes32 => Appeal) public appeals;
    mapping(bytes32 => uint32) public appealCount; // appeal ids per key, from 1
    mapping(bytes32 => mapping(uint32 => mapping(address => bool))) public appealVoted;
    mapping(address => uint32) public strikes;
    mapping(address => uint256) public owed;       // refunds, taken with withdraw()
    uint256 public fundOwed;                       // the community fund's share, sent with payFund()

    event Voted(bytes32 indexed fingerprint, address indexed runner, bool flag, Reason reason, bytes32 reportHash, string uri);
    event Flagged(bytes32 indexed fingerprint, Reason reason);
    event Cleared(bytes32 indexed fingerprint);
    event Protected(bytes32 indexed key, bool on);
    event EnforceDelaySet(uint64 delay);
    event GovernanceSet(address governance);
    event Supported(bytes32 indexed key, address indexed runner, uint8 support, bytes32 reportHash);
    event FastEnforced(bytes32 indexed key, address indexed by);
    event FastQuorumSet(uint8 fastQuorum);
    event GuardianSet(address indexed who, bool on);
    event Responded(bytes32 indexed key, address indexed by, uint256 chainId, address account, string text);
    event ResponderSet(bytes32 indexed key, address responder);
    event IdentitySet(address identity);
    event AppealsSet(uint128 bond, uint64 window, address fund);
    event Appealed(bytes32 indexed key, uint32 indexed id, address indexed appellant, uint128 bond);
    event AppealVoted(bytes32 indexed key, uint32 indexed id, address indexed runner, bool clear, bytes32 reportHash, string uri);
    event AppealClosed(bytes32 indexed key, uint32 indexed id, uint8 outcome); // 1 cleared, 2 kept, 3 expired, 4 flag cleared otherwise
    event Struck(address indexed runner, bytes32 indexed key, uint32 strikes);
    event Paid(address indexed to, uint256 amount);
    event HoldDelaySet(uint64 delay);
    event HeldNow(bytes32 indexed key, address indexed by);

    error NotRunner();
    error AlreadyVoted();
    error NoChange();
    error NotGovernance();
    error ProtectedKey(bytes32 key);
    error NotGuardian();
    error NotFlagged();
    error NoEvidence();
    error TooLong();
    error NotResponder();
    error AppealsOff();
    error BadBond(uint256 bond);
    error AppealOpen();
    error NoAppeal();
    error AppealExpired();
    error NotYet();
    error NotFresh();
    error PayFailed();
    error NoFund();

    constructor(IRunners runners_, uint8 quorum_, uint32 minAgreed_, address governance_, uint64 enforceDelay_) {
        require(quorum_ >= 2, "quorum");
        require(governance_ != address(0), "governance");
        require(enforceDelay_ <= MAX_ENFORCE_DELAY, "delay");
        runners = runners_;
        quorum = quorum_;
        minAgreed = minAgreed_;
        governance = governance_;
        enforceDelay = enforceDelay_;
        fastQuorum = quorum_ > 127 ? 255 : quorum_ * 2;
        holdDelay = enforceDelay_ >= 20 minutes ? 10 minutes : enforceDelay_ / 2;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "governance");
        governance = g;
        emit GovernanceSet(g);
    }

    /// Applies to flags already standing too (they are measured from when they were set).
    function setEnforceDelay(uint64 d) external onlyGov {
        require(d <= MAX_ENFORCE_DELAY, "delay");
        require(holdDelay == 0 || d > holdDelay, "holdDelay"); // holds start before enforcement
        enforceDelay = d;
        emit EnforceDelaySet(d);
    }

    /// Seconds before a flag holds bridging (is*Held), unless fast or held now.
    /// Below enforceDelay (or 0: a flag holds at once). Applies to standing flags too.
    function setHoldDelay(uint64 d) external onlyGov {
        require(d == 0 || d < enforceDelay, "holdDelay");
        holdDelay = d;
        emit HoldDelaySet(d);
    }

    /// Fast lane: this many distinct runners behind a flag enforce it at once.
    /// Above quorum (a supermajority), or 0 to turn the fast lane off.
    function setFastQuorum(uint8 f) external onlyGov {
        require(f == 0 || f > quorum, "fastQuorum");
        fastQuorum = f;
        emit FastQuorumSet(f);
    }

    function setGuardian(address who, bool on) external onlyGov {
        guardian[who] = on;
        emit GuardianSet(who, on);
    }

    /// NeuroIdentity, for the identity route of the right of reply (zero: off).
    function setIdentity(IIdentityOwners i) external onlyGov {
        identity = i;
        emit IdentitySet(address(i));
    }

    /// The only party that may answer for `key` (zero: the on-chain routes again).
    function setResponder(bytes32 key, address who) external onlyGov {
        responder[key] = who;
        emit ResponderSet(key, who);
    }

    /// Appeal bond, window and the community fund that keeps bonds of appeals
    /// that confirmed the flag. A zero fund turns appeals off (open ones still
    /// close normally); a new bond applies to new appeals only.
    function setAppeals(uint128 bond, uint64 window, address fund) external onlyGov {
        require(bond <= MAX_APPEAL_BOND, "bond");
        require(window >= MIN_APPEAL_WINDOW && window <= MAX_APPEAL_WINDOW, "window");
        appealBond = bond;
        appealWindow = window;
        communityFund = fund;
        if (fund != address(0)) fundPayee = fund;
        emit AppealsSet(bond, window, fund);
    }

    /// Governance or a guardian enforces a standing flag at once (money moving
    /// now). Only a flag the runners' quorum already set; protected keys can
    /// never be flagged, so never enforced either.
    function enforceNow(bytes32 key) external {
        if (msg.sender != governance && !guardian[msg.sender]) revert NotGuardian();
        Entry storage e = entries[key];
        if (!e.flagged) revert NotFlagged();
        if (e.fast) revert NoChange();
        _fast(e, key);
    }

    /// Governance or a guardian holds a standing flag at once (no holdDelay):
    /// bridging of its party stops now, as reversible as any hold. Only a flag
    /// the runners' quorum already set; it ends with the flag (clear / protect).
    function holdNow(bytes32 key) external {
        if (msg.sender != governance && !guardian[msg.sender]) revert NotGuardian();
        Entry storage e = entries[key];
        if (!e.flagged) revert NotFlagged();
        if (e.fast || heldNow[key].round == e.round) revert NoChange();
        heldNow[key] = HoldNow(e.round, uint64(block.timestamp));
        emit HeldNow(key, msg.sender);
    }

    function _fast(Entry storage e, bytes32 key) private {
        e.fast = true;
        e.fastAt = uint64(block.timestamp);
        emit FastEnforced(key, msg.sender);
    }

    /// Protect (or unprotect) keys. Protecting clears a flag at once and drops
    /// any votes in progress; unprotecting does not flag anything back.
    function setProtected(bytes32[] calldata keys, bool on) external onlyGov {
        for (uint256 i = 0; i < keys.length; i++) {
            bytes32 k = keys[i];
            protectedKey[k] = on;
            emit Protected(k, on);
            if (!on) continue;
            Entry storage e = entries[k];
            if (e.flagged || e.votes != 0) {
                bool was = e.flagged;
                _reset(e, k);
                e.round += 1;
                e.updatedAt = uint64(block.timestamp);
                if (was) emit Cleared(k);
            }
        }
    }

    /// keccak256 of empty code: every account without code has it, so it is never a threat.
    bytes32 public constant EMPTY_CODEHASH = 0xc5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470;

    /// The key under which EVM code with this extcodehash is flagged.
    function codeKey(bytes32 codeHash) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.threat.code", codeHash));
    }

    /// The key under which an address on a given chain (EVM chain id) is flagged.
    function addressKey(uint256 chainId, address who) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.threat.address", chainId, who));
    }

    function _checkRunner() private view {
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed) revert NotRunner();
    }

    function _checkEvidence(bool required, bytes32 reportHash, string calldata uri) private pure {
        if (required && reportHash == bytes32(0)) revert NoEvidence();
        if (bytes(uri).length > MAX_URI) revert TooLong();
    }

    /// Vote to flag (flag = true, with a reason and its evidence) or to clear
    /// (flag = false; evidence optional). `fingerprint` is any key: a fp1
    /// fingerprint, codeKey(..) or addressKey(..).
    function vote(bytes32 fingerprint, bool flag, Reason reason, bytes32 reportHash, string calldata uri) external {
        _checkRunner();
        _checkEvidence(flag, reportHash, uri);
        if (flag && protectedKey[fingerprint]) revert ProtectedKey(fingerprint);
        if (!_vote(fingerprint, flag, reason, reportHash, uri)) revert NoChange();
    }

    /// One runner's votes on several keys at once, e.g. a fingerprint plus the
    /// code hashes and addresses of its copies, with one evidence for the batch.
    /// Keys already in that state, or already voted on by this runner this
    /// round, are skipped (not an error), so the same list can be sent again as
    /// copies are found. Protected keys are skipped when flagging. On a key
    /// already flagged, a flag vote adds this runner's support (toward
    /// fastQuorum) once.
    function voteBatch(bytes32[] calldata keys, bool flag, Reason reason, bytes32 reportHash, string calldata uri) external returns (uint256 counted) {
        _checkRunner();
        _checkEvidence(flag, reportHash, uri);
        if (flag && reason == Reason.None) revert NoChange();
        for (uint256 i = 0; i < keys.length; i++) {
            bytes32 k = keys[i];
            Entry storage e = entries[k];
            if (flag && protectedKey[k]) continue;
            if (flag && e.flagged) { if (_support(e, k, reportHash)) counted++; continue; }
            if (e.flagged == flag || voted[k][e.round][msg.sender]) continue;
            _vote(k, flag, reason, reportHash, uri);
            counted++;
        }
        if (counted == 0) revert NoChange();
    }

    /// A flag vote on a standing flag: one more runner behind it (once per
    /// runner, counting the quorum that set it). False when nothing changed.
    function _support(Entry storage e, bytes32 key, bytes32 reportHash) private returns (bool) {
        if (e.fast || e.support == type(uint8).max) return false;
        uint32 r = e.round - 1; // the round that set the flag
        if (voted[key][r][msg.sender] || backed[key][r][msg.sender]) return false;
        backed[key][r][msg.sender] = true;
        e.support += 1;
        emit Supported(key, msg.sender, e.support, reportHash);
        if (fastQuorum != 0 && e.support >= fastQuorum) _fast(e, key);
        return true;
    }

    /// The flag (or the votes in progress) is gone: an open appeal ends with its bond refunded.
    function _reset(Entry storage e, bytes32 key) private {
        e.flagged = false;
        e.reason = Reason.None;
        e.votes = 0;
        e.fast = false;
        e.support = 0;
        e.fastAt = 0;
        delete _evidence[key];
        if (appeals[key].appellant != address(0)) _closeAppeal(key, 4);
    }

    function _vote(bytes32 fingerprint, bool flag, Reason reason, bytes32 reportHash, string calldata uri) private returns (bool) {
        Entry storage e = entries[fingerprint];
        if (flag && reason == Reason.None) return false;
        if (flag && e.flagged) {
            if (voted[fingerprint][e.round - 1][msg.sender] || backed[fingerprint][e.round - 1][msg.sender]) revert AlreadyVoted();
            return _support(e, fingerprint, reportHash);
        }
        if (e.flagged == flag) return false;
        if (voted[fingerprint][e.round][msg.sender]) revert AlreadyVoted();
        voted[fingerprint][e.round][msg.sender] = true;
        e.votes += 1;
        if (flag) {
            _flaggers[fingerprint][e.round].push(msg.sender);
            if (e.reason == Reason.None) { // the round's first flag vote: its reason and evidence are what the flag shows
                e.reason = reason;
                _evidence[fingerprint] = Evidence(reportHash, msg.sender, uint64(block.timestamp), uri);
            }
        }
        emit Voted(fingerprint, msg.sender, flag, reason, reportHash, uri);
        if (e.votes >= quorum) {
            e.round += 1;
            e.updatedAt = uint64(block.timestamp);
            if (flag) {
                e.flagged = true;
                e.support = e.votes;
                e.votes = 0;
                flaggedList.push(fingerprint);
                emit Flagged(fingerprint, e.reason);
                if (fastQuorum != 0 && e.support >= fastQuorum) _fast(e, fingerprint);
            } else {
                _reset(e, fingerprint);
                emit Cleared(fingerprint);
            }
        }
        return true;
    }

    // ---- right of reply ----

    /// "eip155:<chainId>:0x<lowercase hex>", NeuroIdentity's spelling of an EVM target.
    function _caip10(uint256 chainId, address a) private pure returns (bytes memory out) {
        bytes memory digits = new bytes(78);
        uint256 n = 78;
        uint256 v = chainId;
        do { digits[--n] = bytes1(uint8(48 + v % 10)); v /= 10; } while (v != 0);
        bytes memory id = new bytes(78 - n);
        for (uint256 i = 0; i < id.length; i++) id[i] = digits[n + i];
        bytes memory hexa = new bytes(40);
        uint160 x = uint160(a);
        for (uint256 i = 40; i > 0; i--) { hexa[i - 1] = HEX[x & 15]; x >>= 4; }
        out = abi.encodePacked("eip155:", id, ":0x", hexa);
    }

    /// The claimed owner of the identity of `account` on chain `chainId` (zero: none, unclaimed or off).
    function _identityOwner(uint256 chainId, address account) private view returns (address) {
        IIdentityOwners idr = identity;
        if (address(idr) == address(0)) return address(0);
        try idr.agentOfTarget(keccak256(_caip10(chainId, account))) returns (uint256 agentId) {
            if (agentId == 0) return address(0);
            try idr.ownerOf(agentId) returns (address o) { return o == address(idr) ? address(0) : o; } catch { return address(0); }
        } catch { return address(0); }
    }

    /// The `owner()` of a contract on this chain (zero: none).
    function _ownerOf(address a) private view returns (address) {
        if (a.code.length == 0) return address(0);
        (bool ok, bytes memory r) = a.staticcall{gas: 50_000}(abi.encodeWithSignature("owner()"));
        if (!ok || r.length < 32) return address(0);
        uint256 w = abi.decode(r, (uint256));
        return w >> 160 == 0 ? address(uint160(w)) : address(0);
    }

    /// May `who` answer for `key` as the party behind (chainId, account)? (See the notice.)
    /// Code keys and fp1 keys: only their governance-assigned responder.
    function mayAnswer(bytes32 key, uint256 chainId, address account, address who) public view returns (bool) {
        address r = responder[key];
        if (r != address(0) || chainId == 0) return r != address(0) && who == r;
        if (who == address(0) || key != addressKey(chainId, account)) return false;
        if (chainId == block.chainid && (who == account || who == _ownerOf(account))) return true;
        return who == _identityOwner(chainId, account);
    }

    /// Post or replace msg.sender's own response to the flag on `key`, as the
    /// party behind (chainId, account) (see the notice). Empty text removes
    /// msg.sender's own response (always allowed to its author). Never changes the flag.
    function respond(bytes32 key, uint256 chainId, address account, string calldata text) external {
        if (bytes(text).length > MAX_RESPONSE) revert TooLong();
        Response storage cur = _responses[key][msg.sender];
        bool had = cur.by != address(0);
        if (bytes(text).length == 0) {
            if (!had) revert NoChange();
            emit Responded(key, msg.sender, cur.chainId, cur.account, text);
            delete _responses[key][msg.sender];
            _dropAuthor(key, msg.sender);
            return;
        }
        if (!mayAnswer(key, chainId, account, msg.sender)) revert NotResponder();
        if (had) _dropAuthor(key, msg.sender);
        else if (_authors[key].length >= MAX_RESPONSES) _evictOldest(key);
        _authors[key].push(msg.sender);
        _responses[key][msg.sender] = Response(msg.sender, uint64(block.timestamp), chainId, account, text);
        emit Responded(key, msg.sender, chainId, account, text);
    }

    function _dropAuthor(bytes32 key, address who) private {
        address[] storage a = _authors[key];
        uint256 n = a.length;
        for (uint256 i = 0; i < n; i++) {
            if (a[i] != who) continue;
            for (uint256 j = i + 1; j < n; j++) a[j - 1] = a[j]; // keep the order
            a.pop();
            return;
        }
    }

    /// Full: the least recently updated response goes, never the assigned responder's.
    function _evictOldest(bytes32 key) private {
        address[] storage a = _authors[key];
        address keep = responder[key];
        for (uint256 i = 0; i < a.length; i++) {
            if (a[i] == keep) continue;
            address old = a[i];
            delete _responses[key][old];
            _dropAuthor(key, old);
            return;
        }
    }

    /// How many responses `key` has (at most MAX_RESPONSES, plus none).
    function responseCount(bytes32 key) external view returns (uint256) {
        return _authors[key].length;
    }

    /// The i-th response to `key`: the governance-assigned responder's first (if
    /// it posted one), then the others newest first. Past the end: all zero.
    function responseAt(bytes32 key, uint256 i) public view returns (string memory text, address by, uint64 at, uint256 chainId, address account) {
        address[] storage a = _authors[key];
        address r = responder[key];
        bool rFirst = r != address(0) && _responses[key][r].by != address(0);
        address who;
        if (rFirst && i == 0) who = r;
        else {
            uint256 k = rFirst ? i - 1 : i; // index among the others, newest first
            for (uint256 j = a.length; j > 0; j--) {
                if (rFirst && a[j - 1] == r) continue;
                if (k == 0) { who = a[j - 1]; break; }
                k--;
            }
        }
        if (who == address(0)) return ("", address(0), 0, 0, address(0));
        Response storage x = _responses[key][who];
        return (x.text, x.by, x.at, x.chainId, x.account);
    }

    /// The first response (responseAt(key, 0)): the assigned responder's, else the newest.
    function responseOf(bytes32 key) external view returns (string memory text, address by, uint64 at, uint256 chainId, address account) {
        return responseAt(key, 0);
    }

    /// `who`'s own response to `key` (empty: none).
    function responseBy(bytes32 key, address who) external view returns (string memory text, uint64 at, uint256 chainId, address account) {
        Response storage x = _responses[key][who];
        return (x.text, x.at, x.chainId, x.account);
    }

    /// The evidence of the flag on `key` (of the round's first flag vote; while
    /// a flag round is still open, that vote's). Zero when there is none.
    function evidenceOf(bytes32 key) external view returns (bytes32 reportHash, string memory uri, address by, uint64 at) {
        Evidence storage v = _evidence[key];
        return (v.reportHash, v.uri, v.by, v.at);
    }

    // ---- appeal ----

    /// Appeal the standing flag on `key` as the party behind (chainId, account),
    /// paying exactly appealBond. Opens an appeal round (voteAppeal).
    function appeal(bytes32 key, uint256 chainId, address account) external payable returns (uint32 id) {
        if (communityFund == address(0)) revert AppealsOff();
        Entry storage e = entries[key];
        if (!e.flagged) revert NotFlagged();
        if (appeals[key].appellant != address(0)) revert AppealOpen();
        if (msg.value != appealBond) revert BadBond(appealBond);
        if (!mayAnswer(key, chainId, account, msg.sender)) revert NotResponder();
        id = ++appealCount[key];
        appeals[key] = Appeal(msg.sender, uint64(block.timestamp), e.round - 1, 0, 0, uint128(msg.value));
        emit Appealed(key, id, msg.sender, uint128(msg.value));
    }

    /// A fresh runner's vote in the open appeal on `key`: clear the flag (clear =
    /// true) or keep it, with its own evidence (the reproduction it ran).
    /// Runners who voted for or backed the flag, and the appellant, cannot vote.
    function voteAppeal(bytes32 key, bool clear, bytes32 reportHash, string calldata uri) external {
        _checkRunner();
        _checkEvidence(true, reportHash, uri);
        Appeal storage a = appeals[key];
        if (a.appellant == address(0)) revert NoAppeal();
        if (block.timestamp >= uint256(a.openedAt) + appealWindow) revert AppealExpired();
        uint32 r = a.flagRound;
        if (voted[key][r][msg.sender] || backed[key][r][msg.sender] || msg.sender == a.appellant) revert NotFresh();
        uint32 id = appealCount[key];
        if (appealVoted[key][id][msg.sender]) revert AlreadyVoted();
        appealVoted[key][id][msg.sender] = true;
        emit AppealVoted(key, id, msg.sender, clear, reportHash, uri);
        if (clear) {
            if (++a.clearVotes < quorum) return;
            address[] storage fl = _flaggers[key][r];
            for (uint256 i = 0; i < fl.length; i++) emit Struck(fl[i], key, ++strikes[fl[i]]);
            _closeAppeal(key, 1);
            Entry storage e = entries[key];
            _reset(e, key);
            e.round += 1;
            e.updatedAt = uint64(block.timestamp);
            emit Cleared(key);
        } else if (++a.keepVotes >= quorum) {
            _closeAppeal(key, 2);
        }
    }

    /// Nobody decided within appealWindow: the bond is refunded, the flag stands.
    function expireAppeal(bytes32 key) external {
        Appeal storage a = appeals[key];
        if (a.appellant == address(0)) revert NoAppeal();
        if (block.timestamp < uint256(a.openedAt) + appealWindow) revert NotYet();
        _closeAppeal(key, 3);
    }

    /// outcome 2 (kept): the bond to the community fund; otherwise refunded.
    function _closeAppeal(bytes32 key, uint8 outcome) private {
        Appeal memory a = appeals[key];
        delete appeals[key];
        if (outcome == 2) fundOwed += a.bond;
        else owed[a.appellant] += a.bond;
        emit AppealClosed(key, appealCount[key], outcome);
    }

    /// Take refunded bonds.
    function withdraw() external {
        uint256 amount = owed[msg.sender];
        owed[msg.sender] = 0;
        _pay(msg.sender, amount);
    }

    /// Send kept bonds to the community fund (anyone may call it): the last
    /// non-zero fund governance set, even after appeals were turned off.
    function payFund() external {
        uint256 amount = fundOwed;
        if (amount == 0) return;
        address to = fundPayee;
        if (to == address(0)) revert NoFund();
        fundOwed = 0;
        _pay(to, amount);
    }

    function _pay(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert PayFailed();
        emit Paid(to, amount);
    }

    // ---- warning views: true as soon as the quorum flagged (Neuro warns on these) ----

    function isFlagged(bytes32 fingerprint) public view returns (bool, Reason) {
        Entry storage e = entries[fingerprint];
        return (e.flagged, e.reason);
    }

    /// EVM code with this code hash (extcodehash) is flagged. Empty code never is.
    function isCodeFlagged(bytes32 codeHash) public view returns (bool, Reason) {
        if (codeHash == bytes32(0) || codeHash == EMPTY_CODEHASH) return (false, Reason.None);
        return isFlagged(codeKey(codeHash));
    }

    function isAddressFlagged(uint256 chainId, address who) public view returns (bool, Reason) {
        return isFlagged(addressKey(chainId, who));
    }

    /// For contracts on this chain: `who` itself is flagged, or the code at it is.
    function isContractFlagged(address who) external view returns (bool, Reason) {
        (bool f, Reason r) = isAddressFlagged(block.chainid, who);
        if (f) return (f, r);
        return isCodeFlagged(who.codehash);
    }

    // ---- hold views: true once the flag is holdDelay old, at once through the fast
    //      lane or holdNow (these hold bridging, reversibly) ----

    /// When a standing flag starts to hold (0: not flagged).
    function heldFrom(bytes32 key) public view returns (uint64 from) {
        Entry storage e = entries[key];
        if (!e.flagged) return 0;
        from = e.updatedAt + holdDelay;
        if (e.fast && e.fastAt < from) from = e.fastAt;
        HoldNow storage h = heldNow[key];
        if (h.round == e.round && h.at < from) from = h.at;
    }

    function isHeld(bytes32 key) public view returns (bool, Reason) {
        Entry storage e = entries[key];
        if (!e.flagged) return (false, Reason.None);
        if (e.fast || heldNow[key].round == e.round || block.timestamp >= uint256(e.updatedAt) + holdDelay) return (true, e.reason);
        return (false, Reason.None);
    }

    function isCodeHeld(bytes32 codeHash) public view returns (bool, Reason) {
        if (codeHash == bytes32(0) || codeHash == EMPTY_CODEHASH) return (false, Reason.None);
        return isHeld(codeKey(codeHash));
    }

    function isAddressHeld(uint256 chainId, address who) public view returns (bool, Reason) {
        return isHeld(addressKey(chainId, who));
    }

    function isContractHeld(address who) external view returns (bool, Reason) {
        (bool f, Reason r) = isAddressHeld(block.chainid, who);
        if (f) return (f, r);
        return isCodeHeld(who.codehash);
    }

    // ---- enforcement views: true only once the flag is enforceDelay old, or at once
    //      through the fast lane (these block) ----

    /// When a standing flag starts to be enforced (0: not flagged).
    function enforcedFrom(bytes32 key) public view returns (uint64) {
        Entry storage e = entries[key];
        if (!e.flagged) return 0;
        uint64 normal = e.updatedAt + enforceDelay;
        return e.fast && e.fastAt < normal ? e.fastAt : normal;
    }

    function isEnforced(bytes32 key) public view returns (bool, Reason) {
        Entry storage e = entries[key];
        if (!e.flagged || (!e.fast && block.timestamp < uint256(e.updatedAt) + enforceDelay)) return (false, Reason.None);
        return (true, e.reason);
    }

    function isCodeEnforced(bytes32 codeHash) public view returns (bool, Reason) {
        if (codeHash == bytes32(0) || codeHash == EMPTY_CODEHASH) return (false, Reason.None);
        return isEnforced(codeKey(codeHash));
    }

    function isAddressEnforced(uint256 chainId, address who) public view returns (bool, Reason) {
        return isEnforced(addressKey(chainId, who));
    }

    function isContractEnforced(address who) external view returns (bool, Reason) {
        (bool f, Reason r) = isAddressEnforced(block.chainid, who);
        if (f) return (f, r);
        return isCodeEnforced(who.codehash);
    }

    function flaggedCount() external view returns (uint256) {
        return flaggedList.length;
    }
}

contracts/ThreatReports.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// The parts of ThreatRegistry this contract reads.
interface IThreatRegistryView {
    function governance() external view returns (address);
    function quorum() external view returns (uint8);
    function voted(bytes32 key, uint32 round, address runner) external view returns (bool);
    function entries(bytes32 key) external view returns (
        bool flagged, uint8 reason, uint64 updatedAt, uint32 round, uint8 votes, bool fast, uint8 support, uint64 fastAt);
}

/// @title ThreatReports: anyone can point the Neuro runners at a contract to check
/// @notice A user who wants a contract's code checked pays a small fee and
///         reports it: report(key, chainKey, target, note). Runners' tools
///         watch the Reported event, run Neuro on the target and, if a
///         reproducible code fact shows up (ThreatRegistry.Reason, with its
///         evidence), flag the key in the ThreatRegistry (the usual quorum;
///         reports never flag anything by themselves, and a report is a request
///         to check, not a finding).
///         The fee is the anti-spam and the runners' reward:
///           - the key is flagged after the report: the runners who set that
///             flag (the registry's quorum of that round) share the fee; each
///             claims its share (claim);
///           - not flagged within `ttl`: the fee goes to the community fund.
///         settle(id) decides which (anyone may call it).
///         Input is bounded: a note of at most MAX_NOTE bytes, one key per report.
///         Governance is the ThreatRegistry's governance.
contract ThreatReports {
    struct Report {
        bytes32 key;          // ThreatRegistry key: fp1, codeKey(..) or addressKey(..)
        bytes32 chainKey;     // where the target lives, e.g. "eip155:56" or "bsc" (bytes32 string)
        address target;       // the contract on that chain (zero: none given)
        address reporter;
        uint64 createdAt;
        uint8 state;          // 0 open, 1 flagged (runners claim), 2 not flagged (to the fund)
        uint32 flagRound;     // the registry round whose voters share the fee
        uint128 fee;          // what was paid
        uint128 share;        // each voter's share once flagged
        uint8 claims;         // shares paid (at most the registry's quorum)
    }

    uint256 public constant MAX_NOTE = 280;
    uint256 public constant MAX_FEE = 100 ether;
    uint64 public constant MIN_TTL = 1 days;
    uint64 public constant MAX_TTL = 365 days;

    IThreatRegistryView public immutable registry;
    uint256 public fee;
    uint64 public ttl;
    address public communityFund;
    Report[] public reports;
    mapping(uint256 => mapping(address => bool)) public claimed;

    event Reported(uint256 indexed id, bytes32 indexed key, bytes32 indexed chainKey, address target, address reporter, uint256 fee, string note);
    event Settled(uint256 indexed id, bool flagged, uint256 share);
    event Claimed(uint256 indexed id, address indexed runner, uint256 amount);
    event FeeSet(uint256 fee);
    event TtlSet(uint64 ttl);
    event CommunityFundSet(address fund);

    error NotGovernance();
    error BadFee(uint256 fee);
    error NoteTooLong();
    error BadKey();
    error AlreadyFlagged();
    error NotSettled();
    error AlreadySettled();
    error NotYet();
    error NotVoter();
    error PayFailed();

    constructor(IThreatRegistryView registry_, address communityFund_, uint256 fee_, uint64 ttl_) {
        require(communityFund_ != address(0), "fund");
        require(fee_ <= MAX_FEE, "fee");
        require(ttl_ >= MIN_TTL && ttl_ <= MAX_TTL, "ttl");
        registry = registry_;
        communityFund = communityFund_;
        fee = fee_;
        ttl = ttl_;
    }

    modifier onlyGov() { if (msg.sender != registry.governance()) revert NotGovernance(); _; }

    function setFee(uint256 f) external onlyGov { require(f <= MAX_FEE, "fee"); fee = f; emit FeeSet(f); }
    function setTtl(uint64 t) external onlyGov { require(t >= MIN_TTL && t <= MAX_TTL, "ttl"); ttl = t; emit TtlSet(t); }
    function setCommunityFund(address f) external onlyGov { require(f != address(0), "fund"); communityFund = f; emit CommunityFundSet(f); }

    /// Ask the runners to check a contract. `key` is the registry key the runners
    /// would flag; send exactly `fee`. A key that is already flagged needs no
    /// report (and would pay nobody for new work), so it is refused.
    function report(bytes32 key, bytes32 chainKey, address target, string calldata note) external payable returns (uint256 id) {
        if (msg.value != fee) revert BadFee(fee);
        if (bytes(note).length > MAX_NOTE) revert NoteTooLong();
        if (key == bytes32(0)) revert BadKey();
        (bool flagged, , , , , , , ) = registry.entries(key);
        if (flagged) revert AlreadyFlagged();
        id = reports.length;
        reports.push(Report(key, chainKey, target, msg.sender, uint64(block.timestamp), 0, 0, uint128(msg.value), 0, 0));
        emit Reported(id, key, chainKey, target, msg.sender, msg.value, note);
    }

    /// Flagged since the report: the voters of that flag share the fee. Not
    /// flagged and older than ttl: the fee goes to the community fund.
    function settle(uint256 id) external {
        Report storage r = reports[id];
        if (r.state != 0) revert AlreadySettled();
        (bool flagged, , uint64 updatedAt, uint32 round, , , , ) = registry.entries(r.key);
        if (flagged && updatedAt >= r.createdAt) {
            uint256 q = registry.quorum();
            r.state = 1;
            r.flagRound = round - 1; // the round that set the standing flag
            r.share = uint128(r.fee / q);
            uint256 dust = r.fee - r.share * q;
            if (dust != 0) _pay(communityFund, dust);
            emit Settled(id, true, r.share);
        } else if (block.timestamp >= uint256(r.createdAt) + ttl) {
            r.state = 2;
            _pay(communityFund, r.fee);
            emit Settled(id, false, 0);
        } else revert NotYet();
    }

    /// A runner who voted for the flag that settled this report takes its share.
    function claim(uint256 id) external {
        Report storage r = reports[id];
        if (r.state != 1) revert NotSettled();
        if (claimed[id][msg.sender]) revert AlreadySettled();
        if (!registry.voted(r.key, r.flagRound, msg.sender)) revert NotVoter();
        if (r.claims >= registry.quorum()) revert AlreadySettled(); // never more than the fee
        r.claims += 1;
        claimed[id][msg.sender] = true;
        _pay(msg.sender, r.share);
        emit Claimed(id, msg.sender, r.share);
    }

    function reportCount() external view returns (uint256) {
        return reports.length;
    }

    function _pay(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert PayFailed();
    }
}

contracts/TwapRecorder.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// The Uniswap-V2 pair surface (ZetaphyPair) the recorder reads.
interface ITwapPair {
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function price0CumulativeLast() external view returns (uint256);
    function price1CumulativeLast() external view returns (uint256);
    function token0() external view returns (address);
    function token1() external view returns (address);
}

/// @title TwapRecorder: observations of DEX pairs' cumulative prices, for TWAPs
/// @notice A Uniswap-V2 pair (ZetaphyPair) keeps price0/price1CumulativeLast:
///         the running sum of its price times the seconds it held, updated at
///         the FIRST trade of a block with the reserves from before it. A TWAP
///         over [t0, t1] is (cumulative(t1) - cumulative(t0)) / (t1 - t0); it
///         needs cumulative(t0) remembered, which is what this contract does.
///         No owner, no settings after deployment. Anyone (a keeper, the relay,
///         a user) may call record(pair):
///           - at most one observation per pair every `minSpacing` seconds and
///             never two in one block, so pokes cannot flood the ring;
///           - an observation is the cumulative price as of now, counted with
///             the reserves from before this block's first trade (the pair's
///             own rule), so a swap in the same transaction or block as the
///             record (or as the read) adds nothing to the average;
///           - it also keeps sqrt(reserve0 * reserve1) (pool depth that swaps
///             cannot lower), so a reader can require depth at every observation
///             of its window, not only at the moment it reads.
///         consult() returns the window's average and what a reader needs to
///         judge it (oldest time, observation count, smallest depth, the
///         largest gap of one segment's average from the window's average).
contract TwapRecorder {
    struct Observation {
        uint64 time;
        uint128 depth;   // sqrt(reserve0 * reserve1), raw units
        uint256 cum0;    // price0Cumulative (UQ112x112 seconds), wraps by design
        uint256 cum1;
    }

    uint16 public constant CAPACITY = 96;
    uint32 public immutable minSpacing;

    mapping(address => Observation[CAPACITY]) private _obs;
    mapping(address => uint16) public nextIndex;
    mapping(address => uint16) public count;

    event Observed(address indexed pair, uint64 time, uint256 cum0, uint256 cum1, uint128 depth);

    error NotEnoughHistory();
    error EmptyPool();

    constructor(uint32 minSpacing_) {
        require(minSpacing_ >= 1, "spacing");
        minSpacing = minSpacing_;
    }

    /// Records an observation if minSpacing has passed since the last one. Returns whether it did.
    function record(address pair) external returns (bool) {
        uint16 n = count[pair];
        if (n != 0) {
            Observation storage last = _obs[pair][(nextIndex[pair] + CAPACITY - 1) % CAPACITY];
            if (block.timestamp < uint256(last.time) + minSpacing) return false;
        }
        (uint256 c0, uint256 c1, uint128 d) = current(pair);
        if (d == 0) revert EmptyPool();
        uint16 i = nextIndex[pair];
        _obs[pair][i] = Observation(uint64(block.timestamp), d, c0, c1);
        nextIndex[pair] = (i + 1) % CAPACITY;
        if (n < CAPACITY) count[pair] = n + 1;
        emit Observed(pair, uint64(block.timestamp), c0, c1, d);
        return true;
    }

    /// The pair's cumulative prices as of now (Uniswap's currentCumulativePrices) and its depth.
    function current(address pair) public view returns (uint256 c0, uint256 c1, uint128 depth) {
        c0 = ITwapPair(pair).price0CumulativeLast();
        c1 = ITwapPair(pair).price1CumulativeLast();
        (uint112 r0, uint112 r1, uint32 last) = ITwapPair(pair).getReserves();
        uint32 nowTs = uint32(block.timestamp);
        if (last != nowTs && r0 != 0 && r1 != 0) {
            unchecked {
                uint32 elapsed = nowTs - last; // wraps, as in the pair
                c0 += ((uint256(r1) << 112) / r0) * elapsed;
                c1 += ((uint256(r0) << 112) / r1) * elapsed;
            }
        }
        depth = uint128(_sqrt(uint256(r0) * uint256(r1)));
    }

    /// The i-th newest observation (0 = newest).
    function observation(address pair, uint16 i) public view returns (Observation memory) {
        require(i < count[pair], "index");
        return _obs[pair][(nextIndex[pair] + CAPACITY - 1 - i) % CAPACITY];
    }

    struct Twap {
        uint256 avg0;          // UQ112x112: token1 per token0 (raw units), over [from, now]
        uint256 avg1;          // token0 per token1
        uint64 from;           // the observation the window starts at (at least `window` old)
        uint64 newest;         // the newest observation's time
        uint16 observations;   // observations in [from, now], `from` included
        uint128 minDepth;      // smallest depth at those observations and now
        uint256 maxSegmentGapBps; // largest |segment average - window average| / window average of avg0, in bps
    }

    /// The average over the newest observation that is at least `window` seconds old up to now.
    /// Reverts NotEnoughHistory if there is none.
    function consult(address pair, uint32 window) external view returns (Twap memory t) {
        uint16 n = count[pair];
        uint256 nowTs = block.timestamp;
        // newest first: find the first one at least `window` old
        uint16 k = type(uint16).max;
        for (uint16 i = 0; i < n; i++) {
            if (nowTs >= uint256(observation(pair, i).time) + window) { k = i; break; }
        }
        if (k == type(uint16).max) revert NotEnoughHistory();
        Observation memory start = observation(pair, k);
        (uint256 c0, uint256 c1, uint128 d) = current(pair);
        uint256 span = nowTs - start.time;
        if (span == 0) revert NotEnoughHistory();
        unchecked {
            t.avg0 = (c0 - start.cum0) / span;
            t.avg1 = (c1 - start.cum1) / span;
        }
        t.from = start.time;
        t.newest = n == 0 ? 0 : observation(pair, 0).time;
        t.observations = k + 1;
        (t.minDepth, t.maxSegmentGapBps) = _segments(pair, k, start, Observation(uint64(nowTs), d, c0, c1), t.avg0);
    }

    /// Walks start -> ... -> newest -> now: the smallest depth, and the largest gap of a
    /// segment's average (avg0) from the window's average, in bps.
    function _segments(address pair, uint16 k, Observation memory prev, Observation memory last, uint256 avg)
        private view returns (uint128 minDepth, uint256 maxGapBps)
    {
        minDepth = prev.depth < last.depth ? prev.depth : last.depth;
        for (uint16 j = k + 1; j > 0; j--) {
            Observation memory o = j == 1 ? last : observation(pair, j - 2);
            if (o.depth < minDepth) minDepth = o.depth;
            uint256 dt = uint256(o.time) - prev.time;
            if (dt != 0 && avg != 0) {
                uint256 seg;
                unchecked { seg = (o.cum0 - prev.cum0) / dt; }
                uint256 bps = _mulDiv(seg > avg ? seg - avg : avg - seg, 10_000, avg);
                if (bps > maxGapBps) maxGapBps = bps;
            }
            prev = o;
        }
    }

    function _sqrt(uint256 x) private pure returns (uint256 z) {
        if (x == 0) return 0;
        z = x;
        uint256 y = x / 2 + 1;
        while (y < z) { z = y; y = (x / y + y) / 2; }
    }

    /// floor(a * b / d) with a 512-bit product (Remco Bloemen's mulDiv, MIT).
    function _mulDiv(uint256 a, uint256 b, uint256 d) private pure returns (uint256 result) {
        unchecked {
            uint256 prod0;
            uint256 prod1;
            assembly {
                let mm := mulmod(a, b, not(0))
                prod0 := mul(a, b)
                prod1 := sub(sub(mm, prod0), lt(mm, prod0))
            }
            if (prod1 == 0) return prod0 / d;
            require(d > prod1, "mulDiv");
            uint256 remainder;
            assembly {
                remainder := mulmod(a, b, d)
                prod1 := sub(prod1, gt(remainder, prod0))
                prod0 := sub(prod0, remainder)
            }
            uint256 twos = d & (~d + 1);
            assembly {
                d := div(d, twos)
                prod0 := div(prod0, twos)
                twos := add(div(sub(0, twos), twos), 1)
            }
            prod0 |= prod1 * twos;
            uint256 inv = (3 * d) ^ 2;
            inv *= 2 - d * inv; inv *= 2 - d * inv; inv *= 2 - d * inv;
            inv *= 2 - d * inv; inv *= 2 - d * inv; inv *= 2 - d * inv;
            result = prod0 * inv;
        }
    }
}

contracts/VaultTestRecipients.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// Test-only recipients for RewardVault.

/// Refuses every payment.
contract RefusingRecipient {
    receive() external payable { revert("no"); }
}

interface IVault {
    function applyShares() external;
    function release() external returns (uint256);
}

/// Tries to re-enter the vault while being paid.
contract ReentrantRecipient {
    IVault public vault;
    uint256 public attempts;
    function setVault(address v) external { vault = IVault(v); }
    receive() external payable {
        attempts += 1;
        try vault.applyShares() {} catch {}
        try vault.release() {} catch {}
    }
}

contracts/WebAuthnVerifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title WebAuthnVerifier: checks a passkey (WebAuthn) assertion on chain
/// @notice Stateless helper shared by LabelRegistry (human labels) and
///         AgentPolicyWallet (emergency freeze by the owner's passkey).
///         The P-256 (secp256r1) signature is checked by the precompile at
///         0x…0100 that cosmos/evm ships (RIP-7212 interface: input
///         hash ‖ r ‖ s ‖ x ‖ y, output 32 bytes = 1 when valid, empty
///         otherwise). ZETAPHY's genesis enables it (active_static_precompiles
///         in zetaphy-chain/setup-node.sh).
///
///         What is checked, as a relying party would (WebAuthn §7.2):
///           - clientDataJSON has "type":"webauthn.get" and
///             "challenge":"<base64url of the 32-byte challenge>";
///           - authenticatorData starts with rpIdHash (sha256 of the site's
///             host name; 0 = any site) and has the user-present flag, and
///             the user-verified flag when requireUV;
///           - the signature is over sha256(authenticatorData ‖ sha256(clientDataJSON)).
///         Not checked: the origin inside clientDataJSON (rpIdHash already
///         binds the site), the signature counter (passkeys that sync keep it
///         at 0), and attestation (who made the authenticator).
contract WebAuthnVerifier {
    address public constant P256 = 0x0000000000000000000000000000000000000100;

    bytes1 private constant FLAG_UP = 0x01;
    bytes1 private constant FLAG_UV = 0x04;

    /// A passkey's answer to navigator.credentials.get(): the authenticator
    /// data, the client data JSON and the signature as (r, s).
    struct Assertion {
        bytes authenticatorData;
        bytes clientDataJSON;
        uint256 r;
        uint256 s;
    }

    /// True when `a` is a valid assertion of the passkey (x, y) over `challenge`.
    function verify(bytes32 challenge, Assertion calldata a, uint256 x, uint256 y, bytes32 rpIdHash, bool requireUV)
        external view returns (bool)
    {
        if (!_flagsOk(a.authenticatorData, rpIdHash, requireUV)) return false;
        if (!_contains(a.clientDataJSON, bytes('"type":"webauthn.get"'))) return false;
        if (!_contains(a.clientDataJSON, abi.encodePacked('"challenge":"', base64url(challenge), '"'))) return false;
        bytes32 h = sha256(abi.encodePacked(a.authenticatorData, sha256(a.clientDataJSON)));
        (bool ok, bytes memory ret) = P256.staticcall(abi.encode(h, a.r, a.s, x, y));
        return ok && ret.length == 32 && uint256(bytes32(ret)) == 1;
    }

    function _flagsOk(bytes calldata authData, bytes32 rpIdHash, bool requireUV) private pure returns (bool) {
        if (authData.length < 37) return false;
        if (rpIdHash != bytes32(0) && bytes32(authData[0:32]) != rpIdHash) return false;
        bytes1 flags = authData[32];
        if (flags & FLAG_UP == 0) return false;
        if (requireUV && flags & FLAG_UV == 0) return false;
        return true;
    }

    /// base64url without padding of 32 bytes (43 characters), as WebAuthn
    /// writes the challenge in clientDataJSON.
    function base64url(bytes32 data) public pure returns (string memory) {
        bytes memory table = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
        bytes memory out = new bytes(43);
        uint256 v = uint256(data);
        // 32 bytes = 256 bits = 42 full 6-bit groups + 4 bits (padded with 2 zero bits)
        for (uint256 i = 0; i < 42; i++) {
            out[i] = table[(v >> (250 - 6 * i)) & 63];
        }
        out[42] = table[(v & 15) << 2];
        return string(out);
    }

    function _contains(bytes calldata hay, bytes memory needle) private pure returns (bool) {
        uint256 n = needle.length;
        if (hay.length < n) return false;
        bytes32 nh = keccak256(needle);
        for (uint256 i = 0; i + n <= hay.length; i++) {
            if (hay[i] == needle[0] && keccak256(hay[i:i + n]) == nh) return true;
        }
        return false;
    }
}

contracts/ZetaphyOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// Pyth's IPyth read surface, with PythStructs.Price's layout (the real Pyth and ZetaphyPythRelay both answer it).
interface IPythPrice {
    struct Price {
        int64 price;
        uint64 conf;
        int32 expo;
        uint256 publishTime;
    }
    function getPriceUnsafe(bytes32 id) external view returns (Price memory);
}

/// TwapRecorder's surface.
interface ITwapSource {
    struct Twap {
        uint256 avg0;
        uint256 avg1;
        uint64 from;
        uint64 newest;
        uint16 observations;
        uint128 minDepth;
        uint256 maxSegmentGapBps;
    }
    function consult(address pair, uint32 window) external view returns (Twap memory);
    function record(address pair) external returns (bool);
}

interface IPairTokens {
    function token0() external view returns (address);
    function token1() external view returns (address);
}

interface IDecimals {
    function decimals() external view returns (uint8);
}

/// @title ZetaphyOracle: one price per asset, or a clear revert
/// @notice price(asset) returns (value, updatedAt): `value` is the asset's price in
///         USD with 18 decimals (1e18 = $1 per whole token), `updatedAt` the oldest
///         source time behind it. When any guard fails it REVERTS with an error
///         naming what failed; it never returns a stale, lopsided or jumped value.
///         Sources, per asset (governance enables one or both):
///           a) a TWAP of a ZETAPHY DEX pair (TwapRecorder observations, the pair's
///              cumulative prices; the other token is a USD stablecoin counted at $1):
///              valid only over at least `window` seconds (from an observation at
///              most 2 x window old), with at least `minObservations` observations
///              in it, a pool depth (quote side, 18 decimals) of at least
///              `minLiquidity` at every observation and now, and no segment
///              between observations averaging more than `maxSegmentGapBps` away
///              from the window's average;
///           b) Pyth (IPyth.getPriceUnsafe; on ZETAPHY a ZetaphyPythRelay until Pyth
///              or a Hyperlane route is here): not older than `maxAge`, not dated
///              in the future, positive, confidence interval at most `maxConfBps`
///              of the price.
///         With both: they must agree within `maxDeviationBps` (else SourcesDeviate);
///         the value is Pyth's, anchored by the TWAP. Decimals are normalized
///         (token decimals, Pyth's exponent) to 18.
///         Circuit breaker: poke(asset) (anyone; a keeper, the relay) records a TWAP
///         observation and, if every guard passes, makes the live price the
///         reference. price() refuses a live price more than `maxChangeBps` from the
///         reference, or more than `maxWindowChangeBps` from the price at the start
///         of the current `changeWindow`. A poke that sees such a jump TRIPS the
///         breaker: the asset has no price until governance resets it (through the
///         timelock). poke() also logs DeviationTripped / StaleFeed / SourceProblem
///         for the bridge monitor (zetaphy bridge monitor).
///         Roles: governance (the ZetaphyTimelock) sets every parameter; guardians
///         (multisigs governance names) may pause a feed at once. Unpausing,
///         resetting a tripped breaker and any setting wait the timelock.
contract ZetaphyOracle {
    struct TwapConfig {
        address pair;            // zero: no TWAP source
        bool assetIsToken0;
        uint8 assetDecimals;
        uint8 quoteDecimals;
        uint32 window;           // seconds
        uint16 minObservations;
        uint16 maxSegmentGapBps;
        uint128 minLiquidity;    // quote-side depth, 18 decimals (USD)
    }
    struct PythConfig {
        bytes32 id;              // zero: no Pyth source
        uint32 maxAge;           // seconds
        uint16 maxConfBps;
    }
    struct Guards {
        uint16 maxDeviationBps;      // between the two sources
        uint16 maxChangeBps;         // from the reference (the last accepted price)
        uint16 maxWindowChangeBps;   // from the price at the start of the change window
        uint32 changeWindow;         // seconds
    }
    struct State {
        uint128 lastPrice;       // the reference (0: none yet, poke first)
        uint64 lastAt;
        bool paused;
        bool tripped;
        uint128 windowPrice;
        uint64 windowStart;
    }

    /// What went wrong with the live price (poke logs it; price() reverts with the matching error).
    enum Problem { None, NotConfigured, TwapUnavailable, TwapStale, TooFewObservations, LowLiquidity, TwapSpike,
        PythUnavailable, PythStale, PythInvalid, PythConfidence, SourcesDeviate }

    ITwapSource public immutable recorder;
    IPythPrice public pyth;
    address public governance;
    mapping(address => bool) public guardian;

    mapping(address => TwapConfig) public twapOf;
    mapping(address => PythConfig) public pythOf;
    mapping(address => Guards) public guardsOf;
    mapping(address => State) public stateOf;
    address[] private _assets;
    mapping(address => bool) public listed;

    uint256 public constant MAX_FUTURE = 60;   // seconds a Pyth publishTime may run ahead (clock skew)
    uint256 private constant BPS = 10_000;

    event GovernanceSet(address governance);
    event GuardianSet(address indexed who, bool on);
    event PythSet(address pyth);
    event TwapConfigured(address indexed asset, address pair, uint32 window, uint16 minObservations, uint16 maxSegmentGapBps, uint128 minLiquidity);
    event PythConfigured(address indexed asset, bytes32 id, uint32 maxAge, uint16 maxConfBps);
    event GuardsSet(address indexed asset, uint16 maxDeviationBps, uint16 maxChangeBps, uint16 maxWindowChangeBps, uint32 changeWindow);
    event FeedPaused(address indexed asset, address indexed by);
    event FeedUnpaused(address indexed asset);
    event CircuitBreakerReset(address indexed asset);
    event Poked(address indexed asset, uint256 price, uint256 updatedAt);
    event DeviationTripped(address indexed asset, uint256 twapPrice, uint256 pythPrice, uint256 bps);
    event StaleFeed(address indexed asset, uint8 source, uint256 updatedAt);   // source 1 TWAP, 2 Pyth
    event SourceProblem(address indexed asset, uint8 problem, uint256 a, uint256 b);
    event CircuitBreakerTripped(address indexed asset, uint256 price, uint256 ref, uint256 bps);

    error NotGovernance();
    error NotGuardian();
    error UnknownAsset(address asset);
    error FeedIsPaused(address asset);
    error BreakerTripped(address asset);
    error NoReference(address asset);
    error PriceJump(address asset, uint256 price, uint256 ref, uint256 bps);
    /// No source enabled, or no guards set (setGuards is required).
    error NotConfigured(address asset);
    error TwapUnavailable(address asset);
    error TwapStale(address asset, uint256 from);
    error TooFewObservations(address asset, uint256 have, uint256 need);
    error LowLiquidity(address asset, uint256 depth, uint256 need);
    error TwapSpike(address asset, uint256 bps, uint256 most);
    error PythUnavailable(address asset);
    error PythStale(address asset, uint256 publishTime);
    error PythInvalid(address asset);
    error PythConfidence(address asset, uint256 bps, uint256 most);
    error SourcesDeviate(address asset, uint256 twapPrice, uint256 pythPrice, uint256 bps);
    error BadConfig();

    constructor(address governance_, ITwapSource recorder_, IPythPrice pyth_) {
        if (governance_ == address(0) || address(recorder_) == address(0)) revert BadConfig();
        governance = governance_;
        recorder = recorder_;
        pyth = pyth_;
        emit GovernanceSet(governance_);
        emit PythSet(address(pyth_));
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    // ---- governance (the timelock) ----

    function setGovernance(address g) external onlyGov { if (g == address(0)) revert BadConfig(); governance = g; emit GovernanceSet(g); }
    function setGuardian(address who, bool on) external onlyGov { guardian[who] = on; emit GuardianSet(who, on); }
    /// The Pyth contract (ZetaphyPythRelay now; Pyth itself once deployed on ZETAPHY). Zero: no Pyth.
    function setPyth(IPythPrice p) external onlyGov { pyth = p; emit PythSet(address(p)); }

    /// The TWAP source of `asset`: a DEX pair of `asset` and a USD stablecoin (pair zero: off).
    function setTwap(address asset, address pair, uint32 window, uint16 minObservations, uint16 maxSegmentGapBps, uint128 minLiquidity) external onlyGov {
        TwapConfig memory c;
        if (pair != address(0)) {
            address t0 = IPairTokens(pair).token0();
            address t1 = IPairTokens(pair).token1();
            if (asset != t0 && asset != t1) revert BadConfig();
            if (window < 60 || minObservations < 2 || maxSegmentGapBps == 0 || minLiquidity == 0) revert BadConfig();
            c = TwapConfig(pair, asset == t0, IDecimals(asset).decimals(), IDecimals(asset == t0 ? t1 : t0).decimals(),
                window, minObservations, maxSegmentGapBps, minLiquidity);
            if (c.quoteDecimals > 18 || c.assetDecimals > 30) revert BadConfig();
        }
        twapOf[asset] = c;
        _configured(asset);
        emit TwapConfigured(asset, pair, window, minObservations, maxSegmentGapBps, minLiquidity);
    }

    /// The Pyth feed of `asset` (id zero: off).
    function setPythFeed(address asset, bytes32 id, uint32 maxAge, uint16 maxConfBps) external onlyGov {
        if (id != bytes32(0) && (maxAge == 0 || maxConfBps == 0 || maxConfBps > BPS)) revert BadConfig();
        pythOf[asset] = PythConfig(id, maxAge, maxConfBps);
        _configured(asset);
        emit PythConfigured(asset, id, maxAge, maxConfBps);
    }

    function setGuards(address asset, uint16 maxDeviationBps, uint16 maxChangeBps, uint16 maxWindowChangeBps, uint32 changeWindow) external onlyGov {
        if (maxDeviationBps == 0 || maxChangeBps == 0 || maxWindowChangeBps < maxChangeBps || changeWindow == 0
            || maxDeviationBps > BPS || maxWindowChangeBps > BPS) revert BadConfig();
        guardsOf[asset] = Guards(maxDeviationBps, maxChangeBps, maxWindowChangeBps, changeWindow);
        _configured(asset);
        emit GuardsSet(asset, maxDeviationBps, maxChangeBps, maxWindowChangeBps, changeWindow);
    }

    /// Lifts a pause.
    function unpauseFeed(address asset) external onlyGov { stateOf[asset].paused = false; emit FeedUnpaused(asset); }

    /// Clears a tripped breaker and the reference: the next poke starts from the live price again.
    function resetCircuitBreaker(address asset) external onlyGov {
        State storage s = stateOf[asset];
        s.tripped = false;
        s.lastPrice = 0; s.lastAt = 0; s.windowPrice = 0; s.windowStart = 0;
        emit CircuitBreakerReset(asset);
    }

    function _configured(address asset) private {
        if (!listed[asset]) { listed[asset] = true; _assets.push(asset); }
        // A new source or guard starts from a fresh reference (the next poke).
        State storage s = stateOf[asset];
        s.lastPrice = 0; s.lastAt = 0; s.windowPrice = 0; s.windowStart = 0;
    }

    // ---- emergency: a guardian (or governance) stops a feed at once ----

    function pauseFeed(address asset) external {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
        stateOf[asset].paused = true;
        emit FeedPaused(asset, msg.sender);
    }

    // ---- consumers ----

    function assets() external view returns (address[] memory) { return _assets; }

    /// The asset's price in USD (18 decimals) and the time of its oldest source, or a revert naming why not.
    function price(address asset) external view returns (uint256 value, uint256 updatedAt) {
        if (!listed[asset]) revert UnknownAsset(asset);
        State memory s = stateOf[asset];
        if (s.paused) revert FeedIsPaused(asset);
        if (s.tripped) revert BreakerTripped(asset);
        Problem p; uint256 a; uint256 b;
        (value, updatedAt, p, a, b) = _live(asset);
        if (p != Problem.None) _fail(asset, p, a, b);
        if (s.lastPrice == 0) revert NoReference(asset);
        (uint256 ref, uint256 bps, bool ok) = _change(asset, s, value);
        if (!ok) revert PriceJump(asset, value, ref, bps);
    }

    /// The live price and what is wrong with it, without the circuit breaker (for monitors and tests).
    function livePrice(address asset) external view returns (uint256 value, uint256 updatedAt, Problem problem, uint256 a, uint256 b) {
        return _live(asset);
    }

    /// Anyone: records a TWAP observation and, when every guard passes, moves the reference
    /// to the live price. A jump beyond the change limits trips the breaker. Returns whether
    /// the reference moved.
    function poke(address asset) external returns (bool) {
        if (!listed[asset]) revert UnknownAsset(asset);
        address pair = twapOf[asset].pair;
        if (pair != address(0)) { try recorder.record(pair) {} catch {} }
        State storage s = stateOf[asset];
        if (s.paused || s.tripped) return false;
        (uint256 value, uint256 at, Problem p, uint256 a, uint256 b) = _live(asset);
        if (p != Problem.None) {
            if (p == Problem.SourcesDeviate) emit DeviationTripped(asset, a, b, _bps(a, b));
            else if (p == Problem.TwapStale) emit StaleFeed(asset, 1, a);
            else if (p == Problem.PythStale) emit StaleFeed(asset, 2, a);
            else emit SourceProblem(asset, uint8(p), a, b);
            return false;
        }
        if (s.lastPrice != 0) {
            if (block.timestamp >= uint256(s.windowStart) + guardsOf[asset].changeWindow) {
                s.windowPrice = s.lastPrice;
                s.windowStart = uint64(block.timestamp);
            }
            (uint256 ref, uint256 bps, bool ok) = _change(asset, s, value);
            if (!ok) {
                s.tripped = true;
                emit CircuitBreakerTripped(asset, value, ref, bps);
                return false;
            }
        } else {
            s.windowPrice = uint128(value);
            s.windowStart = uint64(block.timestamp);
        }
        s.lastPrice = uint128(value);
        s.lastAt = uint64(at);
        emit Poked(asset, value, at);
        return true;
    }

    // ---- internals ----

    /// (reference, bps, ok): the live value against the reference and the window's start price.
    function _change(address asset, State memory s, uint256 value) private view returns (uint256, uint256, bool) {
        Guards memory g = guardsOf[asset];
        uint256 bps = _bps(value, s.lastPrice);
        if (bps > g.maxChangeBps) return (s.lastPrice, bps, false);
        if (s.windowPrice != 0 && block.timestamp < uint256(s.windowStart) + g.changeWindow) {
            uint256 wb = _bps(value, s.windowPrice);
            if (wb > g.maxWindowChangeBps) return (s.windowPrice, wb, false);
        }
        return (s.lastPrice, bps, true);
    }

    function _live(address asset) private view returns (uint256 value, uint256 at, Problem p, uint256 a, uint256 b) {
        TwapConfig memory t = twapOf[asset];
        PythConfig memory y = pythOf[asset];
        if (t.pair == address(0) && (y.id == bytes32(0) || address(pyth) == address(0))) return (0, 0, Problem.NotConfigured, 0, 0);
        if (guardsOf[asset].maxChangeBps == 0) return (0, 0, Problem.NotConfigured, 0, 0); // guards are required
        uint256 twapValue; uint256 twapAt;
        if (t.pair != address(0)) {
            (twapValue, twapAt, p, a, b) = _twap(t);
            if (p != Problem.None) return (0, 0, p, a, b);
        }
        uint256 pythValue; uint256 pythAt;
        if (y.id != bytes32(0) && address(pyth) != address(0)) {
            (pythValue, pythAt, p, a, b) = _pyth(y);
            if (p != Problem.None) return (0, 0, p, a, b);
        }
        if (twapValue != 0 && pythValue != 0) {
            uint256 dev = _bps(twapValue, pythValue);
            if (dev > guardsOf[asset].maxDeviationBps) return (0, 0, Problem.SourcesDeviate, twapValue, pythValue);
            return (pythValue, pythAt < twapAt ? pythAt : twapAt, Problem.None, 0, 0);
        }
        return pythValue != 0 ? (pythValue, pythAt, Problem.None, 0, 0) : (twapValue, twapAt, Problem.None, 0, 0);
    }

    function _twap(TwapConfig memory t) private view returns (uint256 value, uint256 at, Problem p, uint256 a, uint256 b) {
        ITwapSource.Twap memory w;
        try recorder.consult(t.pair, t.window) returns (ITwapSource.Twap memory r) { w = r; } catch { return (0, 0, Problem.TwapUnavailable, 0, 0); }
        if (block.timestamp - w.from > 2 * uint256(t.window)) return (0, 0, Problem.TwapStale, w.from, 0);
        if (w.observations < t.minObservations) return (0, 0, Problem.TooFewObservations, w.observations, t.minObservations);
        if (w.maxSegmentGapBps > t.maxSegmentGapBps) return (0, 0, Problem.TwapSpike, w.maxSegmentGapBps, t.maxSegmentGapBps);
        uint256 avg = t.assetIsToken0 ? w.avg0 : w.avg1;   // quote (raw) per asset (raw), UQ112x112
        if (avg == 0) return (0, 0, Problem.TwapUnavailable, 0, 0);
        // depth: sqrt(r0 r1) * sqrt(quote per asset) = the quote reserve; then 18 decimals
        uint256 depth = (uint256(w.minDepth) * _sqrt(avg)) >> 56;
        depth = depth * (10 ** uint256(18 - t.quoteDecimals));
        if (depth < t.minLiquidity) return (0, 0, Problem.LowLiquidity, depth, t.minLiquidity);
        value = _mulDiv(avg, 10 ** (uint256(t.assetDecimals) + 18), (10 ** uint256(t.quoteDecimals)) << 112);
        if (value == 0 || value > type(uint128).max) return (0, 0, Problem.TwapUnavailable, 0, 0);
        return (value, w.newest, Problem.None, 0, 0);
    }

    function _pyth(PythConfig memory y) private view returns (uint256 value, uint256 at, Problem p, uint256 a, uint256 b) {
        IPythPrice.Price memory q;
        try pyth.getPriceUnsafe(y.id) returns (IPythPrice.Price memory r) { q = r; } catch { return (0, 0, Problem.PythUnavailable, 0, 0); }
        if (q.publishTime > block.timestamp + MAX_FUTURE) return (0, 0, Problem.PythInvalid, q.publishTime, 0);
        if (block.timestamp > q.publishTime && block.timestamp - q.publishTime > y.maxAge) return (0, 0, Problem.PythStale, q.publishTime, 0);
        if (q.price <= 0 || q.expo < -30 || q.expo > 12) return (0, 0, Problem.PythInvalid, 0, 0);
        uint256 raw = uint256(uint64(q.price));
        uint256 confBps = _mulDiv(uint256(q.conf), BPS, raw);
        if (confBps > y.maxConfBps) return (0, 0, Problem.PythConfidence, confBps, y.maxConfBps);
        int256 e = int256(q.expo) + 18;
        value = e >= 0 ? raw * (10 ** uint256(e)) : raw / (10 ** uint256(-e));
        if (value == 0 || value > type(uint128).max) return (0, 0, Problem.PythInvalid, 0, 0);
        return (value, q.publishTime > block.timestamp ? block.timestamp : q.publishTime, Problem.None, 0, 0);
    }

    function _fail(address asset, Problem p, uint256 a, uint256 b) private pure {
        if (p == Problem.NotConfigured) revert NotConfigured(asset);
        if (p == Problem.TwapUnavailable) revert TwapUnavailable(asset);
        if (p == Problem.TwapStale) revert TwapStale(asset, a);
        if (p == Problem.TooFewObservations) revert TooFewObservations(asset, a, b);
        if (p == Problem.LowLiquidity) revert LowLiquidity(asset, a, b);
        if (p == Problem.TwapSpike) revert TwapSpike(asset, a, b);
        if (p == Problem.PythUnavailable) revert PythUnavailable(asset);
        if (p == Problem.PythStale) revert PythStale(asset, a);
        if (p == Problem.PythInvalid) revert PythInvalid(asset);
        if (p == Problem.PythConfidence) revert PythConfidence(asset, a, b);
        revert SourcesDeviate(asset, a, b, _bps(a, b));
    }

    /// |x - y| / min(x, y), in bps.
    function _bps(uint256 x, uint256 y) private pure returns (uint256) {
        uint256 lo = x < y ? x : y;
        if (lo == 0) return type(uint256).max;
        return _mulDiv(x > y ? x - y : y - x, BPS, lo);
    }

    function _sqrt(uint256 x) private pure returns (uint256 z) {
        if (x == 0) return 0;
        z = x;
        uint256 y = x / 2 + 1;
        while (y < z) { z = y; y = (x / y + y) / 2; }
    }

    /// floor(a * b / d) with a 512-bit product (Remco Bloemen's mulDiv, MIT).
    function _mulDiv(uint256 a, uint256 b, uint256 d) private pure returns (uint256 result) {
        unchecked {
            uint256 prod0;
            uint256 prod1;
            assembly {
                let mm := mulmod(a, b, not(0))
                prod0 := mul(a, b)
                prod1 := sub(sub(mm, prod0), lt(mm, prod0))
            }
            if (prod1 == 0) return prod0 / d;
            require(d > prod1, "mulDiv");
            uint256 remainder;
            assembly {
                remainder := mulmod(a, b, d)
                prod1 := sub(prod1, gt(remainder, prod0))
                prod0 := sub(prod0, remainder)
            }
            uint256 twos = d & (~d + 1);
            assembly {
                d := div(d, twos)
                prod0 := div(prod0, twos)
                twos := add(div(sub(0, twos), twos), 1)
            }
            prod0 |= prod1 * twos;
            uint256 inv = (3 * d) ^ 2;
            inv *= 2 - d * inv; inv *= 2 - d * inv; inv *= 2 - d * inv;
            inv *= 2 - d * inv; inv *= 2 - d * inv; inv *= 2 - d * inv;
            result = prod0 * inv;
        }
    }
}

contracts/ZetaphyPoints.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title BZTPHY: ZETAPHY testnet reward points
/// @notice People who run ZETAPHY validators and Neuro runners on the testnet earn BZTPHY.
///         When mainnet launches, BZTPHY balances at the freeze become ZETAPHY at mainnet genesis
///         (a share of a fixed pool; see zetaphy-chain/rewards/README.md).
///         BZTPHY cannot be transferred, approved or sold: it shows who did the work, not who bought it.
///         Wallets still show the balance (balanceOf, totalSupply, name, symbol, decimals, Transfer events).
contract ZetaphyPoints {
    string public constant name = "ZETAPHY Testnet Reward Points";
    string public constant symbol = "BZTPHY";
    uint8 public constant decimals = 18;

    address public owner;          // governance: sets the minter, the cap, revokes, freezes
    address public pendingOwner;
    address public minter;         // the daily award job
    uint256 public epochCap;       // most BZTPHY one epoch (UTC day) may award in total
    bool public frozen;            // after the freeze nothing changes: the balances are the snapshot

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(uint32 => uint256) public awardedInEpoch;
    mapping(uint32 => mapping(address => bool)) public awarded;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Awarded(uint32 indexed epoch, address indexed to, uint256 amount, bytes32 reason);
    event Revoked(address indexed from, uint256 amount, bytes32 reason);
    event MinterSet(address minter);
    event EpochCapSet(uint256 cap);
    event OwnershipTransferStarted(address indexed to);
    event OwnershipTransferred(address indexed from, address indexed to);
    event Frozen(uint256 totalSupply);

    error NotOwner();
    error NotMinter();
    error IsFrozen();
    error NonTransferable();
    error LengthMismatch();
    error AlreadyAwarded(uint32 epoch, address to);
    error OverEpochCap(uint32 epoch);
    error ZeroAddress();

    constructor(address owner_, address minter_, uint256 epochCap_) {
        if (owner_ == address(0)) revert ZeroAddress();
        owner = owner_;
        minter = minter_;
        epochCap = epochCap_;
        emit OwnershipTransferred(address(0), owner_);
        emit MinterSet(minter_);
        emit EpochCapSet(epochCap_);
    }

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier notFrozen() {
        if (frozen) revert IsFrozen();
        _;
    }

    /// @notice Awards one epoch's points. Each address gets at most one award per epoch, so a
    ///         job that runs twice cannot pay twice, and an epoch never exceeds epochCap (a stolen
    ///         minter key can mint at most one cap per day, and the owner can revoke it).
    function award(uint32 epoch, address[] calldata to, uint256[] calldata amounts, bytes32 reason) external notFrozen {
        if (msg.sender != minter) revert NotMinter();
        if (to.length != amounts.length) revert LengthMismatch();
        uint256 before = awardedInEpoch[epoch];
        uint256 total = before;
        for (uint256 i = 0; i < to.length; i++) {
            address a = to[i];
            if (a == address(0)) revert ZeroAddress();
            if (awarded[epoch][a]) revert AlreadyAwarded(epoch, a);
            awarded[epoch][a] = true;
            total += amounts[i];
            balanceOf[a] += amounts[i];
            emit Transfer(address(0), a, amounts[i]);
            emit Awarded(epoch, a, amounts[i], reason);
        }
        if (total > epochCap) revert OverEpochCap(epoch);
        awardedInEpoch[epoch] = total;
        totalSupply += total - before;
    }

    /// @notice Takes points back (cheating, e.g. one person running many fake validators).
    function revoke(address from, uint256 amount, bytes32 reason) external onlyOwner notFrozen {
        uint256 b = balanceOf[from];
        if (amount > b) amount = b;
        balanceOf[from] = b - amount;
        totalSupply -= amount;
        emit Transfer(from, address(0), amount);
        emit Revoked(from, amount, reason);
    }

    function setMinter(address m) external onlyOwner notFrozen {
        minter = m;
        emit MinterSet(m);
    }

    function setEpochCap(uint256 cap) external onlyOwner notFrozen {
        epochCap = cap;
        emit EpochCapSet(cap);
    }

    /// @notice Ends the program for good: the balances now are what mainnet genesis uses.
    function freeze() external onlyOwner notFrozen {
        frozen = true;
        minter = address(0);
        emit Frozen(totalSupply);
    }

    function transferOwnership(address to) external onlyOwner {
        pendingOwner = to;
        emit OwnershipTransferStarted(to);
    }

    function acceptOwnership() external {
        if (msg.sender != pendingOwner) revert NotOwner();
        emit OwnershipTransferred(owner, msg.sender);
        owner = msg.sender;
        pendingOwner = address(0);
    }

    // ---- ERC-20 surface that refuses to move points --------------------------------------
    function allowance(address, address) external pure returns (uint256) {
        return 0;
    }

    function transfer(address, uint256) external pure returns (bool) {
        revert NonTransferable();
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert NonTransferable();
    }

    function approve(address, uint256) external pure returns (bool) {
        revert NonTransferable();
    }
}

contracts/ZetaphyPythRelay.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @notice The part of Pyth's IPyth (pyth-sdk-solidity) ZETAPHY reads and writes,
///         with Pyth's own struct layout (PythStructs.Price / PriceFeed): the
///         ABI is the same as the real Pyth contract's, so ZetaphyOracle can be
///         pointed at real Pyth later (ZetaphyOracle.setPyth, through the timelock).
interface IPythLike {
    struct Price {
        int64 price;
        uint64 conf;
        int32 expo;
        uint256 publishTime;
    }
    struct PriceFeed {
        bytes32 id;
        Price price;
        Price emaPrice;
    }
    function getPriceUnsafe(bytes32 id) external view returns (Price memory);
    function getPriceNoOlderThan(bytes32 id, uint256 age) external view returns (Price memory);
    function getEmaPriceUnsafe(bytes32 id) external view returns (Price memory);
    function priceFeedExists(bytes32 id) external view returns (bool);
    function getUpdateFee(bytes[] calldata updateData) external view returns (uint256);
    function updatePriceFeeds(bytes[] calldata updateData) external payable;
}

/// @title ZetaphyPythRelay: Pyth prices on ZETAPHY before Pyth itself is here
/// @notice Pyth has no contract on ZETAPHY yet. Real Pyth checks each update
///         against Wormhole guardian signatures; this relay instead accepts an
///         update only when `threshold` distinct relayers (keys governance names)
///         submitted exactly the same one. Updates use Pyth's public format, the
///         one Pyth's MockPyth.createPriceFeedUpdateData builds:
///             abi.encode(PythStructs.PriceFeed feed, uint64 prevPublishTime)
///         so a relayer forwards what it reads from Pyth (Hermes) unchanged.
///         Like Pyth: an older update than the stored one is ignored (not an
///         error), the PriceFeedUpdate event is Pyth's, and reads revert with
///         PriceFeedNotFound / StalePrice. Unlike Pyth: the update fee is 0 and
///         sending value is refused.
///         Trust: the relayers (and governance, which names them) can publish any
///         price. ZetaphyOracle does not trust it alone: it checks staleness, the
///         confidence interval, the deviation from the DEX TWAP and a circuit
///         breaker. Later, either point ZetaphyOracle at real Pyth, or make a
///         Hyperlane receiver (a contract whose handle() takes Pyth updates from
///         a Hyperlane message out of a chain where Pyth verified them) the only
///         relayer, with threshold 1. Docs: zetaphy-network/README.md (oracle).
///         Governance: the ZetaphyTimelock.
contract ZetaphyPythRelay is IPythLike {
    address public governance;
    mapping(address => bool) public isRelayer;
    uint256 public relayerCount;
    uint8 public threshold;
    /// The furthest in the future a publishTime may be (clock skew).
    uint256 public constant MAX_FUTURE = 60;

    mapping(bytes32 => PriceFeed) private _feeds;
    /// keccak256(update) => relayer => submitted (an update is accepted once threshold relayers sent it)
    mapping(bytes32 => mapping(address => bool)) public submitted;
    /// Who submitted each update, so only those still relayers count
    /// (submissions()): a relayer governance removes no longer counts.
    mapping(bytes32 => address[]) private _submitters;

    event PriceFeedUpdate(bytes32 indexed id, uint64 publishTime, int64 price, uint64 conf);
    event RelayerSet(address indexed relayer, bool on);
    event ThresholdSet(uint8 threshold);
    event GovernanceSet(address governance);
    event Submitted(bytes32 indexed id, bytes32 indexed update, address indexed relayer, uint8 count);

    error NotGovernance();
    error NotRelayer();
    error PriceFeedNotFound();
    error StalePrice();
    error InvalidUpdateData();
    error NoFee();

    constructor(address governance_, address[] memory relayers, uint8 threshold_) {
        require(governance_ != address(0), "governance");
        governance = governance_;
        for (uint256 i = 0; i < relayers.length; i++) _setRelayer(relayers[i], true);
        require(threshold_ >= 1, "threshold");
        threshold = threshold_;
        emit GovernanceSet(governance_);
        emit ThresholdSet(threshold_);
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setRelayer(address who, bool on) external onlyGov { _setRelayer(who, on); }
    function setThreshold(uint8 t) external onlyGov { require(t >= 1, "threshold"); threshold = t; emit ThresholdSet(t); }
    function setGovernance(address g) external onlyGov { require(g != address(0), "governance"); governance = g; emit GovernanceSet(g); }

    function _setRelayer(address who, bool on) private {
        require(who != address(0), "relayer");
        if (on != isRelayer[who]) { if (on) relayerCount += 1; else relayerCount -= 1; }
        isRelayer[who] = on;
        emit RelayerSet(who, on);
    }

    // ---- Pyth's interface ----

    function getUpdateFee(bytes[] calldata) external pure returns (uint256) { return 0; }

    function updatePriceFeeds(bytes[] calldata updateData) external payable {
        if (msg.value != 0) revert NoFee();
        if (!isRelayer[msg.sender]) revert NotRelayer();
        for (uint256 i = 0; i < updateData.length; i++) {
            (PriceFeed memory f, ) = abi.decode(updateData[i], (PriceFeed, uint64));
            if (f.id == bytes32(0) || f.price.publishTime > block.timestamp + MAX_FUTURE) revert InvalidUpdateData();
            if (f.price.publishTime <= _feeds[f.id].price.publishTime) continue; // older or same: ignored, as Pyth does
            bytes32 u = keccak256(updateData[i]);
            uint8 n = submissions(u);
            if (!submitted[u][msg.sender]) {
                submitted[u][msg.sender] = true;
                _submitters[u].push(msg.sender);
                n += 1;
                emit Submitted(f.id, u, msg.sender, n);
            }
            if (n < threshold) continue;
            _feeds[f.id] = f;
            emit PriceFeedUpdate(f.id, uint64(f.price.publishTime), f.price.price, f.price.conf);
        }
    }

    /// How many current relayers submitted this update (keccak256 of it).
    function submissions(bytes32 u) public view returns (uint8 n) {
        address[] storage s = _submitters[u];
        for (uint256 i = 0; i < s.length; i++) if (isRelayer[s[i]]) n += 1;
    }

    function priceFeedExists(bytes32 id) public view returns (bool) { return _feeds[id].price.publishTime != 0; }

    function getPriceUnsafe(bytes32 id) public view returns (Price memory) {
        if (!priceFeedExists(id)) revert PriceFeedNotFound();
        return _feeds[id].price;
    }

    function getEmaPriceUnsafe(bytes32 id) external view returns (Price memory) {
        if (!priceFeedExists(id)) revert PriceFeedNotFound();
        return _feeds[id].emaPrice;
    }

    function getPriceNoOlderThan(bytes32 id, uint256 age) external view returns (Price memory p) {
        p = getPriceUnsafe(id);
        if (block.timestamp > p.publishTime && block.timestamp - p.publishTime > age) revert StalePrice();
    }
}
